pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 12.0; // perfect lookahead fit
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // unless the item fits almost exactly.
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Penalize opening a new bin when decent alternatives exist,
    // but allow it late in the stream or when open bins are very full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open_fill = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let pressure = avg_open_fill * open_bins_count as f64;
        score += 25.0 - 10.0 * progress - 6.0 * pressure;
        if next_item_size > 0 && post_residual >= next_item_size && item_size <= 30 {
            score -= 5.0; // a fresh bin can host a follow-up small item
        }
    }

    // Mild preference for filling fuller bins earlier in the stream.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - t) * 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (prefer tight fits)
    let mut score = pr;

    // Smooth polynomial coupling: residual value decays with progress,
    // so late in the stream we penalize leftover space more aggressively.
    let decay = 1.0 - progress * progress;
    score -= 12.0 * pr * norm_pr * decay;

    // Non-linear reward for exact/near-exact fits (post_residual near 0)
    let tightness = (1.0 - norm_pr).powi(6);
    score -= 8.0 * tightness * item_size as f64 / cap;

    // Penalize dead space that cannot fit the next item (smooth quadratic gap term)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let gap_frac = gap / cap;
        score += 15.0 * gap_frac * gap_frac * (0.5 + progress);
        // Reward bins whose post-residual still accommodates the lookahead item
        if pr >= next_item_size as f64 {
            score -= 4.0 * (next_item_size as f64 / cap) * (1.0 - progress);
        }
    } else {
        // Last item: strongly prefer zero residual
        score += 20.0 * norm_pr * norm_pr;
    }

    // Last-chance bin bonus (avoid opening a new bin when this is the only fit)
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins early (encourages consolidation)
    let open_frac = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 3.0 * open_frac * norm_pr * (1.0 - progress);

    // Mean-residual coupling: prefer bins close to the mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.01;

    // New-bin candidate: penalize opening a fresh bin unless residual savings are large
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= cap {
            score += 8.0; // item would pair well with next item elsewhere
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the resulting residual: residual classes mod 10 ---
    // Small residuals are "dead space"; penalize classes that are hard to fill.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Residuals like 1..9 (non-decade) are dead unless a tiny item arrives.
        // Penalize proportionally to how far the class is from a "usable" decade.
        if pr < 10 {
            // Dead space: nearly unusable (min item size 1..100 unknown, but small)
            score += 30.0 - 3.0 * class as f64;
        } else {
            // Non-decade residuals waste potential; decade residuals align with
            // typical item sizes (multiples of 10).
            if class != 0 {
                score += 2.0 + (10 - class) as f64 * 0.3;
            } else {
                score -= 4.0; // decade residual: harmonically clean
            }
        }
    } else {
        // Perfect fit: zero residual, best possible outcome.
        score -= 50.0;
    }

    // --- Harmonic class of item size relative to capacity ---
    // Items that are divisors/multiples of capacity harmonics fit cleanly.
    let cap_frac = item_size as f64 / bin_capacity as f64;
    if cap_frac > 0.5 {
        // Large item: placing it now is urgent; reward fitting it tightly.
        score -= 10.0 * cap_frac;
    }

    // --- Integer division threshold: can post_residual host the next item? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain friendly: this bin can host the lookahead item too.
            score -= 8.0;
            // Extra reward if the chain is tight (next item nearly fills remainder).
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 6.0;
            }
        } else {
            // Chain breaks: residual too small for next item.
            score += 5.0;
        }
    } else {
        // Last item: just minimize residual; already handled by base term.
        score -= 1.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin fits; opening a new bin would waste this residual.
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Many options: prefer tightest fit; base post_residual term suffices,
        // but slight penalty for spreading across too many bins.
        score += 1.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of +100 residual must be offset only when
        // current open bins have bad (small) residuals.
        score = 100.0 - 0.5 * mean_residual - (open_bins_count as f64) * 2.0;
        // If no open bin fits (last chance belongs to new bin), it's fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in stream, prefer reusing existing bins to avoid stranding.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter) ---
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // --- Progression-aware pressure: as stream ends, avoid opening slack ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over
    let class = (frac * 10.0).floor(); // 0..10 harmonic class

    // Penalize residuals in awkward harmonic classes (small but unusable leftovers).
    // Class 0: perfect fit -> huge reward. Classes 1-3: dead space -> penalize extra.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score += 40.0; // tiny dead space, bad
    } else if post_residual <= 15 {
        score += 15.0;
    } else if post_residual <= 25 {
        score += 5.0;
    } else {
        // larger residuals are more reusable: mild reward scaling
        score -= 10.0 * (1.0 - frac);
    }

    // Integer-division threshold: residual divisible into common item sizes is good.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 12.0; // round residual, easy to fill later
    }
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0; // keeps the chain going
            // exact harmonic match with next item
            if next_item_size == post_residual {
                score -= 50.0;
            }
            // next item divides residual into round pieces
            let rem2 = post_residual - next_item_size;
            if rem2 == 0 {
                score -= 60.0;
            }
        } else {
            // next item won't fit here; residual should still be "harmonically useful"
            score += 8.0;
        }
    } else {
        // last item: prefer perfect fill
        score -= 20.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // with alternatives, prefer tighter fits more aggressively
        score += 3.0 * (fitting_bins_count as f64).min(5.0);
    }

    // New-bin candidate handling: only open a new bin when the item fits badly
    // everywhere (large item relative to mean residual) or early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = (item_size as f64) > mean_residual * 0.9;
        if bad_fit || open_bins_count == 0 || progress < 0.02 {
            score -= 25.0; // opening fresh is attractive
        } else {
            score += 60.0; // discourage wasting fresh capacity
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Progress-based tie-breaker: later in the stream, squeeze harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Moderate residual is somewhat usable; large residual is fine (kept for future items).
    if post_residual >= 30 {
        score -= 8.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but allow new bin when the fit would create bad dead space.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item would be blocked by this placement creating tiny gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: prefer reusing a decent bin over opening a new one,
    // unless the best reuse would waste space. New bin gets a mild fixed cost.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.3;
        // If item is small relative to capacity, opening a fresh bin wastes potential.
        if item_size < 40 {
            score += (40 - item_size) as f64 * 0.8;
        }
        // Late in the stream, opening new bins is less costly (fewer future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Mean-residual coupling: if open bins are generally tight, avoid wasting this bin's space.
    if bin_residual < bin_capacity && (mean_residual - post_residual as f64) > 40.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 8.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Deviation from mean residual: prefer bins close to mean (balanced packing),
    // but avoid leaving large residuals when mean is small.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: make it attractive only when existing bins would leave bad gaps.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by avoiding dead space.
        score = 45.0 + 0.3 * open_bins_count as f64;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
        if item_size >= 50 {
            score -= 8.0; // large items fit well in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host a
    // typical future item are unusable gaps -> penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // If the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover: mild penalty unless
        // leftover is still large enough to be generally useful.
        if post_residual < 30 {
            score += 12.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when this bin
    // would leave a bad gap or open bins are already numerous.
    if bin_residual == bin_capacity {
        score += 10.0;
        if post_residual < 20 {
            score += 35.0;
        }
        score += open_bins_count as f64 * -0.3;
    }

    // Slight preference for tighter-than-average bins.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Non-linear coupling of post-residual with stream progress:
    // early on, tolerate residual waste; later, penalize it quadratically
    score += norm_pr * progress * progress * cap * 0.02;

    // Smooth interaction: post_residual vs mean residual (avoid outliers vs average state)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 3.0 - dev * 1.5;

    // Last-chance bonus: smooth sigmoid-like reward when few fitting bins
    let fit = fitting_bins_count as f64;
    let scarcity = 1.0 / (1.0 + fit * fit);
    score -= scarcity * 2.5 * (1.0 + progress);

    // Lookahead coupling: reward if next item fits the post-residual (smooth kernel)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 1.8 * slack * slack;
    } else if next_item_size > 0 {
        // penalize blocking the next item, smoothly by overshoot
        let over = (next_item_size as f64 - pr) / cap;
        score += 1.2 * over * over;
    }

    // Mild preference for keeping fewer open bins when bins are crowded
    score += (open_bins_count as f64) * 0.005 * (1.0 - progress);

    score
}

