    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Mean residual coupling: if average leftover is large, favor bins below mean
    // (consolidate), penalize bins far above mean (fragmenting).
    if mean_residual > 0.0 {
        let diff = post_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual < 15 {
            score -= 20.0; // near-perfect fill on last chance
        }
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Make it attractive only for large items or when it would leave a large,
    // flexible gap while other bins are tight.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so full bins usually win
        score += 25.0;
        if item_size >= 60 {
            score -= 20.0; // big items are fine in a fresh bin
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual >= 40 {
            score -= 18.0; // fresh bin can host the next item too
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: prefer bins whose post-residual exactly
    // matches the next item (perfect chain), or fits it tightly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward
        if diff == 0.0 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to tightness of fit
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leftover dead space
            score += 10.0 + diff / 10.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // already "tight"; filling them is good, penalize if it creates waste.
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 5.0;
    } else if (post_residual as f64) > mean_residual * 1.5 {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when it enables a great future chain
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && bin_capacity as i64 - next_item_size as i64 == item_size as i64 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Strongly reward tight fits (small post_residual relative to item).
    let tightness = 1.0 - (post / cap);
    score -= tightness * item_size as f64 * 0.8;

    // Penalize dead space that nothing small can use: post_residual below the
    // minimum plausible item size is wasted, above it is reusable.
    if post_residual < 10 && bin_residual != bin_capacity {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is excellent.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if nxt <= post {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 6.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented (high mean residual spread) or the
    // item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / cap - post / cap).abs();
        score += 35.0;
        score -= item_size as f64 * 0.3;
        score -= fragmentation * 20.0;
        score -= open_bins_count as f64 * 0.5;
        // late in stream, prefer consolidating into open bins
        score += progress * 20.0;
    }

    // Prefer filling bins that are already mostly full (low residual) to
    // consolidate waste.
    let fill_ratio = 1.0 - (bin_residual as f64 / cap);
    score -= fill_ratio * fill_ratio * 15.0;

    // Mild penalty for bins whose residual deviates far from the mean,
    // keeping the bin pool homogeneous.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference to use many open bins efficiently when few remain
    // able to fit future large items.
    if open_bins_count > 3 {
        score += 0.2 * open_bins_count as f64 * (post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling: post_residual value decays with progress
    score -= 40.0 * norm_pr.powf(2.0) * (1.0 - progress);
    score += 25.0 * norm_pr.powf(3.0) * progress;
    // Interaction with mean residual: prefer bins near mean residual
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;
    // Last-chance bonus, scaled smoothly by tightness
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }
    // Lookahead: reward residual that could fit next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - (pr / next_item_size.max(1) as f64).min(1.0));
    }
    // Penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).sqrt();
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // "harmonically usable" buckets (multiples of common item classes).
    let pr = post_residual;
    let pr_class = pr / 10; // integer division thresholds on post_residual
    let harmony = match pr_class {
        0 => 3.0,        // dead space <= 9: nearly perfect fit, reward heavily
        1 => 1.5,        // 10..19: fits a small item class
        2 => 1.0,        // 20..29: fits a medium class
        3 => 0.5,        // 30..39
        4 => 0.0,        // 40..49: neutral zone
        5 => -0.5,       // 50..59: large leftover, still flexible
        6 => -1.0,       // 60..69
        _ => -1.5,       // >=70: bin barely used, very flexible
    };
    score -= harmony * 4.0;

    // Modulo arithmetic: leftover that is a multiple of common sizes (10, 20, 25, 50)
    // is more likely to be filled later by future items.
    let mod_bonus = if pr == 0 { 2.0 }
        else if pr % 10 == 0 { 1.0 }
        else if pr % 25 == 0 { 0.8 }
        else if pr % 5 == 0 { 0.4 }
        else { 0.0 };
    score -= mod_bonus * 3.0;

    // Lookahead coupling: does post_residual exactly admit the next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 8.0; // perfect chained fit
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 10 { score -= 4.0; }
            else if slack <= 25 { score -= 2.0; }
        } else {
            // next item cannot use this bin's leftover; slight penalty
            score += 1.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual;
    // penalize it so it is only chosen when open bins are truly bad fits.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if current item is large and mean residual is small, new bin
        // becomes attractive: reduce the penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size as f64 > mean_residual + 15.0 {
            score -= 9.0 + 3.0 * progress;
        }
    }

    // Prefer filling bins with below-average residual (tighter bins first),
    // keeping looser bins available for future items.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Slight preference for bins whose post_residual falls into "harmonic"
    // half-capacity classes (25/50/75), which pair well with many item sizes.
    if pr == 50 || pr == 25 || pr == 75 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: strongly reward zero post residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // If the next item can fit exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra bonus for an exact follow-up fit.
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit in leftover: mild penalty for creating a trap.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    if bin_residual == bin_capacity {
        // Candidate is a brand-new bin: penalize it, more so with more open bins.
        score += 20.0 + 5.0 * open_bins_count as f64;
        // Late in the stream, new bins are especially wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If an existing bin would leave a tiny dead gap, allow new bin to win:
        // handled naturally by the dead-space penalties above.
    } else {
        // Favor filling bins with larger residual (more room to consolidate).
        score -= 0.05 * bin_residual as f64;
        // Slight preference for bins whose residual is close to mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.02 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Slack after hypothetically placing the next item too.
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0);
        // Perfect chain (post_residual == next_item_size) is best.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable leftovers.
        score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.8;
    }

    // Compare against mean residual: bins tighter than average are more valuable to fill.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: penalize so we only open when open bins are truly bad fits.
    if bin_residual == bin_capacity {
        score += 70.0;
        // But allow early stream opening when few bins exist and item is large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > bin_capacity / 2 && progress < 0.1 {
            score -= 40.0;
        }
    }

    // Prefer filling bins with small residuals (low waste potential).
    if bin_residual < 20 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 30.0 / (1.0 + post_residual as f64);

    // Penalize dead space relative to capacity, especially small leftovers
    // that no future item (min size 1) can still waste value on.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 / (1.0 + slack as f64);
            if slack == 0 {
                score -= 35.0; // perfect chain fit
            }
        } else {
            // Next item won't fit here; mild penalty if this bin becomes a stranded small gap.
            score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin is attractive early in the stream
    // or when many items remain, since future items can fill fresh capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let horizon_value = (1.0 - progress) * (total_items as f64).ln_1p().min(4.0);
        // Prefer new bin when mean residual of open bins is low (poor overall state)
        // or when this item is large (hard to place later).
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 15.0;
        score -= horizon_value * 6.0 + large_item_bonus + (mean_residual < 15.0) as i32 as f64 * 10.0;
        // Discard new-bin option late in stream when decent fits exist.
        if progress > 0.8 && post_residual == 0 {
            score += 40.0;
        }
    }

    // Congestion control: many open bins with high mean residual -> consolidate,
    // favor bins below mean residual (tighter bins).
    if open_bins_count > 3 {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.3;
    }

    // Prefer bins whose residual stays "useful" (>= typical item scale).
    if post_residual >= 40 {
        score -= 6.0;
    } else if post_residual >= 20 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_frac = post / cap;

    // Base: reward tight fits via non-linear decay of post residual.
    let mut score = (post_frac * std::f64::consts::PI).sin().abs() * cap * 0.5 + post;

    // Smooth polynomial coupling: tight fits matter more as stream progresses.
    let tightness = 1.0 - post_frac;
    score -= progress * tightness * tightness * cap * 0.6;

    // Penalize dead space that can't fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).max(0.0) / cap;
        score += gap * gap * cap * (0.5 + progress);
        // Reward leaving exactly-enough room for the next item.
        let fit_next = ((post - nxt).abs()) / cap;
        score -= (1.0 - fit_next) * (1.0 - fit_next) * 8.0 * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when bin is far below mean residual (fragmentation risk).
    score += ((mean_residual - post) / cap).max(0.0) * 3.0;

    // Prefer filling nearly-full bins (smooth quadratic reward).
    score -= (1.0 - post_frac) * (1.0 - post_frac) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: divide capacity into octiles.
    // Residuals in the lowest octile are near-dead space; penalize them hard.
    let octile = post_residual / (bin_capacity / 8);
    match octile {
        0 => score += 60.0,                    // 0..12 : nearly dead space
        1 => score += 25.0,                    // 13..24
        2 => score += 8.0,                     // 25..36
        3 => score -= 0.0,                     // 37..49 neutral
        4 => score -= 5.0,                     // 50..61
        5 => score -= 10.0,                    // 62..74
        6 => score -= 14.0,                    // 75..86
        _ => score -= 18.0,                    // 87..99 : excellent leftover
    }

    // Lookahead compatibility: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly: next item can follow in this bin. Reward,
            // stronger when the next item nearly fills the leftover.
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * chain_tightness;
        } else {
            // Next item cannot use this leftover: dead space risk grows
            // with how small the leftover is relative to typical items.
            score += 10.0 * (1.0 - post_residual as f64 / 100.0);
        }
    }

    // Tight fit reward: exact or near-exact fills are always great.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid forcing
    // a new bin unless the fit is terrible (huge post residual penalty already applies).
    if fitting_bins_count == 1 && post_residual < bin_capacity / 2 {
        score -= 15.0;
    }

    // Prefer reusing bins whose residual is already small (consolidate waste)
    // rather than fragmenting many half-empty bins.
    score -= 0.05 * (mean_residual - post_residual as f64).abs();

    // Mild preference for keeping the number of open bins low early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item (1..=MIN_GAP) are pure waste. Penalize them heavily.
    let min_gap: u32 = 10;
    if post_residual > 0 && post_residual < min_gap {
        score += 60.0 * (1.0 + (min_gap - post_residual) as f64 / min_gap as f64);
    } else if post_residual == 0 {
        // Perfect fill is the ideal outcome: strong reward.
        score -= 40.0;
    } else {
        // Usable residual: mild reward for tighter fit, scaled by item size share.
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 15.0 * tightness;
    }

    // Post-residual exactly matching the lookahead item is highly desirable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that cannot fit the next item but could have.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // flexibility bonus: bin stays useful
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // this bin becomes dead for the lookahead
    }

    // Open-bin pressure: discourage scattering across many open bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit = (bin_capacity - item_size) <= min_gap || fitting_bins_count == 0;
        if decent_fit {
            score -= 20.0;
        } else {
            score += 25.0 + 3.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward chains: tighter post_residual relative to next item is better
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
        } else {
            // Next item won't fit here; penalize wasted residual that could have hosted it
            score += 25.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when open bins exist that fit reasonably
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 70.0 - progress * 20.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Penalize creating tiny unusable dead space (1..=5)
    if post_residual > 0 && post_residual < 6 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize very small dead space only if it can't plausibly host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual >= next_item_size / 2 {
            score += 4.0; // awkward leftover
        }
    }

    // Last chance: this is the only bin that fits; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global pressure: many open bins with small mean residual -> consolidate.
    let pressure = mean_residual / bin_capacity as f64;
    score += 10.0 * pressure;

    // Time horizon: early in stream, be more willing to open new bins (keep options);
    // late in stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized later.
        score -= 20.0 * (1.0 - progress);
        score += 15.0 * progress;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        score -= 8.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let it = item_size as f64;

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post residual with stream progress.
    // Early on, keep bins flexible; late in the stream, aggressively fill bins.
    let fill_bias = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 + 6.0 * progress);
    score += 30.0 * fill_bias;

    // Reward high fill ratio with a smooth cubic term scaled by progress.
    let fill_ratio = 1.0 - pr_norm;
    score -= fill_ratio * fill_ratio * fill_ratio * (10.0 + 20.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: reward if next item fits in the post residual (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        let tight = (pr - nxt).abs() / cap;
        score -= 12.0 * (1.0 - tight * tight) * (1.0 - fits) * (0.5 + progress);
        // Penalize blocking the next item entirely.
        if nxt > pr {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading items across too many bins relative to mean residual.
    let mean_norm = mean_residual / cap;
    score += 3.0 * (pr_norm - mean_norm).abs() * (1.0 - progress);

    // Small tie-breaker on residual to prefer fuller bins among equals.
    score += 0.01 * pr_norm * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Dead-space penalty: leftover that is too small to hold any item is pure waste.
    // Items range 1..100, but small leftovers (<~10) are hard to fill; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_f / 10.0);
    }

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic pairing: reward when the next item can exactly fill the post_residual
    // (residual + next item = perfect harmonic class match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits here later: mild reward proportional to tightness.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap_f;
            score -= 30.0 * tight;
        } else {
            // Next item cannot use this leftover: penalize large stranded residuals.
            score += 0.15 * post_f;
        }
    }

    // Modulo-class logic: leftover divisible into nice chunks (multiples of 10)
    // is more reusable than awkward leftovers.
    let awkward = (post_residual % 10 != 0) as f64;
    score += 8.0 * awkward * (post_f / 100.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a
    // decent fit (e.g., item barely fits or leftover would be stranded).
    if bin_residual == bin_capacity {
        // Base score for a fresh bin: its post_residual equals capacity - item.
        score = (bin_capacity - item_size) as f64;
        // Penalize opening a new bin when good alternatives exist.
        if fitting_bins_count > 0 {
            let best_case_tight = (bin_residual - item_size) as f64 / cap_f;
            score += 40.0 * (1.0 - best_case_tight);
        }
        // If next item is huge and current leftover would be stranded, new bin helps.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 25.0;
        }
        if post_residual == 0 {
            score -= 200.0;
        }
    }

    // Slight preference to fill bins with smaller residuals first (tightest fit),
    // via coupling with mean residual across open bins.
    score += 0.05 * (post_f - mean_residual).max(0.0);

    // Mild stream-progression pressure: late in the stream, prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or below min item size)
    // are heavily penalized so we never strand tiny residuals unless forced.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    } else {
        // Mild convex penalty on leftover space to prefer tight fits
        score += 0.05 * (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more when few bins are open
    // or when an open bin can accept the item reasonably well.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 15.0 + 2.0 * open_bins_count as f64;
        // Allow opening a new bin late in the stream when residuals are fragmented
        if open_bins_count > 3 && mean_residual < 20.0 {
            score -= 25.0;
        }
    }

    // Open-bin pressure: discourage scattering items across many bins
    score += 0.15 * open_bins_count as f64;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match with next item is highly desirable
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // bin becomes exactly reusable for the next item
        } else if post_residual > next_item_size {
            score -= 30.0; // next item still fits here afterwards
        } else {
            // next item would NOT fit in this bin afterwards
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize large dead space relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // Mild pressure to close bins that are nearly full (good packing)
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // Progression: later in stream, prefer tighter fits more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    // New-bin candidate: only attractive when current item fits poorly everywhere
    if bin_residual == bin_capacity {
        // opening new bin costs; make it unattractive unless lookahead says otherwise
        score += 250.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 100.0; // fresh bin helps chain future items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that nothing (in the 1..100 range) can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual >= 60 {
        score += 15.0; // leaving a big hole
    }

    // Lookahead: reward if next item can fit into the post-residual (chaining placements).
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let chain_tightness = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 20.0 * chain_tightness;
        } else {
            // Next item won't fit here; penalize wasting residual that could have held it.
            score += 0.15 * next_item_size as f64;
        }
    } else {
        // Last item: just fill as much as possible.
        score -= 30.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well. Since the new bin has bin_residual == bin_capacity, its post_residual
    // is large; add a mild penalty that shrinks as the stream progresses and mean
    // residual across open bins is high (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 35.0 - 20.0 * fragmentation - 10.0 * progress;
        // If item is large, a fresh bin is actually good (big items define bin structure).
        if item_size >= 50 {
            score -= 25.0;
        }
        // If several bins fit the item, discourage spawning yet another bin.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Global pressure: when many bins are open, prefer consolidating into existing bins.
    score += 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Mean residual coupling: prefer bins below mean residual (tighter bins first),
    // leaving looser bins for future flexibility.
    score += 0.2 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Time horizon: early in the stream, keep bins open/flexible; late, squeeze hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress and post-residual fraction (smooth couplings)
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = (post_residual as f64 / cap).clamp(0.0, 1.0);
    let item_frac = (item_size as f64 / cap).clamp(0.0, 1.0);

    // Non-linear fit reward: strongly favor small post_residual, amplified late in stream
    let tight_fit = (1.0 - pr) * (1.0 - pr);
    score -= 30.0 * tight_fit * (0.4 + 0.6 * progress);

    // Penalize dead space: post_residual too small for the smallest plausible item (1..100 range)
    // Smooth dead-space penalty peaking when post_residual is tiny but nonzero
    if post_residual > 0 {
        let dead = 1.0 - (pr / 0.10).min(1.0);
        score += 25.0 * dead * dead * (0.3 + 0.7 * progress);
    }

    // Interaction: item size vs post residual — prefer bins where the item fills a large
    // fraction of the residual (smooth ratio coupling)
    if bin_residual > 0 {
        let fill_ratio = item_frac / (bin_residual as f64 / cap);
        score -= 15.0 * fill_ratio * (1.0 - fill_ratio) * 4.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: only one bin fits the item — avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: if next item fits smoothly in the post residual, reward it
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let next_pr = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - next_pr) * (1.0 - next_pr);
    }

    // New-bin candidate: penalize opening a new bin, more strongly early in the stream
    // and when many bins are already open; relax late when mean residual is high (fragmentation)
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 35.0 * (1.0 - progress) + 20.0 * (1.0 - fragmentation).max(0.0);
        // But late in the stream with high mean residual, opening a fresh bin is cheap
        score -= 30.0 * progress * fragmentation * fragmentation;
    }

    // Mild penalty for spreading across too many open bins relative to progress
    score += 0.5 * (open_bins_count as f64 / (1.0 + progress * 10.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 create
    // "compatibility classes" with typical item sizes (multiples of 10).
    let residue_class = (post_residual % 10) as f64;
    // Penalize post residuals that are neither 0 (perfect fit) nor large
    // enough to be reusable. Class 0 is golden; classes 1..5 are dead zones.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        score += residue_class * 1.5;
    }

    // Dead-space threshold: post_residual too small for smallest item (1..=9
    // or < next item) is wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward bins that can host the next item too (chained fit),
            // especially when the chain is tight (small leftover after both).
            let chain_left = post_residual - next_item_size;
            score -= 12.0;
            score += (chain_left % 10) as f64 * 0.8;
            if chain_left == 0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here; penalize more if the gap is small
            // (near miss creates tempting dead space).
            let gap = next_item_size - post_residual;
            if post_residual > 0 && gap <= 10 {
                score += 8.0 + gap as f64;
            } else {
                score += 4.0;
            }
        }
    }

    // Integer-division thresholds on post_residual: classify reusability.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual >= half {
        score -= 6.0; // half-full or more room: very reusable
    } else if post_residual >= quarter {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 5.0; // cramped quarter: low utility
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins overall: compare against mean residual of open bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Stream progression: late in the stream, consolidation matters more;
    // early on, allow spreading into fresh bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized later, and
        // penalized when many bins are already open.
        score = 60.0 - progress * 25.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size.saturating_mul(2).min(bin_capacity) {
            score -= 5.0; // big follow-up item: fresh bin gives room
        }
    } else if progress > 0.7 {
        // Late stream: reward tight fits extra.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Harmonic tie-breaker: multiples of 10 in post_residual are ideal
    // partners for future items; odd/misaligned residuals get a nudge.
    if post_residual % 5 != 0 && post_residual > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely attractive.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small leftovers that likely can't host future items.
    let tight = (bin_capacity as f64).sqrt(); // ~10 for C=100
    if post_residual > 0 && (post_residual as f64) < tight {
        score += 3.0 * (tight - post_residual as f64);
    }

    // Reward leaving room for the lookahead item if it would fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0 * (next_item_size as f64) / 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 1.5; // blocks the next item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer spreading when many bins are open.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: only attractive when it produces a large useful residual
    // relative to current mean residual (i.e., existing bins are nearly full).
    if bin_residual == bin_capacity {
        let pr = post_residual as f64;
        if pr < mean_residual {
            score += 40.0; // existing bins fit better; don't open a new bin
        } else {
            score -= 5.0 + 0.1 * pr;
        }
    }

    // Mild stream-progression bias toward consolidating late in the stream.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 2.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit lookahead: perfect match with the next item is a jackpot.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item still fits comfortably.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
    }
    // Penalize dead space that no item (min size 1..10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score -= (mean_residual - post_residual as f64) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless it is genuinely needed.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 35.0 - 40.0 * pressure;
        // A fresh bin is attractive when lookahead item is large and current
        // open bins would be fragmented by this placement.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 15.0;
        }
    }

    // Late in the stream, consolidate harder into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // next_item_size is wasted. Penalize residuals that no future item can use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // lookahead item can land here
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35; // dead space risk
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 8.0;

    // Global pressure: many open bins relative to progress -> encourage
    // packing into existing bins; few bins -> opening new ones is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 0.4;

    // Mean residual coupling: if mean residual is large, spread is fine;
    // if small, we must be frugal with existing space.
    score += (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate handling: empty bin gets a moderate penalty so it
    // only wins when open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 10.0 + progress * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // fresh bin also suits the upcoming item
        }
    }

    // Late-stream frugality: penalize wasteful placements near the end.
    score += post_residual as f64 * (0.05 + 0.15 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth polynomial base: reward tight fits via quartic shaping of post_residual
    let mut score = 4.0 * x * (1.0 - x) * cap + x * x * cap;

    // Non-linear coupling with stream progress: later in stream, prefer tighter packing
    let progress_coupling = (1.0 - progress) * (1.0 - progress);
    score += 12.0 * progress_coupling * pr;

    // Penalize dead space relative to mean residual (smooth interaction)
    score += 0.35 * (pr - mean_residual).abs() * (1.0 + x);

    // Lookahead coupling: reward leaving space for next item smoothly
    let ns = next_item_size as f64;
    if ns > 0.0 {
        let gap = pr - ns;
        let smooth = gap / (gap * gap + 25.0).sqrt();
        score -= 8.0 * smooth;
    }

    // Last-chance bonus: strong but smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - x * x);
    }

    // Mild penalty for bin scarcity pressure
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * pr * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a small residue
    // modulo common item-size classes is less recoverable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Penalize small-but-nonzero post residuals (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic classes: post_residual mod 10 / mod 5 buckets.
    let m10 = (post_residual % 10) as f64;
    let m5 = (post_residual % 5) as f64;
    score += 0.6 * m10 + 0.3 * m5;

    // Integer-division thresholds on post_residual: residuals in ranges
    // that cannot fit any likely item (1..10, 11..20) are penalized;
    // residuals >= 50 remain highly usable.
    if post_residual >= 1 && post_residual <= 20 {
        score += 12.0;
    } else if post_residual >= 21 && post_residual <= 34 {
        score += 4.0;
    } else if post_residual >= 50 {
        score -= 6.0;
    }

    // Perfect fits / near-perfect fits are excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Extra reward if next item exactly fills remaining space.
            if next_item_size == post_residual {
                score -= 12.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Give empty bins a mild default
    // score tied to stream progress and current bin count.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.5 * cap + 10.0 * progress + 2.0 * open_bins_count as f64;
        // If item is large relative to capacity, new bin is more attractive.
        score -= 0.2 * item_size as f64;
        // If many open bins have high mean residual, prefer existing bins.
        score += 0.3 * (mean_residual - 0.5 * cap).max(0.0);
    }

    // Slight preference for tighter bins overall.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (1..10) are wasted; penalize hard as post_residual approaches that zone.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable dead space
        } else if post_residual < 20 {
            score += 18.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 2.5 * open_bins_count as f64;
        // But if this bin would leave a perfect fit for the lookahead item, ease up
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
    }

    // Lookahead: reward leaving exactly the next item's size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + gap);
    }

    // Early in the stream, allow slightly more freedom; later, be strict
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (consolidate large gaps)
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // exact chain fit: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 250.0;
        }
        // penalize dead space the next item can't use
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    score += 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when existing bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // open a new bin when open bins are mostly full / fragmented
        score = 200.0 + 150.0 * fragmentation + 100.0 * progress;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 50.0;
        }
    }

    // mild penalty for wasting a large residual on a small item
    score += 0.1 * (item_size as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit), scaled slightly.
    score *= 1.0 + 0.05 * (1.0 - item_size as f64 / bin_capacity as f64);

    // Lookahead: reward bins whose post-residual can host the next item (k=2 chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.25 * next_item_size as f64;
        // Extra bonus if the pair nearly fills the bin exactly.
        let pair_waste = post_residual - next_item_size;
        score -= 10.0 * (1.0 - pair_waste as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize stranding space the next item can't use.
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: only one bin fits the item; using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Dead-space penalty: post-residual too small to ever fit (min item size 1,
    // but below ~10 it's nearly unusable given typical distributions).
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    }

    // Perfect fit celebration.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: neutral-to-slightly-penalized baseline; open a new bin
    // preferentially for large items or when existing bins would waste badly.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Large items justify fresh bins; small items should reuse.
        score -= 0.45 * item_size as f64;
        // Late in the stream, discourage spawning bins for marginal gains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If many bins are already open with slack, prefer reusing them.
        if mean_residual > item_size as f64 {
            score += 8.0;
        }
    }

    // Global congestion coupling: when many bins are open, favor consolidation
    // into bins with above-average residual (keeps few large gaps alive).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress.
    // Early on, prefer tight fits less aggressively; late, chase tight fits hard.
    let mut score = pr * (1.0 + 1.5 * progress) - 40.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Smooth cubic coupling: reward near-zero post residual increasingly with progress.
    score -= 25.0 * (1.0 - norm_pr).powi(3) * progress;

    // Penalize dead space relative to mean residual (smooth interaction).
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1e-9 {
        score -= 80.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        // Smooth partial reward for leaving room usable by next item.
        score -= 20.0 * (next_item_size as f64 / pr.max(1.0)) * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize post residuals that strand the next item.
        score += 10.0 * progress * (1.0 - pr / cap);
    }

    // Mild penalty for proliferating bins early (prefer consolidation).
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10 (item granularity).
    let r = post_residual % 10;
    // Small residues (1..9) are dead space; large residues (0) are perfect fits.
    let dead = (10 - r) as f64 / 10.0; // 1.0 for r=9 (worst), 0.1 for r=1
    score += dead * 8.0;

    // Integer-division thresholds on post_residual: bins leaving <=10 residual are excellent.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual > 50 {
        score += 6.0; // leaving half a bin free is wasteful
    }

    // Capacity fraction coupling: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Lookahead harmony: does post_residual exactly accommodate next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Harmonic if slack is a small multiple of 10
            if slack % 10 == 0 {
                score -= 6.0;
            } else {
                score += (slack % 10) as f64 * 0.5;
            }
            // Penalize leaving just barely enough for the next item if it creates tiny residue
            if slack > 0 && slack < 5 {
                score += 4.0;
            }
        } else {
            // Next item won't fit here anyway; a near-perfect close is fine.
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64 * 10.0 + 1.0);
        score += 18.0 - crowd.min(18.0);
        // If item is huge relative to capacity, new bin is more attractive
        if item_size >= bin_capacity * 3 / 4 {
            score -= 8.0;
        }
    }

    // Stream progression: later in stream, be slightly greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual context: if open bins are generally tight, value tight fits more.
    if (mean_residual as u32) < 25 && post_residual < 25 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space that cannot fit the next item is worse.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Tiny gaps (<10) are essentially unusable dead space.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strong preference to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless this item would leave a very poor fit in every open bin.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // keep large contiguous space for large upcoming items
        }
    }

    // Lookahead: reward bins whose post-residual still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Late-stream urgency: fill bins tighter as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: this bin's leftover exactly
    // accommodates the next item, chaining two placements into one bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Partial lookahead: next item fits in the post-residual space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Bonus scaled by how tightly the next item nests in the leftover.
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Post-residual is dead space for the next item: penalize proportionally.
        let unusable = post_residual.min(next_item_size - 1) as f64;
        score += 6.0 * (unusable / bin_capacity as f64);
    }

    // Prefer bins tighter than average (best-fit style), penalize loose bins.
    score -= 0.5 * (mean_residual - bin_residual as f64);
    score += 0.3 * (bin_residual as f64 - post_residual as f64).abs().max(0.0) * 0.0; // no-op guard

    // Last-chance bin: if this is the only bin that can fit, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current item is large relative to
    // capacity (poor fit elsewhere) or many bins already open with small residuals.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * large_item;
        score += 8.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count > 0 {
            // Good fits exist elsewhere; make the new bin less attractive.
            score += 25.0;
        }
        // Early in stream, fresh bins are cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness * tightness;

    // Penalize leaving awkward small residuals that few future items can use.
    if post_residual > 0 {
        let frag = 1.0 - (post_residual as f64 / bin_capacity as f64);
        if post_residual < 10 {
            score += 12.0; // tiny unusable sliver
        } else {
            score += 4.0 * frag;
        }
    } else {
        score -= 25.0; // perfect fill: excellent
    }

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0; // next item won't fit here after placement
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer filling bins that are already relatively empty (consolidate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Late in the stream, avoid opening new bins; squeeze into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when many bins open / early stream.
        score += 15.0 + 25.0 * (1.0 - progress);
        score += open_bins_count as f64;
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post_residual (tight fit), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Smooth polynomial coupling of tightness with stream progress:
    // early on, waste matters less; later, demand very tight fits.
    let progress_coupling = 1.0 + 2.0 * progress * (1.0 - x) * (1.0 - x);
    score *= progress_coupling;

    // Perfect-fit reward (smooth gaussian-like bump near x=0)
    score -= 15.0 * (-x * x / 0.005).exp();

    // Penalty for leaving dead space that nothing typical can use:
    // smooth trough around x = 0.1..0.2 (dead zone), reward larger usable residuals
    let deadness = (-(x - 0.15) * (x - 0.15) / 0.01).exp();
    score += 10.0 * deadness * (1.0 - progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (smooth)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (-gap * gap / 50.0).exp();
    }

    // Mild penalty when this bin is far above mean residual (fragmentation)
    score += 0.05 * (pr - mean_residual).abs();

    // Encourage closing nearly-full bins: slightly reward low post residual
    score -= 0.02 * (cap - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the resulting residual: residual classes mod 10 ---
    // Small residuals are "dead space"; penalize classes that are hard to fill.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Residuals like 1..9 (non-decade) are dead unless a tiny item arrives.
        // Penalize proportionally to how far the class is from a "usable" decade.
        if pr < 10 {
            // Dead space: nearly unusable (min item size 1..100 unknown, but small)
            score += 30.0 - 3.0 * class as f64;
        } else {
            // Non-decade residuals waste potential; decade residuals align with
            // typical item sizes (multiples of 10).
            if class != 0 {
                score += 2.0 + (10 - class) as f64 * 0.3;
            } else {
                score -= 4.0; // decade residual: harmonically clean
            }
        }
    } else {
        // Perfect fit: zero residual, best possible outcome.
        score -= 50.0;
    }

    // --- Harmonic class of item size relative to capacity ---
    // Items that are divisors/multiples of capacity harmonics fit cleanly.
    let cap_frac = item_size as f64 / bin_capacity as f64;
    if cap_frac > 0.5 {
        // Large item: placing it now is urgent; reward fitting it tightly.
        score -= 10.0 * cap_frac;
    }

    // --- Integer division threshold: can post_residual host the next item? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain friendly: this bin can host the lookahead item too.
            score -= 8.0;
            // Extra reward if the chain is tight (next item nearly fills remainder).
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 6.0;
            }
        } else {
            // Chain breaks: residual too small for next item.
            score += 5.0;
        }
    } else {
        // Last item: just minimize residual; already handled by base term.
        score -= 1.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin fits; opening a new bin would waste this residual.
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Many options: prefer tightest fit; base post_residual term suffices,
        // but slight penalty for spreading across too many bins.
        score += 1.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of +100 residual must be offset only when
        // current open bins have bad (small) residuals.
        score = 100.0 - 0.5 * mean_residual - (open_bins_count as f64) * 2.0;
        // If no open bin fits (last chance belongs to new bin), it's fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in stream, prefer reusing existing bins to avoid stranding.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // --- Mean residual coupling: prefer bins below mean residual (tighter) ---
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // --- Progression-aware pressure: as stream ends, avoid opening slack ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Moderate residual is somewhat usable; large residual is fine (kept for future items).
    if post_residual >= 30 {
        score -= 8.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but allow new bin when the fit would create bad dead space.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item would be blocked by this placement creating tiny gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: prefer reusing a decent bin over opening a new one,
    // unless the best reuse would waste space. New bin gets a mild fixed cost.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.3;
        // If item is small relative to capacity, opening a fresh bin wastes potential.
        if item_size < 40 {
            score += (40 - item_size) as f64 * 0.8;
        }
        // Late in the stream, opening new bins is less costly (fewer future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Mean-residual coupling: if open bins are generally tight, avoid wasting this bin's space.
    if bin_residual < bin_capacity && (mean_residual - post_residual as f64) > 40.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fills this bin's post-residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step chain: next item closes this bin exactly
        } else if next_item_size <= post_residual {
            // next item fits here; smaller leftover after the chain is better
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 20.0 - chain_left * 0.3;
        } else {
            // next item cannot follow into this bin: penalize large dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Compare post_residual against the mean residual across open bins
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable gaps (dead space below typical minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    // Slight late-stream preference for tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.1 * progress;

    // New-bin candidate: keep it neutral-ish, only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits into the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else if next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Prefer filling bins with large residual when many bins are open (consolidation pressure).
    let pressure = (open_bins_count as f64) / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += 0.02 * pressure * (post_residual as f64);

    // Time horizon: early in the stream, be conservative (favor new bins for large gaps);
    // late in the stream, squeeze existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for deviating far from mean residual (balance load).
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 10.0 + 0.1 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual, scaled non-linearly (quadratic coupling).
    let mut score = post * post / cap;

    // Smooth stream-progress coupling: later in the stream, dead space matters more.
    score += post * (0.5 + progress) * (0.5 + progress);

    // Reward tight fits (post_residual near zero) with a smooth exponential bonus.
    score -= cap * (-(post / cap) * 4.0).exp();

    // Lookahead: if next item fits into the post residual, reward; else penalize smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 15.0 * (1.0 - (next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        let gap = (next_item_size as f64) - post;
        score += 0.3 * gap * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more so mid/late stream
    // and when decent fitting bins exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins first).
    score += 0.2 * (mean_residual - post).abs() * (mean_residual - post).abs().signum();

    // Mild penalty for very large post residual creating dead space, smooth in progress.
    score += 0.05 * post * post / cap * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.5 * pr;

    // Harmonic class of post_residual: bins whose residual falls in "usable" classes
    // (multiples of 10, or small enough to pair with common sizes) are penalized less.
    let class = post_residual % 10;
    let class_bonus = match class {
        0 => 12.0,  // perfectly divisible residual, highly reusable
        1..=5 => 4.0, // small dead space, often fillable
        6..=9 => 0.0, // awkward class, no bonus
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division threshold: residual in [1,10] is near-dead space unless class 0
    if post_residual > 0 && post_residual <= 10 && class != 0 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; penalize large wasted residuals
            score += 0.3 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 0.1 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big-first into fresh bin is fine
        }
    }

    // Progress coupling: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.2 * progress;

    // Mean residual context: if open bins are already fragmented, discourage adding fragmentation
    if (pr - mean_residual).abs() < 5.0 && pr > 20.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to hold even the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Post-residual that cannot host the lookahead item is also dead space
    // (k=2 lookahead): penalize moderately.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Perfect fit: heavily reward zero residual.
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Open bins pressure ---
    // Encourage packing into existing bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // --- Last chance bin: strongly favor using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New bin candidate handling ---
    if bin_residual == bin_capacity {
        // Default mild penalty: prefer reusing open bins with good fits.
        score += 15.0;
        // Opening a new bin is attractive when item fits poorly everywhere else
        // (large dead space would result) or when very few bins are open.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if post_residual > 0 && post_residual < 10 {
            score -= 55.0; // avoid creating tiny-gap waste in an existing bin
        }
        if open_bins_count <= 2 {
            score -= 10.0;
        }
        if waste_ratio > 0.6 {
            score -= 5.0;
        }
    }

    // --- Tightness reward: the tighter the fit relative to residual, the better ---
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // --- Mean residual coupling: prefer bins below mean residual (fuller bins) ---
    score += 0.3 * (mean_residual - bin_residual as f64);

    // --- Stream progression: later in the stream, be stricter about waste ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

