pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item could plausibly use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // dead space relative to the immediate lookahead item
        }
        // Reward bins whose residual after placement matches the next item well.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // When many bins are open, prefer consolidating into existing bins (penalize new bins).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there are many open bins or high mean residual.
        score += 8.0 + 0.5 * open_bins_count as f64 + 0.3 * mean_residual;
        // Late in the stream, opening new bins is more acceptable (avoid stranding).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If no open bin fits well (large item), new bin is less bad.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    } else {
        // Slight preference for bins with residuals close to the item (best-fit flavor).
        let waste = (bin_residual - item_size) as f64;
        score += 0.05 * waste;
        // Prefer bins whose residual is below the mean (compact full bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Early in stream: keep some diversity, mildly discourage filling bins too eagerly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && post_residual < 10 {
        score += 5.0;
    }

