}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr as f64;
    score += 40.0 * norm_pr * norm_pr;
    score -= 30.0 * fit * (1.0 - fit) * (1.0 - progress);

    // Stream-progress coupling: later in stream, tighten packing more aggressively
    let tighten = 1.0 + 2.0 * progress * progress;
    score *= tighten;

    // Dead-space penalty: residuals too small for any plausible item
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr as f64) / 10.0;
    }

    // Lookahead synergy: reward if next item fits the post-residual well
    if next > 0.0 && pr > 0.0 {
        let synergy = next / (pr / cap);
        if synergy <= 1.0 {
            score -= 20.0 * (1.0 - synergy) * (1.0 - synergy);
        } else {
            score += 10.0 * (synergy - 1.0).min(3.0);
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild pressure toward filling bins with larger mean residual spread
    score += 0.05 * (mean_residual - pr).abs();

    // New-bin candidate: make it less attractive unless residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 30.0 - 25.0 * fragmentation * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes via modulo arithmetic.
    // Class 0: perfectly tight (post_residual small) -> strongly reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 40.0;
    } else {
        // Harmonic class: residues divisible by common item sizes (5,10,20,25)
        // are more reusable by future items; odd/prime residues are dead space.
        let harmonic = if pr % 25 == 0 { 3 }
            else if pr % 20 == 0 { 2 }
            else if pr % 10 == 0 { 2 }
            else if pr % 5 == 0 { 1 }
            else { 0 };
        score -= harmonic as f64 * 12.0;
        // Small odd residues are unusable dead space: penalize.
        if pr % 5 != 0 && pr < 30 {
            score += (30 - pr) as f64 * 0.8;
        }
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item chains perfectly: big reward scaled by tightness.
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 - slack.min(20.0) * 0.5;
        } else if next_item_size <= bin_residual {
            // Next item fits only if we DON'T take this item here -> mild penalty.
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer tightest fill.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless post_residual would be terrible dead space.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if pr > 50 {
            score += 10.0; // but wasteful placement -> soften the bonus
        }
    }

    // New-bin candidate (empty bin): only attractive if no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && pr <= 30;
        if good_fit_exists {
            score += 35.0; // discourage opening new bin when a tight fit exists
        } else {
            score -= 8.0; // opening a fresh bin is fine
        }
        // Late in stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer filling bins with small residuals (consolidation), gently.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Many open bins: encourage closing them out by using small-residual bins.
    if open_bins_count > 4 {
        score += (mean_residual - post_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space relative to smallest possible item (1..100 interface).
    if post_residual > 0 && post_residual < item_size {
        score += 5.0 + (10.0 - post_residual as f64).max(0.0) * 2.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins.
    let pressure = open_bins_count as f64 / 20.0;
    if bin_residual != bin_capacity {
        score -= pressure * 10.0;
    } else {
        // New-bin candidate: only attractive when few open bins or bad fits exist.
        score += pressure * 8.0;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Late in the stream, consolidate to reduce total bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // Prefer bins whose residual is near the mean (keeps residuals balanced).
    score += ((bin_residual as f64 - mean_residual) / 10.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still fit the next item (usable chain) -> proportional reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.3 * slack;
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Penalize very small post-residuals (fragmentation) unless it was a perfect fit.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless existing options are poor fits
    // (i.e., this bin's residual is far above mean residual meaning existing bins are tight).
    if bin_residual == bin_capacity {
        let spread = bin_residual as f64 - mean_residual;
        if spread > 25.0 {
            // Existing bins are much emptier on average; opening new bin is wasteful.
            score += 40.0;
        } else {
            score += 12.0;
        }
        // Late in stream, prefer reusing open bins even more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    } else {
        // Reward bins tighter than the mean residual (good consolidation).
        let tightness = mean_residual - bin_residual as f64;
        score -= 0.15 * tightness;
    }

    // Slight preference for filling larger fraction of the bin.
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits nonlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else {
        // Penalize dead space that cannot hold typical items.
        score += (post_residual as f64).powi(2) * 0.02;
    }

    // Lookahead: if the next item fits the post-residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Wasted space relative to the upcoming item.
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Last-chance bonus: only bin able to fit the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Time horizon: late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Penalize spreading residual mass too thin across many bins.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // New-bin candidate logic: opening a fresh bin is attractive only when the
    // item is large relative to residual or many bins already compete.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let open_pressure = open_bins_count as f64 * 0.5;
        // Fresh bin cost grows with number of open bins; shrinks when item is large.
        score += 30.0 + open_pressure - item_frac * 40.0;
        // Late in stream, prefer squeezing into existing bins.
        score += progress * 20.0;
        // If next item is small, a fresh bin is more useful for it.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 - norm_pr * progress * 25.0;
    score += coupling;

    // Reward tight fits (small post_residual) more as stream progresses
    score -= (1.0 - norm_pr).powi(3) * (10.0 + 20.0 * progress);

    // Penalize dead space below next item size (wasted residual)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 0.3 * (pr - nxt) / cap;
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.2 * open_bins_count as f64;
    }

    // Smooth alignment with mean residual state
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover mod 10 classes.
    // Small leftovers (dead space) get penalized more when they fall in
    // "unusable" harmonic classes (1..9 that no typical item fills).
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64) / cap;
    let class = (post_residual % 10) as f64;

    // Reward bins whose post_residual is divisible by common item sizes (harmonic fit).
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 20 == 0 { score -= 8.0; }
        else if post_residual % 25 == 0 { score -= 5.0; }
        else if post_residual % 50 == 0 { score -= 7.0; }
        else {
            // Non-harmonic leftover: penalize proportionally to how "dead" it is.
            score += class * 0.35 * (0.5 + fill);
        }
    }

    // Lookahead coupling: if the next item fits the post_residual exactly or harmonically,
    // strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if (post_residual - next_item_size) % 10 == 0 {
            score -= 9.0;
        } else if next_item_size % 10 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Leftover can't serve the next item: penalize dead space harder.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Perfect fit bonus (integer division threshold: post_residual == 0).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it unattractive unless the stream is early and
    // the item is large relative to capacity (fraction thresholds).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score += 10.0; // base new-bin tax
        if frac > 0.6 && progress < 0.25 {
            score -= 18.0; // early stream + big item: opening fresh bin is fine
        }
        if open_bins_count > 6 {
            score -= 4.0; // many bins open: consolidation pressure elsewhere anyway
        }
    }

    // Mild preference for bins tighter than the mean residual (good packing).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 0.8;
    }

    // Late-stream pressure: discourage leaving many partially-filled bins.
    if progress > 0.8 && post_residual > 0 {
        score += (post_residual as f64) * 0.05 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are unusable -> heavy penalty scaling with how "wasted" they are.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit: maximal reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward keeping residual above the next item size (usable for lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // creates a gap the next item cannot use: penalize relative waste
        score += 6.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // unless the fit is tight (post_residual small).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Allow new bin only if no open bin gives a tight fit.
        if post_residual == 0 { score -= 150.0; }
    } else {
        // reward using existing bins, more when many are open
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Slight preference for bins with lower residual (tighter bins) among fits.
    score += (bin_residual as f64 - mean_residual).max(-50.0).min(50.0) * 0.05;

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for leaving dead space that is too small to be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but how tightly?
            let chain_waste = post_residual - next_item_size;
            score -= 30.0;
            if chain_waste < 10 {
                score -= 25.0;
            }
        } else {
            // Next item cannot use this bin's residual: residual becomes dead
            // space unless it is large enough to be generically useful.
            let dead = post_residual as f64;
            if dead < (next_item_size as f64) {
                score += 0.35 * (next_item_size as f64 - dead);
            }
        }
    }

    // Compare residual against mean residual: prefer bins that are already
    // tighter than average (consolidating waste) when residual is small.
    let residual_f = post_residual as f64;
    if residual_f < mean_residual {
        score -= 0.5 * (mean_residual - residual_f).min(40.0);
    } else {
        score += 0.2 * (residual_f - mean_residual).min(40.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin, especially early in the stream or when
    // open bins could still accommodate the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 30.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 40.0;
        }
        // A new bin is attractive only if item is large and would leave
        // existing bins with fragmented small residuals.
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual waste grows super-linearly, so penalize large post_residual.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Lookahead: bonus if the next item fits into the post-residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if the next item fills the bin almost exactly afterward.
            let second_residual = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - second_residual / bin_capacity as f64);
        } else {
            // Penalize leaving residual too small for the next item (dead space).
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are wasteful
    // or scarce. Base penalty for opening new bins grows with stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // Early stream: opening bins is cheap and enables future flexibility.
        score -= 25.0 * (1.0 - progress);
    }

    // Prefer bins with residual already below the mean (consolidating small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Mild bonus for using bins that are already fairly full (fragmentation control).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let next_fit = next_item_size as f64 / cap;

    // Base: prefer small post_residual, with non-linear (quadratic) shaping
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth coupling: post_residual value weighted by stream progress polynomial
    let prog_poly = 0.5 + 0.5 * progress * (2.0 - progress);
    score -= prog_poly * (pr / cap) * 10.0 * fit;

    // Penalize dead space that cannot fit the lookahead item (smooth gate via sigmoid-like term)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        let gate = 1.0 / (1.0 + (-6.0 * gap).exp());
        score += 14.0 * gate * next_fit;
    } else {
        // Last item: strongly prefer tightest fit
        score -= 20.0 * (1.0 - pr / cap);
    }

    // Reward using nearly-full bins (low residual relative to mean residual)
    let mean_norm = mean_residual / cap;
    score -= 6.0 * (1.0 - mean_norm) * (1.0 - pr / cap);

    // Last-chance bin bonus (smoothly scaled by how tight the fit is)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - (pr / cap).powi(2));
    }

    // Mild penalty for proliferation of open bins late in the stream
    score += 0.02 * (open_bins_count as f64) * progress;

    // New-bin candidate: neutral base so it loses only when a genuinely good fit exists
    if bin_residual == bin_capacity {
        score = cap as f64 * 0.55 + 4.0 * fit - 6.0 * progress * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits strongly rewarded
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Dead-space penalty grows for residuals in awkward harmonic classes
    let cls = post_residual % 20;
    let awkward = match cls {
        1 | 2 | 3 | 17 | 18 | 19 => 1.0,
        11 | 12 | 13 => 0.6,
        _ => 0.0,
    };
    score += awkward * (post_residual as f64) * 0.5;

    // Fraction-of-capacity classes: prefer residuals that are large clean fractions
    let frac = (post_residual as f64) / cap;
    if (frac - 0.5).abs() < 0.02 || (frac - 0.25).abs() < 0.02 || (frac - 0.75).abs() < 0.02 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 5 { score -= 20.0; }
            score -= (nxt_post as f64).min(20.0) * 0.4;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / cap);
        if pressure < 1.5 {
            score -= 40.0; // few open bins / full bins: open new
        } else {
            score += 25.0; // plenty of slack: discourage new bin
        }
    }

    // Mild time decay: as stream progresses, tighten packing (favor filling existing bins)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Prefer bins tighter than the mean residual
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
