}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a nonlinear squaring
    // to punish large dead space more aggressively.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Perfect chaining: the next item exactly fills what's left.
            let gap = (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 30.0 * (1.0 - gap);
            // Extra reward if the next item fits *exactly* (gap ~ 0).
            if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to how much
            // of the next item is "wasted" relative to this bin's residual.
            let waste = nxt - post_residual as f64;
            score += 0.35 * waste;
        }
    } else {
        // Last item: just minimize final residual tightly.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual far above the mean are
    // "loose" bins; prefer to dump into them (they waste less elsewhere).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large relative to typical residuals, or the fit into open bins is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins mildly early, more later (consolidate as stream ends).
        score += 55.0 + 25.0 * progress;
        // But if item is huge, a fresh bin is a natural home: soften penalty.
        let big = item_size as f64 / bin_capacity as f64;
        score -= 60.0 * big * big;
        // If no open bin can fit (we are the only candidate), allow it.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If the next item is large too, reserving a fresh bin is fine.
        if next_item_size > 0 && (next_item_size as f64) >= 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Mild penalty for proliferating open bins when residual is already high.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward filling the bin nearly exactly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize large dead space: residuals too small for typical items (1..100)
    if post_residual > 0 && post_residual < 12 {
        score += 30.0 * (12.0 - post_residual as f64) / 12.0;
    }

    // Lookahead: reward leaving room for the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect pairing
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to overshoot
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 * (miss / next_item_size as f64).min(2.0);
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: encourage consolidating into existing bins, penalize spreading
    if open_bins_count > 2 {
        let pressure = (open_bins_count as f64).ln() / 10.0;
        // reward bins whose residual is below the mean (converging toward closure)
        if (bin_residual as f64) < mean_residual {
            score -= 12.0 * pressure;
        } else {
            score += 6.0 * pressure;
        }
    }

    // New-bin candidate logic: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64; // = 1.0 for empty bin minus item
        // Opening a new bin is good early or when item leaves huge unusable gap elsewhere
        let open_bonus = 18.0 * (1.0 - progress) + 14.0 * (1.0 - tightness);
        // Penalize opening new bins when existing bins fit well
        if fitting_bins_count > 0 && tightness > 0.6 {
            score += 40.0;
        }
        score += open_bonus - 10.0;
        let _ = bad_fit;
    }

    // Mild time pressure: late in stream, prefer filling existing bins tightly
    score -= 10.0 * progress * tightness;

    // Small tie-breaker toward bins with lower residual (denser bins first)
    score += 0.05 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap;

    // Base: prefer tight fits via smooth non-linear penalty on post_residual
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Non-linear coupling of fill ratio with stream progress:
    // later in the stream, tighter packing matters more
    let progress_coupling = (fill * fill * (0.5 + progress)) * 40.0;
    score -= progress_coupling;

    // Cubic interaction between post_residual and progress
    score += (post / cap).powi(3) * 25.0 * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize opening new bins when plenty of open bins exist
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean-residual divergence penalty: prefer bins near the mean state
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Lookahead: reward leaving space that fits the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        let slack = (post - nxt).abs() / cap;
        score -= fits_next * 15.0 * (1.0 - slack);
        score += (1.0 - fits_next) * 8.0;
    }

    // New-bin candidate: make it moderately attractive only when item is large
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score = 20.0 + 60.0 * (1.0 - large) * (1.0 - progress) - 40.0 * large * large;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual gap: post_residual mod classes.
    // Gaps that are multiples of common item sizes are "usable" harmonic classes.
    let gap = post_residual;
    let harmonic_bonus: f64 = if gap == 0 {
        -60.0 // perfect fill
    } else if gap % 50 == 0 {
        -25.0
    } else if gap % 25 == 0 {
        -15.0
    } else if gap % 10 == 0 {
        -10.0
    } else if gap % 5 == 0 {
        -5.0
    } else if gap < 10 {
        20.0 // tiny dead space, unusable
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead: does the next item fit exactly or well into the post-residual?
    if next_item_size > 0 {
        if next_item_size == gap {
            score -= 45.0; // next item perfectly fills this bin
        } else if next_item_size <= gap {
            // fractional compatibility: next item leaves another harmonic gap
            let g2 = gap - next_item_size;
            if g2 % 10 == 0 {
                score -= 12.0;
            } else if g2 < 10 {
                score += 15.0; // would strand tiny space
            }
        } else {
            score += 8.0; // next item won't fit here; keep space flexible
        }
    } else {
        // last item: fill as much as possible
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): penalize unless current fit is bad.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 30.0;
        // But if placing here would strand a lot (large post_residual in an open bin
        // is already high), opening fresh can win; reduce penalty when stream is early.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many open bins with high mean residual, prefer new bin less.
        if mean_residual > 50.0 {
            score += 10.0;
        }
    }

    // Slight preference for tighter bins (low residual relative to capacity).
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Congestion: many open bins -> consolidate.
    if open_bins_count > 8 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it's too small to hold even the smallest plausible item.
    // We treat gaps < 12 as near-dead, with a smooth ramp.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward: strongly favor placements leaving exactly 0 residual.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bins pressure: penalize using bins when many are open, to avoid bin sprawl;
    // but soften when this is the last fitting bin (avoid opening a new bin unnecessarily).
    let pressure = (open_bins_count as f64).sqrt() * 1.5;
    if fitting_bins_count == 1 {
        score -= pressure * 0.8;
    } else {
        score += pressure;
    }

    // Penalize creating gaps that cannot fit the lookahead item (wasted potential).
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 4.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 3.0;
        }
    }

    // Slight preference for tighter bins early on (best-fit tendency),
    // scaled by stream progress so late stream favors consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (0.5 + progress);

    // New-bin candidate: make empty bins mildly unattractive unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.1;
    }

    // Penalize leaving residual far from mean (fragmentation signal).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it fills the remainder.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 120.0 * fill_ratio;
            // Bonus if both placements nearly exhaust the bin.
            if post_residual - next_item_size <= 5 {
                score -= 80.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a gap that is too small
            // for typical items (dead space), scaled by how close it is to useless.
            let gap = post_residual as f64;
            if gap < 10.0 {
                score += 60.0 * (10.0 - gap);
            }
        }
    }

    // Penalize post-residuals that are awkwardly small (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins that are already more filled
    // (smaller residual) than average — classic best-fit reinforcement.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: make opening a new bin moderately attractive only
    // when the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        if item_size >= 60 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that becomes unusable: post_residual below typical small item size.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver = wasted capacity
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, extra pressure to pick the tightest one.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item could fit into this bin's post_residual,
    // reward leaving that compatible space; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 8.0; // breaking a potential chain
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large and current open bins have poor fits, or late in the stream
    // when mean residual is already low (little capacity left anywhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_gap = mean_residual - item_size as f64;
        let mut new_bin_score = 55.0; // base cost of opening a bin

        // If open bins can't come close to fitting (mean residual barely covers item),
        // a new bin becomes more attractive.
        if avg_fit_gap < 10.0 {
            new_bin_score -= 30.0;
        }
        // Large items relative to capacity prefer fresh bins.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_score -= 15.0;
        }
        // Early stream: keep optionality low, avoid bin proliferation.
        new_bin_score += 20.0 * (1.0 - progress);
        // Many open bins already: discourage more.
        new_bin_score += 1.5 * open_bins_count as f64;

        score = new_bin_score;
    }

    // Mild time-horizon coupling: early on, slightly favor consolidation into
    // existing bins (score = residual dominated); late, tighten preference for
    // low post_residual even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Small penalty proportional to how far above mean residual this bin sits,
    // nudging selection toward bins whose residual matches the fleet average.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (prefer tight fits)
    let mut score = pr;

    // Smooth polynomial coupling: residual value decays with progress,
    // so late in the stream we penalize leftover space more aggressively.
    let decay = 1.0 - progress * progress;
    score -= 12.0 * pr * norm_pr * decay;

    // Non-linear reward for exact/near-exact fits (post_residual near 0)
    let tightness = (1.0 - norm_pr).powi(6);
    score -= 8.0 * tightness * item_size as f64 / cap;

    // Penalize dead space that cannot fit the next item (smooth quadratic gap term)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let gap_frac = gap / cap;
        score += 15.0 * gap_frac * gap_frac * (0.5 + progress);
        // Reward bins whose post-residual still accommodates the lookahead item
        if pr >= next_item_size as f64 {
            score -= 4.0 * (next_item_size as f64 / cap) * (1.0 - progress);
        }
    } else {
        // Last item: strongly prefer zero residual
        score += 20.0 * norm_pr * norm_pr;
    }

    // Last-chance bin bonus (avoid opening a new bin when this is the only fit)
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins early (encourages consolidation)
    let open_frac = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 3.0 * open_frac * norm_pr * (1.0 - progress);

    // Mean-residual coupling: prefer bins close to the mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.01;

    // New-bin candidate: penalize opening a fresh bin unless residual savings are large
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= cap {
            score += 8.0; // item would pair well with next item elsewhere
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in awkward "harmonic" classes are hard to fill later.
    let pr = post_residual;
    if pr > 0 {
        // Residuals 1..9 are nearly unusable (min item 10 in classic setting, but sizes 1..100 here).
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }
        // Modulo arithmetic on capacity: residuals that are exact divisors/multiples of
        // capacity fractions tend to tile well with common item sizes.
        let cap = bin_capacity;
        let half = cap / 2;
        let quarter = cap / 4;
        if pr == half || pr == quarter || pr == cap / 5 || pr == cap / 10 {
            score -= 8.0; // harmonically aligned residual: easy to fill
        }
        // Penalize residuals that no plausible next item fits: dead space.
        if next_item_size > 0 && pr < next_item_size {
            score += (next_item_size - pr) as f64 * 0.5;
        }
        // Reward if the lookahead item exactly fills the post residual.
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size > 0 && next_item_size <= pr {
            // Reward residuals that still admit the next item.
            score -= 5.0;
        }
    } else {
        // Perfect fit: strongly favored.
        score -= 40.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; that alone
    // usually ranks it worse. But if the item is large and mean residual is low,
    // opening a fresh bin can be better than fragmenting many bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let new_bin_bias = 30.0 * (1.0 - progress) - 10.0 * progress;
        score += new_bin_bias;
        // If item is big and open bins are crowded, opening a new bin is attractive.
        if fill_ratio > 0.6 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Slight preference to keep mean residual balanced: avoid creating extreme outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Late-stream consolidation: as the stream ends, prefer filling existing bins.
    if next_item_size == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be reused
    // (nothing can fit in a gap smaller than the minimum item size) are
    // pure waste, so penalize them far beyond their nominal size.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // "Awkward" gaps: large enough to waste but too small for typical items.
    if post_residual >= 10 && post_residual <= 25 {
        score += 0.9 * (25 - post_residual) as f64;
    }

    // Perfect fit reward: encourage filling a bin exactly.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item can also fit into the leftover
    // space, this placement is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    }
    // Penalize leaving a gap that the lookahead item just barely misses.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing space rather than spreading out.
    score += 2.5 * open_bins_count as f64;

    // Slight preference toward bins whose residual is below the mean
    // (tighter bins get filled first, keeping large gaps flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Mild new-bin aversion that grows over the stream.
    if bin_residual == bin_capacity {
        score += 55.0 + 20.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
