pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with quadratic dead-space penalty.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += 0.35 * (post * post) / cap;

    // Lookahead: if the next item fits into the post residual, reward this bin strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 6.0 + 0.25 * nxt;
            // Perfect chain: next item exactly fills the bin afterwards.
            if post_residual == next_item_size {
                score -= 8.0;
            }
        } else {
            // Dead space risk: next item cannot use the leftover.
            let waste = post;
            score += 0.15 * waste * (1.0 + waste / cap);
        }
    } else {
        // Last item: minimize leftover aggressively.
        score -= 3.0;
    }

    // Last-chance bin: strongly reward using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }
    // Many alternatives: mild penalty so competition decides on fit quality.
    if fitting_bins_count > 3 {
        score += 1.5;
    }

    // Global state coupling: with many open bins, prefer filling existing ones
    // rather than fragmenting capacity further.
    let ob = open_bins_count as f64;
    score += 0.02 * ob * (post / cap);

    // Mean residual coupling: if this bin's residual is far above the mean,
    // it is a "loose" bin; filling it down toward the mean is good.
    let residual = bin_residual as f64;
    let gap = residual - mean_residual;
    score -= 0.08 * gap;

    // Time horizon: early in the stream, be more willing to open/keep loose bins
    // (future items unknown); late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 * (post / cap);
    score -= progress * 4.0 * (post / cap);

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Reward it only when it enables a large item or when no good existing fit exists;
    // otherwise penalize so existing bins are preferred.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64) > 0.6 * cap;
        let poor_existing = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual > 0 && (bin_residual - item_size) as f64 > mean_residual);
        if big_item || poor_existing {
            score -= 5.0;
        } else {
            score += 10.0 + 0.05 * ob;
        }
        // Late in the stream, opening new bins is wasteful.
        score += progress * 6.0;
    }

    // Small item into a large hole: mildly discourage wasting a big residual on a tiny item
    // unless it is the last chance.
    if (item_size as f64) < 0.25 * cap && residual > 0.6 * cap && fitting_bins_count > 1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalized smoothly as post-residual grows.
    let mut score = norm_pr * norm_pr * cap;

    // Smooth progress coupling: later in stream, value tight packing more.
    let tight_bias = (1.0 + progress * progress) * (item_size as f64 / cap);
    score -= tight_bias * (bin_residual as f64 - pr) * 0.5;

    // Dead-space penalty: residuals too small for typical items are waste.
    let dead = if next_item_size > 0 { (pr - next_item_size as f64).max(0.0) } else { pr };
    score += (dead / cap) * (dead / cap) * cap * (0.3 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= cap * (0.5 + progress);
    }

    // Mean residual coupling: avoid worsening an already-low mean residual.
    score += (mean_residual - pr).abs() * 0.1 * (1.0 + progress);

    // New-bin candidate: make empty bin moderately attractive only when fit is poor.
    if bin_residual as f64 == cap {
        score = cap * (0.6 + 0.4 * norm_pr) - (item_size as f64 / cap) * cap * 0.2 * (1.0 - progress);
        if fitting_bins_count <= 1 && next_item_size > 0 && (next_item_size as f64) > pr {
            score -= cap * 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "useful" residue
    // classes (divisible into common small item sizes) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit is always best
    } else {
        // Reward residuals that are reusable by typical small items (multiples of 10/5)
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        }
        // Penalize dead space in awkward classes
        if pr < 10 {
            score += 25.0; // unusable sliver
        } else if pr <= 20 {
            score += 5.0;
        }
        // Integer-division threshold: residual bucket by 20s
        let bucket = pr / 20;
        score += (3 - bucket.min(3)) as f64 * 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 && next_item_size <= pr {
        if pr - next_item_size == 0 {
            score -= 30.0;
        } else if (pr - next_item_size) % 10 == 0 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > pr {
        // next item won't fit here; leftover becomes dead unless small
        if pr > 0 && pr < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening fresh bins is fine early, wasteful late
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 30.0 * progress;
        if pr == bin_capacity as u32 {
            // empty bin post_residual = capacity; neutralize base large residual
            score -= 0.0;
        }
    }

    // Prefer filling bins with small residuals relative to fleet mean
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for tighter bins overall
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 30.0;
    }
    // Mid-range dead space (10..=20) also discouraged, more mildly.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward filling bins tightly relative to their residual.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 15.0;

    // Open-bin pressure: many open bins -> favor consolidation into existing bins,
    // penalize opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure.
        score += 25.0 + bin_pressure;
        // A new bin is attractive if it leaves a large, reusable residual
        // for the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    } else {
        // Reusing an open bin is generally favored.
        score -= 10.0;
        // Last-chance bin: strongly prefer using it before opening a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Lookahead: if this placement lets the next item fit here, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If it leaves a gap just below the next item, penalize (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Slightly prefer bins below the mean residual (balancing across bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 200.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // penalize dead space relative to next item
        score += 0.8 * (next_item_size as f64 - post_residual as f64);
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 50.0;
        // but opening a new bin is attractive for large items into fresh space
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;  // awkward zone
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid wasting residual capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this bin becomes a perfect pair — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here: slight penalty scaled by wasted potential.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    } else {
        // Last item in stream: just minimize post_residual (already base), add small tight-fit nudge.
        score -= 5.0 * tightness;
    }

    // Global state: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins) — a new-bin candidate gets a rising penalty.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin: penalize more as the stream progresses and bins accumulate.
        score += 15.0 + 20.0 * progress + 0.3 * open_bins_count as f64;
        // But early in the stream, new bins are cheap.
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (denser bins), keep uniformity.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild preference for bins with larger residual when item is large (big items need room).
    if item_size > 50 {
        score += 0.05 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) + norm_post * (0.5 + 1.5 * progress * progress);

    let mut score = post + 20.0 * poly;

    // Reward tight fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Penalize dead space relative to mean residual
    score += 0.3 * (post - mean_residual).max(0.0) * (0.5 + progress);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap) * norm_post;
    }

    // Mild pressure against bin sprawl late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when residuals are large and stream is early
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 10.0 * progress * (1.0 - norm_post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" classes (multiples of common item sizes / near-capacity fractions).
    let pr = post_residual;
    let usable = (pr == 0) as i32
        + (pr >= 20 && pr <= 30) as i32
        + (pr >= 50 && pr <= 60) as i32
        + (pr % 10 == 0) as i32;
    score -= usable as f64 * 3.0;

    // Penalize dead space: small nonzero residuals are wasted.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit is heavily rewarded.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward strongly; if next item cannot ever fit post_residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Fraction-of-capacity harmonic term: prefer filling bins past half full.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.5 {
        score -= 10.0 * (fill_frac - 0.5);
    }

    // Modulo threshold on post_residual: residuals in [10,20) or [40,50)
    // are awkward classes for typical size streams.
    if (10..20).contains(&pr) || (40..50).contains(&pr) {
        score += 6.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // fits well (many bins fit -> discourage new bin).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 30.0 + 5.0 * fitting_bins_count as f64;
        }
    }

    // Late in the stream, tighten packing to reduce bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap just below next item: future dead space risk.
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; with few bins,
    // filling existing bins tightly is still favored but new-bin cost is low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score += 0.6 * pressure * (mean_residual / bin_capacity as f64);

    // New-bin candidate: make it attractive only when the fit is poor or dead space would result.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) < 10;
        if poor_fit || (next_item_size > 0 && (bin_residual - item_size) < next_item_size) {
            score -= 20.0;
        } else {
            // Prefer existing bins for decent fits, but less aggressively when many bins are open.
            score += 30.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful (below min item size 1, harsher below ~10)
    if post_residual < 10 {
        score += 60.0;
    } else {
        score += 0.15 * (post_residual as f64).powf(1.4);
    }

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 90.0 - 1.5 * slack; // reward fit, mildly penalize slack
        } else {
            // next item cannot fit here; penalize proportionally to overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.5 * overflow;
        }
    }

    // Compare residual against mean residual of open bins: prefer tightest bins
    score -= 0.8 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize spreading across many open bins lightly; encourage consolidation
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate handling: opening a new bin is only good if the item is large
    // or no open bin gives a good fit. Make the empty bin unattractive by default.
    if bin_residual == bin_capacity {
        let tight_fit = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 80.0 * tight_fit; // large items justify new bins more
        if next_item_size > 0 && next_item_size >= item_size {
            score += 30.0; // big items coming: fresh bin more acceptable
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
    }

    // Slight preference for filling bins earlier in the stream
    score += 0.02 * (step_index as f64 / (total_items.max(1) as f64)) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement unless it can fit the next item.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 8.0; // residual still useful for lookahead item
        } else if dead > 20.0 {
            score += dead * 0.25; // likely wasted space
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins when many bins fit the item well.
        if fitting_bins_count > 0 {
            score += 20.0 + 5.0 * (fitting_bins_count as f64).sqrt();
        }
        // Early in stream, opening bins is fine (builds capacity for future).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.3 {
            score -= 6.0;
        }
        // If next item is large and mean residual low, new bin is attractive.
        if next_item_size > 60 && mean_residual < 30.0 {
            score -= 10.0;
        }
    } else {
        // Mild preference for fuller bins among open ones.
        score += 0.05 * (bin_capacity - bin_residual) as f64;
    }

    // Late in stream: consolidate, avoid spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0 * (open_bins_count as f64).ln().max(0.0);

    // Slight pull toward bins with residual near mean (keeps balance).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer low post_residual (tight fits). Late: tolerate larger residuals
    // less harshly, so we avoid opening new bins unnecessarily.
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;

    // Quadratic/cubic shaping of post_residual, modulated by progress.
    let x = pr / cap;
    score += w_early * (x * x) * cap * 0.5;
    score -= w_late * (x * (1.0 - x)) * cap * 0.35;

    // Perfect fit reward, stronger as stream progresses.
    if post_residual == 0 {
        score -= 12.0 + 18.0 * progress;
    }

    // Dead-space penalty: residuals too small for any plausible item.
    let dead = x > 0.0 && x < 0.10;
    if dead {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * w_late;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / cap);
    }

    // Penalize bins far from mean residual (keeps residual distribution balanced),
    // with smooth polynomial weighting.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += (dev * dev) * cap * (0.25 + 0.25 * progress);

    // Mild penalty for opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.4 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: penalize wasted space quadratically.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect fit: near-zero residual is a jackpot.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Harmonic class of post_residual: bins whose leftover falls into
    // "usable" residue classes (divisible by common item sizes) are preferred.
    let pr = post_residual;
    if pr > 0 {
        let mut usable_bonus = 0.0;
        if pr % 10 == 0 { usable_bonus += 40.0; }
        if pr % 20 == 0 { usable_bonus += 25.0; }
        if pr % 25 == 0 { usable_bonus += 20.0; }
        if pr % 50 == 0 { usable_bonus += 30.0; }
        // Dead-space classes: small odd remainders are hard to fill.
        if pr % 10 != 0 && pr < 15 { usable_bonus -= 60.0; }
        score -= usable_bonus;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // chain placement is ideal.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            // Next item fits but leaves another gap; mild reward scaled by fit tightness.
            let nxt_gap = pr - next_item_size;
            score -= 30.0 * (1.0 - nxt_gap as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize large leftovers.
            score += 0.5 * (pr as f64 - (next_item_size as f64 - pr as f64)).max(0.0);
        }
    }

    // Last-chance bin: if only this bin can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when
    // existing bins have poor fits (large post_residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let residual_pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Prefer new bin when mean residual is small (existing bins nearly full)
        // or early in the stream (amortize future flexibility).
        score -= 60.0 * (1.0 - residual_pressure) + 40.0 * (1.0 - progress);
        // Penalize opening new bins when many are already open and loose.
        score += 0.8 * open_bins_count as f64 * residual_pressure;
        // If the item would leave a large dead space in any bin, empty bin looks better.
        if post_residual > 40 {
            score -= 45.0;
        }
    }

    // Fraction-of-capacity threshold: reward placements that keep residual
    // in the "reusable band" (10..=50) via integer division tiers.
    let tier = pr / 10;
    match tier {
        0 => score -= 20.0,          // residual < 10: excellent
        1 => score -= 10.0,          // 10..19: good
        2 | 3 => score += 5.0,       // 20..39: neutral
        4 => score += 15.0,          // 40..49: risky
        _ => score += 25.0,          // 50+: wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small post_residual gaps that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize moderately small gaps that only tiny items could fill.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item almost fits but not quite (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: more open bins -> prefer filling existing ones over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.5 * (1.0 + progress);

    // New-bin candidate penalty grows with number of open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact match: post_residual == next_item_size (perfect 2-step chain)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits here: reward proportionally to tightness of the chain
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * tightness;
        } else {
            // next item does NOT fit post_residual: penalize small dead space left behind
            let dead = next_item_size as f64 - post_residual as f64;
            if dead < 10.0 {
                score += 20.0; // nearly-fitting gap is wasted potential
            } else {
                score += 5.0 * (dead / 80.0);
            }
        }
    }

    // Compare post_residual against mean residual: leaving residual far below mean
    // (creating an outlier small hole) is bad unless it was a tight fit.
    let pr = post_residual as f64;
    if pr < mean_residual - 15.0 {
        score += 0.5 * (mean_residual - pr);
    } else if pr > mean_residual + 15.0 {
        // leaving a large residual relative to others can be good (keeps bins usable)
        score -= 0.15 * (pr - mean_residual);
    }

    // Last-chance bonus: only this bin fits the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual is truly awkward
    if bin_residual == bin_capacity {
        let awkward = if next_item_size > 0 {
            (bin_residual as i64 - next_item_size as i64).abs() as f64
        } else { 0.0 };
        score += 40.0 - 0.3 * awkward;
        // early in stream, prefer opening bins (keeps options open)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for tighter fits overall
    score += 0.2 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but with diminishing returns on very small residuals
    let pr = post_residual as f64;
    score = 0.7 * pr + 0.3 * pr * pr / (bin_capacity as f64);

    // Lookahead: if next item fits perfectly into post_residual, strongly reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item can't use this leftover space: penalize wasted potential
        score += 8.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize bins far below mean residual (fragmenting global state)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Time horizon: early on, be conservative (favor new bins less); later, consolidate
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * t * (1.0 - pr / bin_capacity as f64);

    // Many open bins: encourage filling them rather than opening new ones
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).ln() * (pr / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * pr - 20.0 * t;
        if fitting_bins_count == 1 { score += 60.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let is_new_bin = bin_residual == bin_capacity;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * (1.0 + 0.8 * progress * norm_post + 0.6 * (1.0 - progress) * (1.0 - norm_post) * (1.0 - norm_post));

    let mut score = poly * 100.0;

    // Penalize large post-residual more strongly as stream progresses
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits, scaled by polynomial decay of usefulness
    score -= 30.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + 0.5 * progress);

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 25.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 15.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when fit is poor
    if is_new_bin {
        score += 20.0 + 30.0 * progress;
    }

    // Slight preference for bins with residuals near the mean (balanced usage)
    score += 5.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals in the same modular class
    // as common item sizes are more reusable. Penalize "dead zone" leftovers
    // (small but nonzero) that few item sizes can fill.
    let dead_zone = post_residual > 0 && post_residual < 10;
    if dead_zone {
        score += 40.0;
    }

    // Classify leftover by integer division into harmonic bands of capacity/10.
    let band = post_residual / 10; // 0..=10
    // Rewards: bands 1..4 (10-49 leftover) are highly reusable for items 10..80
    // only partially; band 0 is perfect fit; large bands waste capacity.
    match band {
        0 => score -= 25.0, // perfect fit
        1 | 2 => score -= 12.0,
        3 => score -= 6.0,
        4 | 5 => score += 4.0,
        _ => score += (band as f64 - 5.0) * 3.0,
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: strongly reward, scaled by how snugly next item fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 18.0 + 14.0 * snug;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Next item cannot use this leftover: penalize proportionally.
            score += 6.0 + (post_residual as f64 / bin_capacity as f64) * 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 20.0;
        if dead_zone && post_residual > 0 {
            score -= 5.0; // still better than a fresh bin for tiny leftover loss
        }
    }

    // New empty bin candidate: only attractive when current fit creates bad
    // fragmentation or when the stream is early and bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 - 25.0 * (1.0 - progress) - fragmentation.min(30.0);
        if post_residual >= 50 {
            score += 10.0; // a fresh bin keeps large flexibility
        }
    }

    // Modulo coupling: leftovers congruent to 0 mod 10 align with item grid.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Crowd control: many open bins -> prefer tightening existing ones.
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.4;
    }

    // Mean residual pull: prefer bins near the mean to balance the pool.
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps are unusable -> heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Penalize moderate dead space that can't fit typical small items
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward tight fits relative to residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits the post-residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0; // gap useless for next item
    }

    // New empty bin candidate: only attractive when existing bins are poor fits
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count <= 1 {
            score -= 60.0; // opening new bin is fine when no good alternative
        }
        if post_residual < 20 {
            score += 30.0; // big item into fresh bin leaves little dead space
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 25.0;
        } else {
            // Reward closeness of post_residual to next item size (lookahead coupling)
            let diff = (post_residual as f64 - nxt).abs();
            score -= (30.0 / (1.0 + diff)).max(0.0) - (diff / 40.0).min(10.0);
        }
        // If next item fits exactly into current residual (pre-fit match)
        if (bin_residual as i64 - next_item_size as i64 - item_size as i64).abs() < 1 {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize waste
        score += (post_residual as f64 / 10.0).min(5.0);
    }

    // Penalize dead space: post_residual too small to ever be useful
    // (smallest item is 1; assume practical granularity ~10 from original spec)
    if post_residual < 10 && post_residual > 0 {
        score += 12.0 - post_residual as f64;
    }

    // Relative to mean residual: prefer bins with residual near/below mean
    // (keep tight bins tight, avoid wasting large-residual bins on small items)
    let mr = mean_residual;
    if mr > 0.0 {
        let rel = post_residual as f64 / mr;
        if rel < 1.0 {
            score -= 4.0 * (1.0 - rel);
        } else {
            score += 3.0 * (rel - 1.0).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win
        score += 20.0;
        // But if the item barely fits anywhere, allow new bin
        if item_size as f64 > bin_residual as f64 * 0.9 {
            score -= 22.0;
        }
        // Late in the stream, avoid accumulating many near-empty bins
        if open_bins_count > 5 {
            score += 5.0;
        }
    }

    // Mild progression scaling: tighten packing as stream advances
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer minimal post residual (tight fit)
    let mut score = post;

    // Reward near-perfect fits aggressively
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize residuals that are too small to fit even the smallest item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 + post; // dead-space penalty grows as residual shrinks
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily
    if next > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 12.0 - slack as f64 * 0.3;
    } else if next > 0 && next_item_size > post_residual && post_residual > 0 {
        // post residual can't host next item: mild penalty unless residual is large anyway
        score += (next - post).min(20.0) * 0.2;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it over a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: residual == capacity means empty bin
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when current item is large and fit elsewhere is poor
        let fill_ratio = item / cap;
        let openness = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early and when many bins already fit the item
        score += 30.0
            - fill_ratio * 25.0
            - (open_bins_count as f64).ln().max(0.0) * 2.0
            + openness * 10.0;
        // If next item is huge, a fresh bin may serve it better
        if next > 0 && next >= 0.8 * cap {
            score -= 8.0;
        }
    } else {
        // Filling an existing bin is generally good: mild global reward
        score -= 5.0;
        // Reward bins whose residual deviates favorably from the mean (using this bin
        // reduces dispersion of residuals across the fleet)
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score -= dev * 0.05;
        } else {
            score += (-dev) * 0.05;
        }
        // Crowding: many open bins -> encourage consolidation
        if open_bins_count > 4 {
            score -= 1.5;
        }
    }

    // Time-horizon modulation: early in stream, be conservative with tight fits
    // (keep bins flexible); late in stream, close bins out aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * post * 0.15; // late: residual waste matters more

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (low post_residual). Late: tolerate residuals less,
    // pushing toward perfect fits as the stream ends.
    let poly = pr * pr / (cap * cap);
    score += poly * (1.0 + 3.0 * progress) * 8.0;

    // Reward using a large fraction of the bin (smooth cubic coupling).
    let fill = it / cap;
    score -= fill * fill * fill * 25.0;

    // Penalize residuals that no plausible future item fits well:
    // smooth interaction of post_residual with mean residual dispersion.
    let mr = mean_residual.max(0.0);
    let gap = (pr - mr).abs();
    score += (gap * gap) / cap * 0.4;

    // Last-chance bin: smooth reward scaled by how tight the fit is.
    if fitting_bins_count == 1 {
        score -= (1.0 - pr / cap) * 15.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            score -= (1.0 - slack / cap) * 10.0;
        } else {
            // Dead-space penalty: next item cannot follow in this bin.
            score += (nx - pr) / cap * 6.0;
        }
    } else {
        // Near stream end: strongly prefer minimal post-residual (smooth quartic).
        score += (pr / cap).powi(4) * 20.0;
    }

    // Mild penalty for proliferating open bins, coupled with residual size.
    score += (open_bins_count as f64).ln() * (pr / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by residue modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Harmonic classes: post_residual congruent to small residues mod 10 are "usable slots"
    // for typical small items (1..=10). Penalize residues that no small item can use.
    let residue = post_residual % 10;
    if post_residual > 0 && residue > 0 && residue < 1.min(post_residual) {
        // unreachable guard, kept for class symmetry
    }
    if post_residual > 0 {
        // dead space: only unusable if less than the smallest possible item
        if post_residual < 1 {
            score += 300.0;
        }
        // harmonic reward: post_residual divisible by common item granularities
        if post_residual % 5 == 0 { score -= 25.0; }
        if post_residual % 10 == 0 { score -= 40.0; }
        if post_residual % 20 == 0 { score -= 55.0; }
        if post_residual % 25 == 0 { score -= 45.0; }
        if post_residual % 50 == 0 { score -= 60.0; }
        // awkward residues (prime-ish / odd small leftovers)
        let awkward = matches!(residue, 1 | 3 | 7 | 9);
        if awkward && post_residual < 15 { score += 60.0; }
    }

    // Lookahead coupling: harmonic match between post_residual and next item class.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 350.0; // perfect chain fit
        } else if next_item_size < post_residual {
            // how well does post_residual decompose around next item?
            let rem2 = post_residual - next_item_size;
            score -= 30.0 * (1.0 - rem2 as f64 / cap);
            if rem2 % 10 == 0 { score -= 20.0; }
        } else {
            // next item cannot follow here; penalize proportionally to overflow
            score += 0.8 * (nx - pr);
        }
        // if next item is large, prefer bins whose post_residual pairs with a future split
        if nx > 0.5 * cap && frac > 0.5 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 220.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation into fullest bins.
    if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Prefer filling bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - pr);

    // Early stream: keep bins balanced slightly; late stream: pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.3 * (pr - mean_residual);

    // New-bin candidate: default mild aversion, but attractive when current item is large
    // and would leave awkward small residue in an open bin.
    if bin_residual == bin_capacity {
        let awkward_new = item_size > 60 && post_residual < 40 && post_residual % 10 != 0;
        if awkward_new {
            score -= 80.0;
        } else {
            score += 120.0;
        }
        if open_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Small tie-break noise-free coupling with item size class (integer division buckets).
    let size_class = item_size / 10;
    score += 0.1 * size_class as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space relative to what a future item could use:
    // a gap that cannot fit the lookahead item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward gaps that can still accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    // unless this bin would otherwise be wasted.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.8 * pressure;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it mildly unattractive unless open bins
    // are nearly full (mean residual small) or count is very low.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Slight late-stream tightening: as stream progresses, avoid
    // leaving scattered small gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly matches next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.15 * slack;
            if post_residual == next_item_size {
                score -= 25.0; // perfect pairing bonus
            }
        } else {
            // Next item won't fit here; penalize wasted residual that is too small to be useful.
            let waste = post_residual as f64;
            let min_size = 1.0;
            if waste < next_item_size as f64 {
                score += 0.25 * (next_item_size as f64 - waste);
            }
            // Penalize residuals that become near-useless dead space.
            if waste < min_size {
                score += 50.0;
            }
            score += 0.10 * waste;
        }
    }

    // Compare post_residual against mean residual: leaving below-average residual
    // concentrates space, which is generally good.
    let dev = (post_residual as f64) - mean_residual;
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let base_penalty = 35.0;
        let scarcity_penalty = if fitting_bins_count == 0 { -60.0 } else { 0.0 };
        let lookahead_penalty = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            -10.0 // fresh bin can host a clean pair
        } else {
            0.0
        };
        score += base_penalty + scarcity_penalty + lookahead_penalty;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Slight preference for bins with less residual among equals (best-fit tiebreak).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize small unusable dead space quadratically
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += (10.0 - dead) * (10.0 - dead) * 2.0;
        }
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= next_item_size as f64 * 1.5;
        } else {
            // penalize leaving residual that wastes capacity for next item
            score += 30.0;
        }
        // chain fit: residual that could fit a fraction of next item
        let frac = (post_residual as f64 / next_item_size as f64).min(1.0);
        score -= frac * 20.0;
    }

    // Last chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Tightness of fit relative to residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 40.0;

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > item_size as f64 * 1.5 {
        score -= 15.0 + mean_residual * 0.05;
    }

    // New-bin candidate handling: opening a new bin wastes existing residual
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 120.0;
        // less costly early in stream or when few bins open
        score -= 60.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // if next item is large, a fresh bin is more attractive
        score -= next_item_size as f64 * 0.4;
        // if many bins are nearly full (low mean residual), new bin ok
        if mean_residual < 20.0 {
            score -= 50.0;
        }
    }

    // mild noise-free time coupling: later in stream, waste is costlier
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress * 0.5;

    // Smooth waste penalty: dead space below next item size is costly
    let waste = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        gap * gap * (1.0 + progress)
    } else {
        0.0
    };

    // Mild reward for tight fits, scaled by scarcity of fitting bins
    let scarcity = (fitting_bins_count.max(1) as f64).recip();
    let tightness = (item_size as f64 / bin_residual.max(1) as f64) - (item_size as f64 / cap);

    let mut score = pr + 40.0 * poly + 30.0 * waste - 15.0 * tightness * scarcity * (0.5 + progress);

    // Penalize opening new bins late in the stream, smoothly
    let new_bin_bonus = if bin_residual == bin_capacity {
        25.0 * (0.3 + progress)
    } else {
        0.0
    };
    score += new_bin_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer-division bands of the capacity.
    let quarter = bin_capacity / 4;      // 25
    let eighth = bin_capacity / 8;       // 12
    let cap_f = bin_capacity as f64;

    // Reward tight fits: post_residual in the lowest band is "dead space"
    // and should be strongly favored (use up the bin).
    if post_residual == 0 {
        score -= 4.0 * cap_f; // perfect fit
    } else if post_residual <= eighth {
        score -= 2.5 * cap_f; // near-perfect fit
    } else if post_residual <= quarter {
        score -= 1.2 * cap_f; // usable small gap
    } else if post_residual <= 2 * quarter {
        score -= 0.3 * cap_f; // medium gap
    }
    // Large leftover (> half capacity) gets no bonus: wasteful placement.

    // Harmonic compatibility: does the next item fit into the leftover?
    // Reward leaving a gap that the lookahead item can exactly or nearly fill.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 3.0 * cap_f; // next item fills this bin exactly
        } else if gap > 0 && (gap as u32) <= eighth {
            score -= 1.5 * cap_f; // next item almost fills it
        } else if gap > 0 && (gap as u32) <= quarter {
            score -= 0.6 * cap_f;
        } else if gap < 0 && (-(gap) as u32) <= eighth {
            score += 0.8 * cap_f; // next item barely does NOT fit: risky bin
        }
        // Modulo-harmonic bonus: leftover congruent to a small residue class
        // relative to next item size suggests reusable structure.
        let r = post_residual % (next_item_size.max(1));
        if r <= eighth && post_residual > 0 {
            score -= 0.4 * cap_f;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1.0 * cap_f;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits a bit more.
        score += 0.05 * (fitting_bins_count as f64);
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // are mostly full or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - (mean_residual / cap_f);
        score += 0.8 * cap_f * (avg_fill.clamp(0.0, 1.0)) - 0.3 * cap_f * progress;
        // But if no open bin could even fit (fitting_bins_count==0 was
        // excluded by caller), still allow it: base score is post_residual.
    }

    // Slight preference to spread load when many bins are open and mean
    // residual is high (avoid fragmenting).
    if mean_residual > 0.75 * cap_f && open_bins_count > 2 {
        score -= 0.2 * cap_f;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum plausible item (1..100 range)
    // are effectively unusable. Penalize gaps in (0, 12) heavily.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Reward leaving gaps that can fit the lookahead item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.5 * slack.min(30.0);
        } else {
            // Lookahead won't fit here: mild penalty for blocking future options
            score += 8.0;
        }
    }

    // Tight fits (small post_residual relative to item) are good placements
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and avoid opening new bins; with few bins, allow spreading.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open, reward when overloaded
        score += pressure * 3.0;
        // Early in stream, new bins are cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    } else {
        score -= pressure.min(10.0);
    }

    // Prefer bins whose residual deviates below the mean (consolidating fuller bins)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: strongly reward when the NEXT item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: this bin gets completed next step
        } else if next_item_size <= post_residual {
            // partial fit next step: reward proportional to how much is consumed
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill_ratio;
        } else {
            // next item won't fit here: penalize leaving dead space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Compare post_residual against mean residual: prefer bins that end below-average residual
    // (keeps the fleet of open bins tight and homogeneous)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, using it avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it's only chosen
    // when no open bin offers a good fit (its base post_residual = capacity - item is already large)
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if the new bin would enable a perfect chain with the next item, allow it
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 40.0;
        }
    }

    // Late in the stream: consolidate aggressively, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Dead-space penalty: small but nonzero leftovers are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 40.0;
        } else if post_residual as u32 >= next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot use the leftover: leftover is dead weight.
            score += 6.0;
        }
        // If leftover is so small no plausible item (>=1) chains well,
        // mild penalty scaled by fraction of capacity wasted.
        let waste_frac = post_residual as f64 / cap;
        score += 5.0 * waste_frac * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when existing
    // bins are crowded or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 20.0;
        // But if many bins are nearly full (low mean residual), new bin is fine.
        let mean_fill = 1.0 - mean_residual / cap;
        if mean_fill > 0.75 {
            score -= 25.0;
        }
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size >= 50 {
            score -= 12.0;
        }
    }

    // Prefer filling bins that are already mostly full (high fill ratio).
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 12.0 * fill;

    // Mild pressure when many bins are open: consolidate.
    score += 0.05 * open_bins_count as f64;

    // Global residual alignment: penalize bins far from mean residual
    // to encourage uniform depletion.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let mr = mean_residual / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress
    let poly = prn * prn * (1.0 - t) + prn * t * (1.0 - prn);
    score += 40.0 * poly;

    // Penalize tight-but-wasteful fits smoothly
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit * fit * (1.0 + 0.5 * t);

    // Reward near-perfect fill with smooth saturating term
    score -= 30.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - prn);

    // Lookahead: penalize if next item cannot use post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 12.0 * (1.0 - t) * (prn / (nxt / cap));
        } else {
            score -= 10.0 * (1.0 - prn) * t;
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - prn);
    }

    // New-bin candidate: mildly penalize early, allow late when open bins are full-ish
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t) - 10.0 * (mr / cap);
    }

    // Smooth open-bin pressure
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items are 1..100, capacity 100.
    // Class 0 (exact fit) is perfect; small classes (1..=5) are near-perfect.
    let cls = post_residual % bin_capacity;
    if cls == 0 {
        score -= 60.0; // exact fill
    } else if cls <= 5 {
        score -= 40.0;
    } else if cls <= 12 {
        score -= 15.0;
    } else if cls <= 25 {
        score -= 5.0;
    } else {
        // large dead space: penalize proportionally beyond base
        score += (cls as f64) * 0.15;
    }

    // Integer-division thresholds: can a "typical" next item still fit?
    // Harmonic classes of next_item_size relative to post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward, scaled by how snugly
            let slack = post_residual - next_item_size;
            let slack_cls = slack % 10;
            score -= 25.0 - (slack_cls as f64) * 1.2;
            if slack == 0 {
                score -= 20.0; // perfect pair
            }
        } else {
            // lookahead won't fit: residual becomes dead space for the horizon item
            score += (post_residual as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if current fit is poor.
    if bin_residual == bin_capacity {
        // neutral base: post_residual == capacity here, so add a fixed offset
        // that good fits among open bins will undercut.
        score += 45.0;
        // discourage opening bins early in the stream / when few bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 20.0 + (open_bins_count as f64) * 0.5;
        // if item is huge relative to capacity, opening fresh is more reasonable
        score -= (item_size as f64) * 0.2;
    }

    // Prefer tighter bins: closer to full before placement.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Mean residual coupling: if this bin is far below mean residual,
    // it is already tight -> extra reward for using it.
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    }

    // Harmonic class of item_size (decile) modulating waste aversion:
    let dec = (item_size / 10) % 4;
    if dec == 0 {
        score += 3.0; // tiny items: waste matters less
    } else if dec == 3 {
        score -= 4.0; // large items: pack them snugly
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Prefer tighter fits relative to bin residual.
    score -= 0.5 * (item_size as f64 / bin_residual.max(1) as f64) * 20.0;

    // Open bins pressure: discourage spreading across many bins unless fit is good.
    score += 0.15 * open_bins_count as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    // Last chance bin: reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is large and this bin would leave an awkward gap, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // Mean residual coupling: placing into a bin far from mean residual is slightly penalized.
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // New bin candidate: mildly penalize opening a new bin unless current residuals are small.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching:
    // reward exact match between post_residual and next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step pairing
        }
        // penalize leaving dead space unusable by next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0;
        }
        // reward leaving room that still fits the next item comfortably
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // last item: minimize waste directly
        score += 0.0;
    }

    // relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // penalize opening a new bin when decent alternatives exist,
    // unless residual would be tiny (good fill)
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score -= fill * 30.0; // big items justify a new bin
        if fitting_bins_count > 0 {
            score += 15.0; // discourage bypassing open bins
        }
    }

    // reward large fill ratio of this placement
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // late in stream: be greedier, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else {
        // Penalize dead space quadratically for large leftovers.
        score += (post_residual as f64) * (post_residual as f64) * 0.05;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize wasted residual relative to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic: empty bin gets a baseline penalty so we prefer
    // reusing open bins, unless the fit is poor or few bins remain.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Late in the stream, opening a new bin is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
        // If many open bins exist and mean residual is high, reuse is preferable;
        // if mean residual is low, a new bin is more attractive.
        score -= (mean_residual - 20.0) * 0.5;
        // If item is large relative to capacity, prefer a fresh bin.
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
    }

    // Mildly prefer bins with residual close to item size (perfect fit shaping).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 15.0;

    // Prefer bins below mean residual (filling the emptiest bins first keeps spread tight).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Slight penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) coupling
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth stream-progress coupling: later in the stream, residual waste matters more
    score += 12.0 * progress * norm_post * norm_post * cap;

    // Reward tight fits: subtract when post_residual is small, smoothly
    let tightness = 1.0 - norm_post;
    score -= 20.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Next-item lookahead: if the post-residual can fit the next item, reward keeping it open
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Dead space relative to next item: smooth penalty
        let gap = (next_item_size as f64 - post) / cap;
        score += 6.0 * gap * gap;
    }

    // Penalize bins far below mean residual (fragmentation), smoothly
    score += 0.05 * (mean_residual - post).abs();

    // New-bin candidate: empty bin should lose unless nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mild preference to fill already-open bins as stream matures
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "friendly" residue classes (multiples of common small sizes) are
    // more reusable, so reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Dead-space penalty for awkward residuals (small, hard-to-fill leftovers)
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr >= 10 && pr < 20 {
        score += 10.0;
    }

    // Reward residuals that are multiples of 10 or 25 (harmonic classes)
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Integer-division threshold: residual in [50, 100] is "half-bin or more"
    if pr / 50 >= 1 {
        score -= 4.0;
    }

    // Perfect fit: huge reward
    if pr == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // next item fits but leaves another awkward remainder?
        let npr = pr - next_item_size;
        if npr % 10 == 0 {
            score -= 8.0;
        }
        if npr > 0 && npr < 10 {
            score += 6.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins are nearly full on average (little usable space left).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let usable = mean_residual.max(0.0);
        // penalize new bin when mean residual is large and reusable
        score += 30.0 + usable * 0.6 - progress * 10.0;
        // if item is large relative to capacity, new bin slightly better
        if item_size >= 60 {
            score -= 8.0;
        }
        // if no open bin can fit, new bin is necessary
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference for tighter bins among many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Capacity fraction coupling: item filling > half the bin is efficient
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.5 {
        score -= fill_frac * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Mild tie-break toward fuller bins relative to mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Progression: tighten dead-space tolerance later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: leave nothing behind
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain fit: this bin will be perfectly consumed by next item
        } else if post_residual > next_item_size {
            score -= 40.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // next item cannot fit here anyway; penalize small leftover dead space
            score += 30.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit
    if bin_residual == bin_capacity {
        score += 120.0 + 10.0 * fitting_bins_count as f64;
    }

    // Waste fraction penalty (non-linear dead space)
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 50.0 * waste_frac * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space is fine; large dead space penalized super-linearly
    if post_residual > 0 {
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 60.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here: reward leaving exactly usable space
        let slack_after_next = post_residual - next_item_size;
        score -= 30.0 - (slack_after_next as f64) * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in leftover: penalize dead space more
        score += 15.0;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Tight fit bonus: item fills most of the bin residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= (fill_ratio - 0.5).abs().max(0.0) * 0.0; // placeholder no-op
    score -= fill_ratio * 10.0;

    // Prefer bins with below-mean residual (consolidate emptiness)
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // Time horizon: early in stream, be pickier about wasting space; late, just fit
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.3 * progress;

    // New-bin candidate: default attractiveness depends on how bad existing options are
    if bin_residual == bin_capacity {
        // New bin is good if item is large (little waste) or few fitting bins exist
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 0.8 + 20.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
        if item_size > 50 {
            score -= 10.0; // large items pair well with fresh bins
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post residual, with smooth quadratic penalty
    let mut score = post * (1.0 + 0.5 * norm_post);

    // Smooth polynomial coupling with stream progress: late in stream, waste matters more
    let progress_coupling = 1.0 + 0.8 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth function of item_size relative to residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // mild penalty when many bins fit, to keep preference for best fit
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let snug = 1.0 - (post - next_item_size as f64) / cap;
        score -= 8.0 * snug;
    } else if next_item_size > 0 {
        // smooth penalty if next item won't fit here
        score += 3.0 * (1.0 - post / (next_item_size as f64)).max(0.0);
    }

    // Discard bins whose residual is far from mean residual (fragmentation control)
    score += 0.5 * (post - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
        // allow new bin if existing residuals are all too small relative to item
        if bin_residual < item_size {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when the item is large
    if bin_residual == bin_capacity {
        score = 600.0 - item_size as f64 * 6.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }
        return score;
    }

    // Near-perfect fit: residual too small for any item => dead space eliminated
    if post_residual < 10 {
        score -= 60.0;
    }

    // Harmonic class: penalize residuals in awkward modulo classes
    // (residuals that are small multiples of 10 tend to be reusable)
    let m = post_residual % 10;
    score += m as f64 * 1.5;

    // Integer-division threshold: residuals >= 50 are half-empty bins, still valuable
    if post_residual >= 50 {
        score -= 10.0;
    } else if post_residual < 20 {
        score += 8.0; // awkward small residual, risky dead space
    }

    // Lookahead coupling: reward if next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
            let nxt_post = post_residual - next_item_size;
            score += nxt_post as f64 * 0.4;
        } else {
            score += 12.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Mild coupling to global state: when mean residual is high, prefer tight fits
    score += mean_residual * 0.08;

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are nearly unusable
    // (item sizes 1..100 but typical stream items are >= 10), so punish them hard.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Small-but-usable gaps: mild penalty to prefer larger leftovers.
        score += 8.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + tightness);

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize creating many open bins; encourage filling
    // existing bins when the count is already high.
    score += 2.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (best-fit style), but
    // discourage placing into bins far below the mean residual (fragmented bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if the next item fits exactly in the post-residual, reward this
    // placement strongly (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap == 0 {
            score -= 35.0;
        } else if chain_gap <= 10 {
            score -= 10.0;
        }
    }
    // If next item would be blocked by a tiny dead space we just created, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: default attractiveness decays as stream progresses and
    // as open-bin count grows, so we only open new bins when it's genuinely better
    // than a poor fit into an existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * progress + 3.0 * open_bins_count as f64;
        // But if the new item is large, opening a fresh bin for it is reasonable.
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score super-linearly as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness.powi(3);

    // Lookahead: if the next item can fill this bin's post residual, reward strongly.
    let next_fits = next_item_size > 0 && post_residual >= next_item_size;
    if next_fits {
        // Reward proportional to how well the next item fills the leftover.
        let fill_ratio = next_item_size as f64 / post_residual as f64;
        score -= 6.0 + 8.0 * fill_ratio;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: leftover too small for the next item -> penalize.
        score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // Prefer bins whose residual is below the mean (fill the emptier-relative bins),
    // gently coupling to global state.
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidation matters more: mildly favor reusing bins.
    score += 3.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate penalty: opening a new bin should only win when all
    // existing fits are poor. Penalize the empty bin, but relax the penalty
    // when the item is large relative to capacity (hard to place later).
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 8.0;
        score += 14.0 + 10.0 * progress - large_item_bonus;
        // If the next item could pair with this fresh bin, soften the penalty.
        if next_fits {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress) - 0.8 * progress * pr * x;

    // Penalize dead space quadratically, scaled by progress
    score += 30.0 * x * x * (0.5 + progress);

    // Reward tight fits
    score -= 12.0 * (item_size as f64 / cap) * (1.0 - x);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: favor bins whose post residual can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Mild preference for consolidating into fewer bins
    score += (open_bins_count as f64) * 0.05 * (x);

    // New-bin candidate adjustment: prefer opening new bin when residuals are fragmented
    if bin_residual == bin_capacity {
        score -= 10.0 * progress * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: reward exact-fit classes (0, and small residues)
    let class = post_residual % 10;
    if class == 0 {
        score -= 25.0; // perfect modulo-10 fit class
    } else if class <= 3 {
        score -= 10.0;
    } else if class >= 8 {
        score += 8.0; // large dead-space class
    }

    // Penalize residues below the smallest possible item (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item could fit in post-residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // blocks next item's fit
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when item is large and open bins are tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < item_size as f64 * 1.5;
        if tight && open_bins_count > 2 {
            score -= 15.0 * progress;
        } else {
            score += 18.0;
        }
    }

    // Fraction-of-capacity coupling: reward bins whose residual is a large fraction consumed
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Integer-division threshold on post_residual (harmonic bands of capacity/4)
    let quarter = bin_capacity / 4;
    if post_residual <= quarter / 2 && post_residual > 0 {
        score += 5.0; // tiny awkward band
    } else if post_residual > quarter * 3 {
        score -= 4.0; // still roomy
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    // A residual below the minimum item size (1..100 unknown, assume ~10) is pure waste.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // unusable tiny gap
        } else if post_residual < 20 {
            score += 25.0; // likely dead space
        } else if post_residual < 35 {
            score += 8.0; // marginal usability
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Reward tight fits relative to item size (relative waste).
    score += (post_residual as f64) / (item_size.max(1) as f64) * 15.0;

    // Open bins pressure: when many bins are open, discourage opening new ones
    // and encourage filling existing ones; when few bins, allow new bins cheaply.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 4.0;
        score += 5.0; // base cost of consuming fresh capacity
    } else {
        // Slight reward for using existing bins when many are open.
        score -= (open_bins_count as f64).min(20.0) * 1.5;
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) == (next_item_size as f64) {
        score -= 25.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item cannot use the leftover: leftover is more likely dead space
        score += (post_residual as f64).min(30.0) * 0.5;
    }

    // Stream progression: early on, be more willing to open bins (exploration);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if is_new_bin {
        score += progress * 20.0;
    } else {
        score -= progress * 5.0;
    }

    // Mean residual coupling: if this bin's residual deviates far below mean,
    // it is becoming fragmented; penalize leaving it far below the mean.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score += (mean_residual - residual_f) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small waste
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - waste / bin_capacity as f64);
    }
    // Penalize dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * post_residual as f64;
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 2.0 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Discourage opening a new bin when reasonable fits exist
    if bin_residual == bin_capacity {
        score += 50.0;
        if fitting_bins_count > 0 && next_item_size > 0 {
            score += 25.0;
        }
    }

    // Late in stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can't fit typical items (small residuals are wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly or are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // Prefer new bin late in stream or when open bins are tight.
        score += 55.0 - 30.0 * progress - 4.0 * crowding.ln().max(0.0);
        // If lookahead item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    } else {
        // Lookahead synergy: reward bins whose post-residual still fits the next item.
        if next_item_size > 0 {
            if (post_residual as u64) >= next_item_size as u64 {
                score -= 10.0;
            } else if post_residual > 0 {
                score += 5.0;
            }
        }
        // Mildly prefer bins below mean residual (consolidate emptier bins).
        score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);
    }

    // Slight preference for fewer open bins overall.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let c = bin_capacity as f64;
    let norm_r = r / c;

    // Base: penalize leftover space, quadratically for dead space
    let mut score = r + 12.0 * r * norm_r;

    // Smooth non-linear coupling of residual with stream progress:
    // late in the stream, waste matters more; early, flexibility matters.
    let prog_coupling = (1.0 + 3.0 * progress) * (norm_r * (1.0 - norm_r)) * c * 0.5;
    score -= prog_coupling;

    // Reward tight fits smoothly: cubic falloff of fit quality
    let fit_quality = 1.0 - (r / (item_size.max(1) as f64 + 1.0)).min(4.0) / 4.0;
    score -= 8.0 * fit_quality * fit_quality * fit_quality * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let slack = (r - n) / c;
            score -= 10.0 * (-8.0 * slack * slack).exp();
        } else {
            score += 6.0 * (1.0 - n / c);
        }
    }

    // Penalize bins deviating from mean residual (keep bin pool balanced)
    score += 0.5 * (r - mean_residual).abs();

    // Mild penalty for proliferating open bins early on
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bins mildly unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "wasted" is the leftover space?
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f;

    // Perfect fit -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: leftover too small for any plausible item (sizes 1..=100)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver is nearly useless
    }

    // Reward leftovers that are "harmonically useful": divisible by common item sizes
    let useful_div = [1u32, 2, 4, 5, 10, 20, 25, 50]
        .iter()
        .filter(|&&d| d > 0 && post_residual % d == 0)
        .count() as f64;
    score -= 8.0 * useful_div;

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover can host the next item -> reward, scaled by snugness
            let snug = (next_item_size as f64) / (post_residual as f64);
            score -= 40.0 * snug;
        } else {
            // leftover cannot fit next item -> penalize proportionally to waste
            score += 0.5 * (post_residual as f64) * (1.0 - (next_item_size as f64) / (post_residual as f64 + 1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Many open bins -> discourage spreading, prefer tight packing
    score += (open_bins_count as f64) * 0.6;

    // Prefer bins tighter than the mean residual (well-utilized bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Fractional capacity thresholds: leftover in [0,0.1) or [0.25,0.5) of capacity are bad zones
    if frac > 0.0 && frac < 0.1 {
        score += 25.0;
    }
    if frac >= 0.25 && frac < 0.5 {
        score += 10.0;
    }

    // Integer-division threshold: leftover in same "quarter" as next item size class
    let q_left = post_residual / 25;
    let q_next = if next_item_size > 0 { next_item_size / 25 } else { 4 };
    if next_item_size > 0 && q_left == q_next && post_residual >= next_item_size {
        score -= 15.0; // leftover class matches next item class
    }

    // New-bin candidate: only attractive late in stream or when current bin fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 0.6 * cap_f;
        score += 300.0 - 150.0 * progress;
        if poor_fit {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 40.0 } else if post_residual < 20 { 18.0 } else { 0.0 };
        score += dead;
    }

    // Reward tight fits.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // Last-chance bin bonus: avoid wasting the only fitting bin's space badly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Lookahead: prefer bins leaving room for the next item.
    if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        score -= 8.0;
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 10.0;
    }

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residuals below the mean (consolidate space).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared post-residual penalizes wasted space superlinearly.
    score += 0.5 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: strongly favor bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = if (post_residual as i64 - next_item_size as i64).abs() as f64 > 0.0 {
            (post_residual as i64 - next_item_size as i64).abs() as f64
        } else {
            0.0
        };
        if post_residual >= next_item_size {
            // Next item can chain into this bin: reward closeness of match.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: dead space penalty grows with gap.
            score += 10.0 * gap / bin_capacity as f64;
        }
    }

    // Last-chance bin: penalize leaving it, since failing to use it opens a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists (high mean residual spread
    // or current bin would leave large unusable residue).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        // Opening a bin costs ~half a wasted bin on average; accept when waste is large.
        score = 45.0 + 60.0 * (1.0 - waste) - 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin supports the lookahead chain
        }
    }

    // Mild preference for bins below mean residual (consolidate space).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap);
        } else {
            // next item cannot use leftover; penalize proportionally to waste
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins among many open bins (best-fit reinforcement).
    score -= (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Time horizon: early in stream, be tolerant of loose fits (future flexibility);
    // late in stream, be greedy about residual space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.15;
    score -= progress * (bin_residual as f64 / cap) * 5.0;

    // Global state: if mean residual is high, discourage leaving more slack than needed;
    // if mean residual is low (bins nearly full), favor opening fresh capacity.
    if bin_residual == bin_capacity {
        // New-bin candidate: open new bin when existing bins are crowded or fit is bad.
        let avg_fit = mean_residual.max(0.0);
        let bad_fit = post_residual as f64 > cap * 0.5;
        if avg_fit < cap * 0.25 || bad_fit {
            score -= 15.0 + avg_fit;
        } else {
            score += 10.0 + avg_fit * 0.5;
        }
    } else if (post_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: penalize residual scaled by progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Penalize dead space relative to mean residual (smooth interaction)
    score += 6.0 * (pr - mean_residual) / cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_item;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Small post_residual = tight fit: reward strongly (sub-additive, quadratic).
    if post_residual <= 10 {
        score -= 40.0 + 4.0 * (10 - post_residual) as f64;
    } else if post_residual <= 25 {
        score -= 12.0;
    } else if post_residual <= 50 {
        score -= 3.0;
    }

    // Modulo-class logic: residuals divisible by common item sizes (10, 20, 25, 50)
    // are more likely to be perfectly filled later — reward them.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 { score -= 6.0; }
        if r % 20 == 0 { score -= 3.0; }
        if r % 25 == 0 { score -= 2.5; }
        if r % 50 == 0 { score -= 2.0; }
        // Odd/awkward classes penalized mildly.
        if r % 10 != 0 && r < 10 { score += 0.0; }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves further residue: partial reward scaled by fit tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this bin's residue: penalize dead space a bit.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; the penalty shrinks as the stream matures.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 18.0 - 6.0 * progress;
        // If many bins are open and mean residual is high, opening new bins is worse.
        score += 0.05 * open_bins_count as f64 + 0.02 * mean_residual;
    } else {
        // Prefer bins with below-average residual (denser bins first).
        score -= (mean_residual - pr) * 0.3;
    }

    // Capacity-fraction coupling: reward filling past half capacity.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill >= 0.5 { score -= 4.0 * fill; }
    if fill >= 0.9 { score -= 5.0; }

    // Integer-division thresholds: post_residual in (0,10) is near-dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // too small for any item (min size ~1..10 range guard)
        // but if truly unusable given min item size 1, keep mild.
        if post_residual == 0 { score -= 100.0; } // perfect fit
    }
    if post_residual == 0 { score -= 100.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if it cannot fit a typical future item (small threshold).
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
        if (post_residual as f64) < dead_threshold {
            // Squared penalty: tiny gaps are worthless.
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
        // Perfect fit bonus: reward exact fills.
        if post_residual == 0 {
            score -= 25.0;
        }
        // Reward gaps that can still fit the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 {
            // Gap too small for the next item: mild penalty.
            score += 4.0;
        }
    }

    // Open bins pressure: discourage proliferating bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.3 + 0.7 * progress);

    // Relative fill reward: prefer bins where item consumes a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // existing bins would leave large dead space or none fit well.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        // Baseline cost of opening a bin.
        score += 30.0;
        // More attractive late in the stream when mean residual is high
        // (open bins are fragmented) — but still pay the opening cost.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
        // If this bin is the only fitting option, opening is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for tighter existing bins vs mean residual.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // 2-step lookahead: reward bins whose post_residual exactly or nearly fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Exact match is ideal; decaying reward as gap grows.
            score -= 30.0 * (-gap / 15.0).exp();
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead potential.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
        // Bonus if this bin plus item plus next item fills bin almost completely.
        if post_residual + next_item_size as u32 <= bin_capacity {
            let combined_left = (bin_capacity - item_size - next_item_size.min(bin_capacity)) as f64;
            score -= 10.0 * (-combined_left / 10.0).exp();
        }
    } else {
        // Last item: just minimize post_residual hard.
        score += 20.0 * tightness;
    }

    // Relative to mean residual: prefer bins that are more filled than average (below-mean residual).
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 15.0 + 10.0 * (1.0 - poor_fit) - 5.0 * poor_fit;
        // Early in stream, opening bins is cheaper; late in stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Few open bins => opening is more acceptable.
        score -= 2.0 * open_bins_count as f64;
    }

    // Slight penalty for leaving tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 12.0; // perfect lookahead fit
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // unless the item fits almost exactly.
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Penalize opening a new bin when decent alternatives exist,
    // but allow it late in the stream or when open bins are very full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open_fill = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let pressure = avg_open_fill * open_bins_count as f64;
        score += 25.0 - 10.0 * progress - 6.0 * pressure;
        if next_item_size > 0 && post_residual >= next_item_size && item_size <= 30 {
            score -= 5.0; // a fresh bin can host a follow-up small item
        }
    }

    // Mild preference for filling fuller bins earlier in the stream.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - t) * 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Normalized post residual in [0,1]
    let x = pr / cap;

    // Non-linear polynomial coupling: waste penalty grows superlinearly with residual,
    // modulated by stream progress (late stream -> penalize waste harder).
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like term in [0,1]
    let progress_weight = 2.0 + 6.0 * progress;
    score += progress_weight * poly * cap * 0.1;

    // Reward tight fits: subtract when post_residual is small, smoothly.
    let tightness = (1.0 - x).powi(3);
    score -= 4.0 * tightness;

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        let gx = gap / cap;
        // smooth reward peaked when gap is small
        score -= 6.0 * (1.0 - gx) * (1.0 - gx) * (1.0 + progress);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; penalize leaving large unusable residual
        let nx = (next_item_size as f64) / cap;
        score += 3.0 * nx * x * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Slight preference for bins with below-mean residual (consolidate waste).
    let mean_x = mean_residual / cap;
    score += 1.5 * (x - mean_x);

    // New-bin candidate: penalize opening a new bin unless residual would be huge
    // (i.e., current bins are nearly full and item is large).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 10.0 + 8.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
        // Discount penalty if the item is large relative to capacity (a fresh bin is natural)
        let item_frac = (item_size as f64) / cap;
        score += new_bin_penalty * (1.0 - item_frac * item_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "reusable"
    // residue classes (multiples of 10, and small even leftovers) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        let class = pr % 10;
        // Residues 0 (clean decade) and 5 (half-decade) are most reusable.
        let class_bonus = match class {
            0 => 18.0,
            5 => 10.0,
            2 | 4 | 6 | 8 => 4.0,
            _ => 0.0,
        };
        score -= class_bonus;

        // Integer-division thresholds: leftovers <= 10 are dead space.
        if pr <= 10 {
            score += 12.0;
        } else if pr <= 20 {
            score += 4.0;
        }

        // Coupling with next item: reward leftovers that can host next_item_size
        if next_item_size > 0 {
            if pr >= next_item_size {
                score -= 8.0;
                // exact harmonic match: next item fills leftover to a decade
                if (pr - next_item_size) % 10 == 0 {
                    score -= 6.0;
                }
            } else {
                score += 6.0; // next item cannot use this leftover
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize so it is chosen only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.15 * open_bins_count as f64;
        // If lookahead is large relative to capacity, fresh bin slightly better.
        if next_item_size >= 70 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter bins overall (low residual before placement).
    score += 0.05 * bin_residual as f64;
    // Mild time decay: late in the stream, prefer compacting.
    score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // Gaps below the minimum item size (1..10) are pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps that cannot fit the next item are likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the post residual exactly accommodates the next item,
    // this bin is an excellent chain candidate.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize creating more bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins are open or
        // the item is large and would leave big gaps elsewhere.
        score -= 15.0;
        score += open_bins_count as f64 * 1.5;
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Mild global pressure: keep mean residual low by favoring bins
    // with residual below the mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Stream progression: early on, be more willing to open new bins;
    // later, consolidate into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 20.0;
    } else {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0; // chain perfectly: next item fills this bin exactly
        } else {
            // penalize mismatch, scaled by how far off we are
            score += diff as f64 * 0.35;
        }
        // bonus if next item still fits after this placement
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // dead space smaller than next item is wasted
            score += 18.0;
        }
    }

    // Zero residual: perfectly closed bin is excellent
    if post_residual == 0 {
        score -= 45.0;
    }

    // Penalize leaving tiny unusable slivers (likely dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits: small post_residual relative to item size
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin before opening a new one: strong preference to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        score += 35.0;
        // allow new bin when open bins have little usable space left
        if mean_residual < item_size as f64 * 0.5 {
            score -= 50.0;
        }
    } else {
        // favor bins whose residual deviates favorably from the mean (more room)
        score -= (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Late in the stream: consolidate harder, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect fills strongly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Penalize dead space that is too small to be useful later (wasted capacity)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 10.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // next item cannot use the leftover; mild penalty scaled by wasted gap
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is justified only when existing
    // residuals are poor fits or the stream is early with plenty of small items expected
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 15.0;
        // Early in the stream, or many open bins with fragmented residuals: new bin cheaper
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score -= (1.0 - t) * 10.0;
        if fragmentation < 0.3 && open_bins_count > 0 {
            score -= 12.0;
        }
        // If item is large, a fresh bin is attractive
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward relative fit vs mean residual state
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= fit_ratio * 8.0;
        // Prefer bins with residual close to item (best-fit flavor)
        let diff = (bin_residual as f64 - item_size as f64).abs();
        score += diff * 0.25;
        // Spread load: with many open bins, favor consolidating into fuller ones
        if open_bins_count > 3 {
            score -= (bin_residual as f64 / bin_capacity as f64) * 6.0;
        }
    }

    // Late-stream consolidation: as stream ends, avoid opening new bins
    score += t * 12.0 * if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, quadratically
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 - norm_pr) * (progress * (1.0 - progress) * 4.0);
    score += 20.0 * coupling;

    // Perfect fit reward (smooth)
    score -= 15.0 * (1.0 - norm_pr).powi(8);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Penalize leaving residual smaller than plausible next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr > 0.0 && pr < ni {
            score += (ni - pr) * (0.5 + progress);
        } else if pr >= ni {
            score -= 3.0 * (pr - ni) / cap;
        }
    }

    // Slight preference for tighter bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: coarse buckets via capacity/8 division
    let class = post_residual / (bin_capacity / 8).max(1);
    score += class as f64 * 4.0;

    // Exact-fit class: post_residual in tiny harmonic band is highly desirable
    if post_residual < 5 {
        score -= 60.0;
    } else if post_residual < 12 {
        score -= 25.0;
    }

    // Dead-zone class: residuals in [13, 29] are hard to fill with items >=10
    if post_residual >= 13 && post_residual < 30 {
        score += 35.0;
    }

    // Modulo coupling: post_residual mod 10 — small remainders are "clean" classes
    let rem = post_residual % 10;
    score += (10 - rem) as f64 * 0.6;

    // Lookahead harmonic: can next_item_size exactly consume the post_residual class?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 30.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual at all -> penalize small leftovers
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 50.0;
    }

    // Last-chance bonus: only this bin fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only good when item is large
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score -= 15.0 * (frac - 0.6);
        } else {
            score += 40.0 * (0.6 - frac);
        }
    }

    // Mean residual coupling: placing into a bin far below mean residual spreads space
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.25;

    // Stream phase: late in stream, consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 2.0;

    // Integer-division threshold on next_item_size classes
    let nclass = next_item_size / 20;
    score -= nclass as f64 * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Penalize gaps that are too small to be useful for typical future items.
        let unusable = if dead < 10.0 { 1.0 } else if dead < 20.0 { 0.6 } else if dead < 30.0 { 0.25 } else { 0.0 };
        score += 40.0 * unusable;
        // Mild superlinear pressure on the gap itself.
        score += 0.05 * dead * dead / bin_capacity as f64;
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits in the post residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if next_item_size > bin_capacity {
            // next item larger than capacity edge case; ignore
        } else {
            // Next item won't fit here: slight penalty for wasting the gap.
            score += 5.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins are tight/fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Opening a new bin is penalized mildly; it wins only if open bins would leave bad gaps.
        score += 20.0 + 0.1 * open_bins_count as f64;
        // But if all fitting bins would create dead space, new bin becomes competitive:
        if fragmentation > 0.0 && mean_residual < 15.0 {
            score -= 30.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean (balanced usage),
    // but reward using the tightest bin (small bin_residual) slightly.
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to capacity
        score += (post_residual as f64 / bin_capacity as f64) * 50.0;
    }

    // 2-step lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0;
        // Even better: next item nearly fills the bin after this placement
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 120.0;
        } else {
            score += (next_post as f64 / bin_capacity as f64) * 30.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally
        score += ((next_item_size - post_residual) as f64 / bin_capacity as f64) * 40.0;
    }

    // Prefer bins tighter than average (best-fit style)
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Early in stream: be slightly conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    // Discourage opening a new bin when a decent fit exists
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 {
        // Reward residuals that can still host a next item of known size.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 6.0 + (next_item_size as f64) * 0.1;
            } else {
                score += (next_item_size - post_residual) as f64 * 0.4;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive; penalize it unless
    // current item leaves a very poor residual in every fitting bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening bins is cheaper (more future items to fill them);
        // late in the stream, avoid opening bins.
        score += 30.0 - 25.0 * progress;

        // If the item fits perfectly in a fresh bin, opening is attractive.
        if post_residual == 0 {
            score -= 40.0;
        }
        // If many bins are open with slack, discourage a new one.
        score += open_bins_count as f64 * 1.5;

        // If mean residual across open bins is large, definitely use an existing bin.
        score += mean_residual * 0.5;
    }

    // Mild preference for bins with smaller residual (best-fit flavor) modulated by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64) * 0.05 * (1.0 - progress);

    // Slight penalty when many bins are open: consolidate to reduce fragmentation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer low post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth coupling of post-residual with stream progress:
    // later in the stream, tight fits matter more
    score += 30.0 * pr_norm * pr_norm * progress;

    // Penalize post-residual that cannot fit the lookahead item (smooth gate)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (nx - pr).max(0.0) / cap;
        score += 25.0 * waste * waste * (1.0 + progress);
        // Reward post-residual that exactly accommodates the next item
        let fit_gap = (pr - nx) / cap;
        score -= 10.0 * (-fit_gap * fit_gap * 40.0).exp() * fit_gap.max(0.0);
    }

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - pr_norm) * (0.5 + 0.5 * progress);
    }

    // Mild dispersion penalty: avoid draining bins far below mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, more so when open bins exist and fit
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Fragmentation penalty: small dead space is useless
    score += 15.0 * (-(pr / 12.0).powi(2)).exp() * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by small
    // moduli are more reusable by typical item sizes.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit, strongly favored
    } else {
        let mut hb = 0.0;
        if pr % 10 == 0 { hb -= 8.0; }
        if pr % 20 == 0 { hb -= 4.0; }
        if pr % 25 == 0 { hb -= 3.0; }
        if pr % 5 == 0 { hb -= 2.0; }
        // Dead space penalty for small unusable remainders
        if pr < 10 { hb += 15.0; }
        else if pr < 20 { hb += 6.0 * (pr as f64 / 10.0); }
        hb
    };
    score += harmonic_bonus;

    // Lookahead coupling: does the leftover accommodate the next item's class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact-class match is best
            if post_residual == next_item_size {
                score -= 20.0;
            } else {
                let gap = post_residual - next_item_size;
                // favor gaps that are again harmonic (small or round)
                if gap == 0 { score -= 15.0; }
                else if gap % 10 == 0 { score -= 6.0; }
                else if gap < 10 { score += 4.0; }
                score -= 5.0; // generic bonus for chaining
            }
        } else {
            // leftover too small for next item: penalize proportionally
            score += 8.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        // prefer new bin when item is big and mean residual is small
        let new_bin_score = 45.0
            + 0.5 * (item_size as f64)
            + 30.0 * crowding
            + 10.0 * progress;
        score = score.min(new_bin_score);
        // make empty bin unattractive by default
        score += 25.0;
    }

    // Mild penalty for spreading across many open bins when residuals are high
    if open_bins_count > 4 && post_residual > 50 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: gaps too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Exact fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over opening new ones.
    score += 0.8 * open_bins_count as f64;

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave a tiny gap, penalize slightly.
    if next_item_size > 0 && post_residual as u32 >= next_item_size {
        let nxt_post = post_residual as u32 - next_item_size;
        if nxt_post > 0 && nxt_post < 10 {
            score += 10.0;
        }
    }

    // New-bin candidate: make it moderately attractive only when residuals
    // across open bins are large and fragmented (mean residual high relative
    // to item size) or when this bin would otherwise be a poor fit.
    if bin_residual == bin_capacity {
        // Base handicap so existing bins with good fits win.
        score += 5.0;
        // Attractive when open bins are crowded (little usable residual).
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (-gap / 20.0).exp(); // strong bonus for exact/near-exact next-item fit
        // Penalize residuals that can neither fit the next item nor much of anything
        if post_residual < next_item_size {
            score += 15.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Dead-space penalty: tiny residuals are nearly unusable (items >= 1 though, so mild)
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin when the stream is early
    // or when open bins are loose, but allow it late to spread load.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Slight preference for filling tighter bins overall
    score += 0.3 * (bin_residual as f64 - item_size as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize creating small unusable dead space (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: slight penalty for wasting space.
            score += 3.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when current fit is poor
    // and the item would leave a large awkward residual in an existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty to prefer existing bins when fits are reasonable.
        score += 20.0;
        // If the item fits perfectly in a fresh bin (item_size == capacity unlikely, else
        // moderate residual), reduce the penalty proportionally to wasted space in existing bins.
        let waste_existing = (bin_residual - item_size) as f64;
        if waste_existing > 0.5 * bin_capacity as f64 {
            score -= 25.0; // existing bins would waste half the space; new bin is fine
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many open bins already have large mean residual, prefer filling them.
        if mean_residual > 0.5 * bin_capacity as f64 {
            score += 10.0;
        }
    }

    // Mild preference for balancing: avoid dumping into the bin with the largest residual
    // when it creates a big leftover, unless it is a near-perfect fit.
    if !is_new_bin {
        let residual_gap = bin_residual as f64 - mean_residual;
        score += 0.05 * residual_gap.max(0.0);
    }

    // Dynamic time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - fit_ratio);

    // Small nudge toward fewer open bins late in the stream.
    if open_bins_count > 3 && progress > 0.7 && !is_new_bin {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fits less aggressively (spread items); late, minimize waste strongly.
    let mut score = pr * (1.0 + 2.0 * progress * x) + 30.0 * x * x * progress;

    // Smooth interaction: dead space penalty grows non-linearly with progress.
    score += 20.0 * x * x * x * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress) + 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = pr - nxt;
        if fit_gap >= 0.0 {
            score -= 10.0 * (1.0 - (fit_gap / cap).exp());
        } else {
            score += 8.0 * ((-fit_gap) / cap);
        }
    }

    // Mild preference to keep mean residual balanced (avoid many near-empty bins).
    score += 0.05 * (mean_residual - pr).abs() * progress;

    // New-bin candidate: penalize slightly unless current residual is very tight.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues modulo small divisors
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize tiny dead space classes (post_residual in [1..10]) — nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class reward: leftover divisible by common item sizes (10, 20, 25, 50)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next item fit the leftover?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or leaves a good class
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 40.0;
            } else if next_post < 10 {
                score -= 10.0; // leaves tiny residue but consumed well
            } else if next_post % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize proportional to mismatch class
            let gap = next_item_size - post_residual;
            score += (gap % 20) as f64 * 0.5;
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately unattractive unless current bin is very full
    if bin_residual == bin_capacity {
        score += 15.0;
        // but attractive if mean residual across open bins is tiny (all bins nearly full)
        score -= (mean_residual / cap).max(0.0) * 40.0;
    }

    // Fractional dead-space penalty: quadratic in waste fraction
    score += frac * frac * 30.0;

    // Progression: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Many open bins: discourage spreading, favor filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (10) are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // create unusable dead space -> strongly penalize
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: reward heavily
    }

    // Reward tight fits relative to bin capacity
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, prefer it over opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // penalize new bin when open bins still have room and item fits reasonably
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // if next item is large, a fresh bin may be useful
        if next_item_size >= 60 && fill_ratio > 0.6 {
            score -= 15.0;
        }
        let _ = mean_tightness;
        let _ = step_index;
        let _ = total_items;
    } else {
        // favor bins whose residual is close to item size (tight packing)
        let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 15.0 * waste;
        // lookahead: if next item fits the post residual, bonus
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // late in stream, consolidate to avoid opening extra bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress;
    }

    // deviation from mean residual: prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Perfect match: post_residual exactly fits the next item.
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 50.0 * (1.0 - diff / (bin_capacity as f64));

        // Penalize dead space: post_residual too small for next item but nonzero.
        if post_residual < next_item_size {
            score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
        }

        // Bonus for leaving space usable by the average next item.
        if post_residual >= next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 20.0;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize bins far below mean residual (fragmented small leftovers),
    // reward bins near mean residual.
    let mr = mean_residual;
    if mr > 0.0 {
        let rel = post_residual as f64 / mr;
        score += 5.0 * (rel - 1.0).abs();
    }

    // Tight fit reward relative to capacity.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Late in stream: prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress;

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.4 * open_bins_count as f64;

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * fill;
        if fitting_bins_count == 1 {
            score += 10.0; // opening a new bin is fine if the only fit is poor
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual nonlinearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Discourage spreading when many bins are open (fragmentation control).
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 3.0;
    }

    // Time-horizon modulation: early on, be conservative; late, exploit tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // Compare against mean residual: prefer bins with residual below mean (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.25;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 20.0 } else { 12.0 };
        score += pressure + (item_size as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping of post-residual.
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Stream-progress coupling: dead space becomes more costly as the stream advances.
    score += 3.0 * progress * norm_pr * norm_pr;

    // Reward filling bins almost exactly (post_residual near zero), smoothly.
    score -= 4.0 * (1.0 - norm_pr).powi(6) * (1.0 - progress);

    // Lookahead coupling: penalize residual that neither fits the next item nor is tiny.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 1.5 * (1.0 - slack * slack);
        } else {
            let waste = (ni - pr) / cap;
            score += 2.0 * waste * (1.0 + progress);
        }
    } else {
        // Last item: strongly prefer zero residual.
        score -= 5.0 * (1.0 - norm_pr);
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5 * (1.0 - progress);
    }

    // Mild penalty for opening a new bin when many bins are open and mean residual is high.
    if bin_residual == bin_capacity {
        score += 1.0 + 0.05 * open_bins_count as f64 + (mean_residual / cap) * 2.0;
    } else {
        // Slight preference for bins with below-mean residual (tighter bins).
        score += 0.5 * ((pr - mean_residual) / cap).max(-1.0).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity / 4 granularity
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);

    // Reward tight fits (small post_residual classes)
    match class {
        0 => score -= 40.0,                    // near-perfect fit
        1 => score -= 18.0,                    // good fit
        2 => score -= 6.0,                     // moderate fit
        _ => score += 8.0,                     // large dead space
    }

    // Modulo-5 harmonic penalty: leftovers that pair well with small items
    let m5 = post_residual % 5;
    if m5 == 0 {
        score -= 5.0;
    } else if post_residual % 10 == 0 {
        score -= 4.0;
    } else {
        score += m5 as f64 * 0.8;              // awkward remainder sizes
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact-ish match is a double win
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0;
            } else if gap <= 10 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // penalize opening new bins mildly, more as stream matures
        score += 55.0 + 25.0 * (1.0 - progress) - 10.0 / pressure;
        // but if current item is huge and mean residual is low, allow it
        if item_size >= bin_capacity * 3 / 4 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    }

    // Mild preference for filling bins that are already relatively full
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 6.0;

    // Discourage leaving residuals in the "useless zone" (just above half-capacity classes)
    if post_residual > quarter * 2 && post_residual < quarter * 3 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        // A residual is "dead" if it's too small for the smallest plausible item.
        let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
        if (post_residual as f64) <= dead_threshold {
            score += 60.0 * (dead_threshold - post_residual as f64 + 1.0);
        }
        // Non-linear penalty: residual that fits nothing likely next is wasted.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else if next_item_size > 0 && post_residual == next_item_size {
            // Perfect lookahead fit: strong reward.
            score -= 45.0;
        }
    } else {
        // Perfect packing: strong reward.
        score -= 70.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    score -= 8.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.9 * open_bins_count as f64;

    // Prefer bins with residuals below mean (compact bins), penalize above.
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when open bins would create
    // large dead space or no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by potential usefulness.
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            // New bin preserves room for a large next item.
            score -= 18.0;
        }
        if item_size >= 70 {
            score -= 10.0; // large items fit best in fresh bins
        }
    }

    // Late-stream consolidation: as stream progresses, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward perfect match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        // Exact 2-step match is a huge bonus.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual that next item cannot use but is too big to be dead space.
        if next_item_size > post_residual as u32 && post_residual > 0 {
            score += 10.0;
        }
    } else {
        // Last item: prefer tightest fit (smallest post residual already in base).
        score -= 20.0;
    }

    // Compare post_residual against mean residual: leaving less than mean is good (consolidation).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: neutral baseline; make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = 50.0 + post_residual as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.9 {
            score -= 30.0; // big next item: fresh bin is useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to typical upcoming item sizes.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill bonus
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 8.0;
    } else if post_residual > 60 {
        score += 15.0; // wasteful placement
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot follow here; mild penalty unless post_residual tiny
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // More competition for this bin: prefer the best fit among many.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: prefer filling bins in bins with low mean residual
    // (keeps fragmented bins from being abandoned).
    score += 0.2 * (mean_residual - post_residual as f64);

    // Time horizon: early in stream, be conservative (favor tight fits more);
    // late in stream, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins that are already fairly full (low residual) to consolidate.
    score += 0.1 * bin_residual as f64;

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        // New bin default score: keep it competitive but usually worse than a
        // decent fit; attractive when item is huge or nothing fits.
        score = 70.0 * (1.0 - big_item) - 40.0 * pressure + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: penalize wasted space, scaled non-linearly by item size
    let mut score = pr * (1.0 + 0.5 * fit * fit);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, keep bins roomy; later, tolerate tighter residuals less
    let t = progress;
    let coupling = (pr / cap).powi(2) * (0.5 + 2.0 * t * (1.0 - t) * 4.0);
    score += 30.0 * coupling;

    // Reward tight fits smoothly (small post_residual relative to item)
    score -= 20.0 * (fit * (1.0 - pr / cap)).powi(2);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0 * nxt * (1.0 - t);
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly unless residuals of open bins are too small
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / cap;
        score += 10.0 - 25.0 * avg_fit * (1.0 - t);
    }

    // Mild penalty for bin proliferation
    score += 0.3 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction band it lands in.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..=8 harmonic band

    // Penalize dead space nonlinearly: small post-residuals are good.
    match class {
        0 => score -= 30.0,                       // near-perfect fit
        1 => score -= 15.0,                       // excellent
        2 => score -= 6.0,                        // good
        3 | 4 => { score += 2.0; }                // mediocre half-bin-ish
        _ => { score += (class as f64 - 4.0) * 5.0; } // large waste
    }

    // Lookahead: reward if next item fits exactly into post residual (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let pair_waste = post_residual - next_item_size;
            let pair_class = pair_waste / eighth;
            if pair_class <= 1 { score -= 12.0; }
            else { score -= 12.0 / (pair_class as f64); }
        } else {
            // Next item cannot use this bin's remainder; penalize more if waste is in an awkward class.
            if class >= 5 { score += 8.0; }
        }
    } else {
        // Last item: just minimize waste strongly.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer only if current fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > (quarter as f64);
        if poor_fit {
            score -= 10.0 + 10.0 * progress;
        } else {
            score += 25.0; // keep using well-matched open bins
        }
        // Slight preference for fewer open bins late in stream.
        score += open_bins_count as f64 * 0.05;
    }

    // Coupling with mean residual: if this bin is tighter than average, prefer it.
    let tightness = mean_residual - post_residual as f64;
    score -= tightness * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Open-bin pressure: discourage scattering across many bins when tight fits exist.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this residual: small residual becomes dead space.
        score += 10.0;
    }

    // New-bin candidate: prefer only when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 15.0 - pressure * 10.0 + open_bins_count as f64 * 2.0;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward post_residual that exactly matches the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Perfect match for next item is extremely attractive.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += 0.6 * diff;
        }
        // Reward post_residual that can still hold the next item, penalize otherwise.
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0 + 0.3 * pr; // dead space that next item cannot use
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin (only fitting bin): strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Tight fits (small leftover) are good.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Default mild penalty so open bins are preferred unless they fit poorly.
        score += 12.0;
        if pressure > 0.0 {
            score -= 50.0;
        }
        // Late in stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for bins with small residual overall (best-fit flavor).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but dead space below a
    // useful threshold is worse than a perfect fit. Penalize small gaps.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // gaps that can't hold even the smallest plausible item are dead space
        if gap < 10.0 {
            score += 15.0 * (10.0 - gap);
        }
        // prefer gaps that exactly match the next item (perfect chain)
        if next_item_size > 0 && (post_residual as u32) == next_item_size {
            score -= 20.0;
        }
    } else {
        // perfect fill
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward;
    // if not, penalize leaving residual that next item can't use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer
    // consolidating into bins below mean residual (denser bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let relative_residual = bin_residual as f64 / bin_capacity as f64;
    let mean_rel = mean_residual / bin_capacity as f64;
    if mean_rel > 0.0 {
        // bins tighter than average get a bonus, looser get penalized
        score += 10.0 * (relative_residual - mean_rel);
    }

    // Time horizon: early on, be more willing to open new bins (explore);
    // late, consolidate aggressively to avoid opening bins.
    let exploration_bonus = (1.0 - progress) * 6.0;
    let consolidation_bonus = progress * 12.0;
    if bin_residual == bin_capacity {
        // new-bin candidate: accept early, resist late unless item is large
        score += exploration_bonus - consolidation_bonus;
        // a new bin is more attractive for large items that would wreck an
        // open bin's residual
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    } else {
        // using an existing bin: reward more as stream progresses
        score -= consolidation_bonus * relative_residual;
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual

    // Smooth polynomial base: reward tight fits (low post_residual)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let px = x * x;
    let cx = x * x * x;
    score -= 30.0 * px * (1.0 - progress);
    score += 20.0 * px * progress;
    score += 15.0 * cx * (2.0 * progress - 1.0);

    // Penalize dead space relative to mean residual (smooth coupling)
    let dead = (pr as f64 - mean_residual).max(0.0);
    score += 0.5 * dead * (0.5 + progress);

    // Lookahead: reward leaving space close to next item size (smooth gaussian-like)
    if next_item_size > 0 {
        let d = (pr as f64 - next_item_size as f64) / cap;
        score -= 25.0 * (-20.0 * d * d);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Mild penalty for bin proliferation early on
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space buckets via integer division
    let pr = post_residual;
    let class = pr / 10; // 0..10 harmonic class
    // Penalize small-but-unusable residuals (dead space) nonlinearly
    if pr > 0 {
        let frac = pr as f64 / cap;
        if frac < 0.10 {
            score += 12.0 * (0.10 - frac); // tiny slivers are worthless
        } else {
            score -= 6.0 * frac; // large residual keeps future flexibility
        }
    }

    // Modulo coupling: residuals in {0, 25, 50, 75} are "harmonic" with common item sizes
    if pr % 25 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 2.0;
    }
    // Odd residuals unlikely to be filled exactly
    if pr % 2 == 1 && pr < 20 {
        score += 3.0;
    }

    // Lookahead: can next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // perfect harmonic continuation
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score += 0.35 * slack; // penalize leftover after next item too
        } else {
            score -= 1.5; // next item won't fit anyway; residual less valuable
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive for large items leaving useful residual
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 3.0 + 5.0 * frac;
        } else {
            score += 6.0 * (0.5 - frac); // discourage new bins for small items
        }
    }

    // Stream progression: late in stream, prefer tightening bins (less waste)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (mean_residual / cap);

    // Crowd penalty: many open bins -> favor consolidating into tightest fits
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harshly (dead space in 1..20 range)
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward fitting into bins that fit the item, especially when few alternatives
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open bins pressure: discourage spreading into many open bins
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item is large and post_residual too small, penalize creating dead space
    if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Progress scaling: tighten behavior as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: next item fits exactly into the post-residual space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Partial lookahead reward, decaying with leftover after the next item.
            let after_next = post_residual as f64 - next_item_size as f64;
            score -= 200.0 - 2.0 * after_next;
        } else {
            // Next item won't fit here: penalize wasting residual space it can't use.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Brand-new bin candidate: mild penalty so it's chosen only when clearly better.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Prefer filling bins that are already partially used as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += (mean_residual - post_residual as f64) * 0.5;

    // Time horizon: early in stream, be more willing to open new bins;
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: score based on how bad the alternatives are.
        let base = 100.0 - 40.0 * progress;
        // Open a new bin if the current bin leaves awkward leftover space.
        if post_residual > 0 && post_residual < 10 {
            score = base - 50.0;
        } else {
            score = base + post_residual as f64 * 0.3;
        }
        if fitting_bins_count == 1 {
            score += 80.0; // don't abandon the only fitting bin
        }
    } else {
        score -= 20.0 * progress * fit_ratio;
    }

    // Mild penalty for using very empty bins when others are fuller.
    if bin_residual as f64 > mean_residual + 20.0 && bin_residual < bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: early on, tolerate loose fits;
    // later, tighten preference for small post_residual.
    let prog_coupling = 1.0 + 1.5 * progress * progress + 2.0 * progress * norm_pr;
    score *= prog_coupling;

    // Penalize post residual that cannot fit a plausible next item (dead space),
    // smoothly weighted by how much of the bin is wasted.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = (nxt - pr).max(0.0) / cap;
        score += 30.0 * unusable * unusable * (0.5 + progress);
        // Reward bins whose post residual still accommodates the lookahead item.
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, scaled smoothly by item tightness.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 25.0 * (0.3 + 0.7 * tightness);
    }

    // Mild penalty for spreading across too many open bins, smooth in count.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);

    // Encourage balance with the mean residual: avoid outliers in either direction.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: keep its score neutral-high so it's chosen only when
    // open bins offer poor fits; smooth ramp with progress.
    if bin_residual == bin_capacity {
        score += pr * (1.2 + 0.6 * progress) + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of 10, and small odd chunks) are preferred.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold class
    let residue = pr % 10;

    // Reward post-residuals in coarse harmonic buckets: 0 dead space is perfect,
    // 50 is half-capacity (most reusable), tiny leftovers (1..9) are dead space.
    match class {
        0 => {
            if pr == 0 { score -= 60.0; }        // perfect fit
            else { score += 25.0 + residue as f64; } // dead space penalty
        }
        1 => { score += 8.0; }                    // 10-19: poor reuse
        2 => { score -= 5.0; }                    // 20-29: decent
        3 => { score -= 12.0; }                   // 30-39: good
        4 => { score -= 18.0; }                   // 40-49: very good
        5 => { score -= 20.0; }                   // 50: half-bin, maximally reusable
        6 => { score -= 15.0; }
        7 => { score -= 10.0; }
        _ => { score -= 6.0; }                    // large residuals: fresh bins
    }

    // Nonzero residue modulo 10 => future items rarely fill exactly; penalize.
    if residue != 0 {
        score += residue as f64 * 0.8;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0);
        } else {
            // next item won't fit here at all: mildly penalize wasting this bin now
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        if crowding < 0.35 {
            score -= 15.0; // open bins nearly full -> fresh bin is fine
        } else {
            score += 40.0; // plenty of room elsewhere -> avoid bin proliferation
        }
    }

    // Mild stream-progress term: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // Tie-break toward tighter bins overall.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host a
    // typical future item are unusable gaps -> penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // If the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover: mild penalty unless
        // leftover is still large enough to be generally useful.
        if post_residual < 30 {
            score += 12.0;
        }
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when this bin
    // would leave a bad gap or open bins are already numerous.
    if bin_residual == bin_capacity {
        score += 10.0;
        if post_residual < 20 {
            score += 35.0;
        }
        score += open_bins_count as f64 * -0.3;
    }

    // Slight preference for tighter-than-average bins.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item leaves little dead space.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 20.0 * next_tight;
            if post_residual == next_item_size {
                score -= 45.0; // chain of two perfect fits
            }
        } else {
            // Next item cannot fit here: penalize proportionally to leftover dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
            if post_residual < 10 {
                score += 15.0; // unusable sliver for the next item
            }
        }
    } else {
        // Last item: closing a bin completely is ideal.
        if post_residual == 0 {
            score -= 80.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (big-item bins).
    let rel = (bin_residual as f64) - mean_residual;
    score -= 0.08 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when decent alternatives exist,
    // but allow it when the stream is early or the fit is poor everywhere.
    if bin_residual == bin_capacity {
        score += 20.0; // new-bin base penalty
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress); // cheaper to open bins early
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        // If the item is large, a fresh bin is more attractive.
        score -= 0.1 * item_size as f64;
    }

    // Slight preference to fill bins with many occupants implicitly via residual ordering.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream, in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative fill achieved by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: subtract proportional to how well the item fills the bin
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize creating small, hard-to-use dead space (post_residual in (0, 12) is worst)
    let pr = post_residual as f64;
    if pr > 0.0 {
        let deadness = 1.0 - (pr / 12.0).min(1.0);
        score += 25.0 * deadness * deadness;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let gap = (pr - ni).abs();
            score -= 30.0 / (1.0 + gap);
        } else {
            // next item cannot fit here: slight penalty for stranding this bin's residual
            score += 8.0 * (pr / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Mild dispersion penalty: prefer bins where alternatives exist but fit is good
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let mean_pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Base penalty for spawning a bin
        let mut new_bin_penalty = 55.0;
        // If existing residuals are large (mean_residual high), opening new bin is more wasteful
        new_bin_penalty += 30.0 * mean_pressure;
        // Late in the stream, prefer consolidating into open bins
        new_bin_penalty += 20.0 * progress;
        // If many bins could fit, opening a new one is rarely useful
        new_bin_penalty += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
        // Large items early on justify fresh bins
        new_bin_penalty -= 25.0 * fill_ratio * (1.0 - progress);
        // If next item is huge, a fresh bin pairs well with it
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference for the fullest bins among equals (tie-break toward tight packing)
    score += 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Slight noise-free regularization with open bin count: discourage bin sprawl
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on wasted space, sharpened by stream progress
    let mut score = pr + 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Smooth coupling: waste is worse when residuals across bins are already small
    let tight = (mean_residual / cap).clamp(0.0, 1.0);
    score += 30.0 * pr_norm * (1.0 - tight) * (1.0 - tight);

    // Perfect fit reward (smooth, continuous)
    score -= 25.0 * (-pr / 8.0).exp();

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = if pr >= n { 1.0 } else { 0.0 };
        let gap = (pr - n).abs();
        score += 12.0 * (1.0 - fits_next) * (pr_norm);
        score -= 10.0 * fits_next * (-gap / 15.0).exp();
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and when many bins are already open, but relax if the item is large.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        let item_frac = item_size as f64 / cap;
        score += 15.0 + 25.0 * progress + 3.0 * (open_bins_count as f64).sqrt()
                 - 20.0 * item_frac * item_frac;
    }

    // Mild preference for bins with lower residual among equally tight fits
    score += 0.05 * (bin_residual as f64 - pr) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod-10 buckets) ---
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are "harmonically useful" (multiples of 10/20/25/50) are fine;
    // odd primes / tiny slivers are dead space.
    let dead = match pr {
        0 => 0.0,
        1..=9 => 6.0,                       // tiny sliver: unusable
        10 | 20 | 25 | 40 | 50 => -4.0,     // highly reusable class
        30 | 60 | 70 | 75 | 80 => -2.0,     // reusable
        _ => 1.5,                            // awkward residue (e.g. 11..19 non-round)
    };
    score += dead;

    // Integer-division threshold: post_residual divisible by next item => great pair
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            if pr % n == 0 {
                score -= 5.0; // next item fills this bin exactly later
            } else {
                // penalize leaving a gap the next item cannot harmonize with
                let gap = pr - (pr / n) * n;
                score += gap as f64 * 0.3;
            }
            // If next item only fits here, strong last-chance coupling
            if fitting_bins_count == 1 && n <= pr {
                score -= 8.0;
            }
        } else {
            // next item too big for this bin's post residual: mild penalty
            score += 2.0;
        }
    } else {
        // last item in stream: prefer tightest fit strongly
        score -= 3.0;
    }

    // --- Capacity fraction classes ---
    let frac = pr as f64 / bin_capacity as f64;
    if frac < 0.10 {
        score += 4.0; // nearly full bin: good, but tiny leftover is dead
    } else if frac < 0.25 {
        score -= 1.0;
    } else if frac > 0.75 {
        score += 1.0; // still mostly empty: wasteful placement
    }

    // Last-chance bin bonus (only fitting bin before opening a new one)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 12.0 - crowded * 2.0;
        if step_index + 1 >= total_items {
            score += 20.0; // never open a bin for the final item
        }
    }

    // Progress-based tie-break: late in the stream, tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Penalize gaps that cannot hold the lookahead item (dead space for next item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward bins that can also fit the next item (flexibility).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless it reduces waste.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than average (fill fuller bins first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference to keep large residuals for large future items.
    if bin_residual > 50 {
        score += 5.0;
    }

    // New-bin candidate: penalize moderately so it's only chosen when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: post_residual slightly above next item size (item + next fits well).
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward small slack quadratically, but only if next item could fit.
        if slack <= 20.0 {
            score -= 40.0 - slack * slack * 0.1;
        }
    }

    // Penalize dead space: post_residual too small for next item (likely wasted).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Penalize placing into a bin with residual far below mean (already tight bin).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.05;

    // Last-chance bonus: only this bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only prefer it when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && item_size >= 70 {
            score += 5.0; // large item: fresh bin gives future flexibility
        }
    }

    // Slight preference to fill bins tighter as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // Exact-ish fit: strongly favor near-zero post residual
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Dead-space penalty: post residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits the post residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + 0.3 * next_item_size as f64;
        } else {
            // wasted chain opportunity
            score += 5.0;
        }
        // pair fill: item + next exactly fill the bin
        if item_size + next_item_size == bin_residual {
            score -= 60.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 30.0 * progress;
        // But if item is huge and no open bin fits well, new bin is fine
        if item_size >= 70 && fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If many open bins with large mean residual, discourage new bin
        score += 0.2 * mean_residual;
    }

    // Prefer filling bins with larger residuals when many bins are open
    if open_bins_count > 3 {
        score += 0.15 * (open_bins_count as f64);
        score -= 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Time-horizon modulation: early on, be greedy (minimize post residual);
    // later, preserve flexibility slightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits, non-linearly
    let mut score = 2.0 * x * x - 1.2 * x + 0.5 * pr;

    // Polynomial coupling of post-residual with stream progress:
    // early on, tolerate loose fits; later, demand tight packing.
    let coupling = x.powf(2.0 + 2.0 * progress) * (1.0 + 3.0 * progress);
    score += 4.0 * coupling;

    // Penalize dead space relative to mean residual (smooth interaction)
    score += 0.3 * (pr - mean_residual) * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic gap)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 0.4 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Mild penalty for opening new bins when many bins are open late in stream
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space classes: residual that no plausible item (1..=100) can use well.
    let dead_threshold = 9u32; // smallest item size
    if post_residual < dead_threshold {
        score += 250.0; // unusable sliver -> strong penalty
    }

    // Harmonic class of post_residual: modulo-10 buckets.
    let r_mod = post_residual % 10;
    let r_div = post_residual / 10; // decade class 0..=9

    // Decade-based desirability: mid-range residuals (30..=70) are flexible.
    let decade_bonus: f64 = match r_div {
        0 => -40.0,                    // 1..9: nearly full, good if usable
        1 => -10.0,                    // 10..19
        2 => -35.0,                    // 20..29: fits many small items
        3 => -50.0,                    // 30..39: sweet spot
        4 => -45.0,                    // 40..49
        5 => -35.0,                    // 50..59
        6 => -20.0,                    // 60..69
        7 => 0.0,                      // 70..79
        8 => 15.0,                     // 80..89: mostly empty, weak reason
        _ => 25.0,                     // 90..99: nearly untouched bin
    };
    score -= decade_bonus;

    // Modulo-5 residue: residuals divisible by 5 align with common item sizes.
    if r_mod == 0 {
        score -= 12.0;
    } else if r_mod == 5 {
        score -= 6.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 300.0; // next item exactly fills this bin
            } else if slack < dead_threshold {
                score -= 150.0; // next item leaves only a sliver
            } else {
                score -= (slack as f64).ln() * 10.0; // gentle reward for usability
            }
        } else {
            // Next item cannot fit here; if this bin is the only fitting bin,
            // placing current item here is a last chance -> reward.
            if fitting_bins_count == 1 {
                score -= 200.0;
            } else {
                score += 20.0; // mild penalty: bin closes off lookahead
            }
        }
    } else if next_item_size == 0 {
        // Last item: prefer tightest possible fit overall.
        score -= 100.0;
    }

    // Last-chance bonus generally: sole fitting bin avoids opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an untouched bin should only win when no
    // open bin offers a decent fit. Penalize it progressively as the stream
    // fills and as open-bin residuals remain usable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = (open_bins_count as f64).sqrt() * 15.0;
        score += 120.0 + open_penalty + progress * 60.0;
        // If next item is large and current bin is the only fitting one,
        // still discourage hoarding a fresh bin.
        if next_item_size > 50 {
            score += 30.0;
        }
    }

    // Mean-residual coupling: if this bin's post-fit residual sits far below
    // the mean, we are consolidating space efficiently.
    let mean_post = mean_residual - item_size as f64;
    if (post_residual as f64) < mean_post {
        score -= (mean_post - post_residual as f64).min(50.0) * 0.8;
    } else {
        score += ((post_residual as f64) - mean_post).min(50.0) * 0.4;
    }

    // Prefer bins whose residual is closest (in ratio) to the item: best-fit core.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 60.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual >= 10 {
        // Larger usable residual is mildly preferred over mid-range waste.
        score -= 0.15 * post_residual as f64;
    }

    // Reward tight fits relative to bin load.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when a good
    // fit exists, but encourage using existing bins over opening new ones.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item cannot use this gap; penalize leaving moderate gaps.
            if post_residual > 0 && post_residual < next_item_size {
                score += 8.0;
            }
        }
    }

    // Mean-residual coupling: penalize bins far below mean residual (they
    // hoard space), mildly reward bins near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight stream-progression bias: later in the stream, prefer reusing
    // existing bins more aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // offer terrible fits (small dead space) — otherwise penalize opening.
    if bin_residual == bin_capacity {
        let open_bad = fitting_bins_count == 0
            || (fitting_bins_count == 1 && bin_residual < bin_capacity && false);
        if open_bad {
            score -= 30.0;
        } else {
            score += 20.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        // Perfect chain: next item exactly fills post_residual
        if (post_residual as u32) == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits inside post_residual: reward proportional to tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // Next item won't fit in this bin's remainder: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * (gap / 100.0);
        }
        // Penalize remainder that is small but useless relative to next item
        if post > 0.0 && nxt > post {
            score += 8.0 * (post / nxt);
        }
    } else {
        // Last item: prefer minimal final waste
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (bin_capacity - item_size) as f64;
        score = poor_fit + 10.0 * progress;
        if fitting_bins_count > 1 {
            score += 25.0; // discourage wasting a fresh bin when alternatives exist
        }
    }

    // Slight preference for keeping many open bins consolidated
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item cannot fit here; slight penalty for wasting space
            score += 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_frac * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate: penalize mildly, but allow it when mean residual is low
    // (nothing useful open) or item is huge relative to typical residual.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        let mut new_penalty = 15.0;
        if mean_gap < 0.0 {
            new_penalty -= (mean_gap.abs()).min(20.0);
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            new_penalty -= 5.0; // opening fresh bin helps the next big item
        }
        // Later in the stream, opening bins is cheaper than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_penalty -= 10.0 * progress;
        score += new_penalty;
    }

    // Mild time-varying exploration: early stream favors tight fits more,
    // late stream favors consolidation of open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * tightness;
    score -= progress * (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Prefer bins whose residual deviates favorably from the mean (above-mean
    // residual bins are less precious; below-mean residual bins should be kept).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual scaled by a polynomial in progress
    let pr = post_residual as f64;
    let poly = 1.0 + 0.6 * progress - 0.9 * progress * progress + 0.5 * progress * progress * progress;
    score += pr * poly * 0.5;

    // Penalize large dead space non-linearly (quadratic waste)
    score += (pr * pr) / (bin_capacity as f64 * bin_capacity as f64) * 30.0;

    // Reward tight fits: small post_residual relative to item size
    let fit_ratio = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= fit_ratio * 12.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).ln_1p();
    }

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Mean residual context: penalize bins far from the mean (smooth coupling)
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / (mean_residual + 10.0);

    // New-bin candidate handling: prefer existing bins early, allow new bins for big items
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        score += 8.0 - 10.0 * big * big - 6.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;

    // Perfect fit: strongly reward closing a bin completely.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: bins in the lowest decade class are
    // nearly closed, reward them; dead space in mid classes is penalized.
    let class = post_residual / 10;
    match class {
        0 => score -= 10.0,                       // residual <= 10: almost closed
        1 => score -= 4.0,                        // residual <= 20
        2 | 3 => score += 3.0,                    // awkward mid-range dead space
        _ => {}
    }

    // If the lookahead item cannot fit the leftover, this leftover is likely
    // permanent dead space -> penalize proportionally to how far off it is.
    if post_residual > 0 && next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > post_residual as f64 {
            score += 6.0 + 0.15 * (nx - post_residual as f64);
        } else if nx == post_residual {
            score -= 20.0; // next item closes this bin exactly
        } else {
            score -= 2.0; // leftover still reusable
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it
    // avoids opening a new bin -> strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Brand-new empty bin candidate: normally discouraged, but more
    // acceptable early in the stream or when no open bin fits well
    // (fitting_bins_count small relative to open bins).
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * t;
        if open_bins_count > 0 {
            let fit_ratio = fitting_bins_count as f64 / open_bins_count as f64;
            if fit_ratio < 0.34 {
                score -= 6.0 * (1.0 - fit_ratio);
            }
        }
        // A fresh bin is attractive if mean residual of open bins is tiny
        // (they are all nearly closed).
        if mean_residual < 0.15 * cap {
            score -= 10.0;
        }
    }

    // Mild global pressure: keep residual compactness relative to mean.
    score += 0.05 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward tight fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalty for opening a new bin when fitting bins exist.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 55.0;
    }

    // Open-bin pressure: fewer bins favored.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual deviates from mean (diversity of gaps).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Lookahead: if next item fits post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits into the post residual: reward tightness of that fit
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.8;
    } else if next_item_size > 0 {
        // Next item will NOT fit here: penalize proportionally to overshoot
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.5;
    }

    // Prefer bins whose residual is below mean (already partially filled)
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.3;
    } else {
        score += (resid - mean_residual) * 0.3;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (< 10 units)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mild preference for using existing bins over opening a new one as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual, but reward exact-ish fits strongly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Reward leaving residual that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // lookahead item won't fit here; mild penalty proportional to waste
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins, penalize new-bin tendency.
    let open_f = open_bins_count as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate (empty bin): penalize unless residual state is fragmented or item is huge.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        let pressure = (open_f / (open_f + 5.0)) * (0.5 + 0.5 * progress);
        score += 30.0 * pressure - 20.0 * fragmentation;
        if item_size > bin_capacity / 2 {
            score -= 10.0; // big items fine in fresh bins
        }
    }

    // Prefer bins whose residual deviates favorably from mean (below-mean residual = fuller bin).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: push toward using fullest bins as stream ends.
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small bonus for using bins that would otherwise strand medium residual.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty on waste.
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, waste is more costly; early, be more forgiving.
    let coupling = pr_norm * (1.0 - pr_norm) * (0.5 - progress).abs();
    score += 30.0 * coupling * (1.0 - progress);

    // Penalize post-residual that is too small to plausibly fit a future item,
    // with a smooth (cubic) falloff rather than a hard threshold.
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - pr).max(0.0) / cap;
        score += 25.0 * gap * gap * gap * cap;
        // Reward leaving room for the lookahead item.
        let room = (pr - next).max(0.0) / cap;
        score -= 10.0 * room * (1.0 - room);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (smooth penalty scaling with post-residual).
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - pr_norm) * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: penalize slightly so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    // Mild preference for tighter bins among many options.
    score -= 5.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let c = bin_capacity as f64;
    let quarter = (bin_capacity / 4) as u32;
    let half = (bin_capacity / 2) as u32;
    let eighth = (bin_capacity / 8) as u32;

    // Perfect fit: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space penalty grows super-linearly for tiny unusable leftovers.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 30.0;
        }
        // Harmonic classes: leftover in (0, C/8] is near-dead; (C/8, C/4] moderate;
        // (C/4, C/2] good; > C/2 wasteful but re-usable.
        if post_residual <= eighth {
            score += 40.0;
        } else if post_residual <= quarter {
            score += 10.0;
        } else if post_residual <= half {
            score -= 15.0;
        } else {
            score += 5.0;
        }
        // Modulo arithmetic: leftover that is a divisor-friendly residue of capacity
        // (e.g. multiples of 10 or 25) pairs well with common item sizes.
        let r = post_residual;
        if r % 10 == 0 { score -= 8.0; }
        if r % 25 == 0 { score -= 6.0; }
        if r % 50 == 0 { score -= 5.0; }
        // Odd residues that can't hold the smallest item class are penalized.
        if r % 2 == 1 && r < 20 { score += 12.0; }
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= quarter { score -= 30.0; }
            else { score -= 8.0; }
        } else {
            // Next item cannot follow into this bin: penalize if it forces a new bin.
            score += 10.0;
            if next_item_size > bin_residual {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Tightness reward: filling a bin more completely.
    let fill = 1.0 - (post_residual as f64) / c;
    score -= 20.0 * fill * fill;

    // Early in the stream, allow opening fresh bins for big items to build structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive for large items or when residuals are fragmented.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0;
        }
        score += 10.0 * progress; // later in stream, prefer reusing bins
    }

    // Mean-residual coupling: prefer bins near the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer bins with small residual relative to item size (best-fit flavor).
    if bin_residual >= item_size {
        score += 0.05 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;

    // --- Perfect fit: strongest possible reward ---
    if post_residual == 0 {
        score -= 1000.0;
    }

    // --- Strict dead-space avoidance ---
    // Residuals in (0, 10) are nearly unusable (min item size is 1, but the
    // practical chance of filling a tiny gap is low). Penalize quadratically
    // so the smaller the sliver, the harsher the penalty.
    if pr > 0.0 && pr < 10.0 {
        let gap = 10.0 - pr;
        score += 2.0 * gap * gap;
    }

    // --- Last-chance bin: if this is the only open bin that fits the item,
    // placing here avoids opening a new bin. Strong reward. ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // --- New-bin candidate penalty, coupled with open_bins_count pressure ---
    // Opening a new bin while other bins are open wastes potential; the more
    // bins already open, the stronger we push toward consolidating.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 50.0 + 5.0 * open_bins_count as f64 + 30.0 * progress;
    }

    // --- Lookahead (k=2): keep the bin useful for the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            // The leftover gap can still host the next item: reward.
            score -= 30.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // The gap likely becomes dead space after this placement: penalize.
            score += 15.0;
        }
    }

    // --- Mild consolidation tilt: prefer bins whose post-fit residual sits
    // below the current mean residual (tighter than average packing). ---
    score += 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-exact fits (small post_residual).
    let pr = post_residual as f64;
    if pr <= 10.0 {
        score -= 60.0 * (10.0 - pr) / 10.0;
    }

    // 2-step lookahead: reward if next item fits perfectly into post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves more waste; mild penalty proportional to leftover.
        score += 0.15 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize dead space relative to next size.
        score += 0.05 * (next_item_size as f64).min(pr);
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * item_size as f64;
        // Allow new bin if item is huge (poor fit anywhere else).
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    // Slight preference early in the stream to keep bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // a "useless" threshold should be penalized extra.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score -= 6.0; // near-perfect fill
    } else if post_residual == 0 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.35;
    } else if next_item_size > 0 && post_residual > 0 {
        // post-residual too small for next item: penalize wasted space
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Penalize the empty-bin candidate
    // mildly so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 0.4;
    }

    // Global state coupling: when mean residual is high, prefer bins with
    // large residuals to consolidate space.
    if bin_residual as f64 > mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    // Time horizon: later in the stream, be greedier (minimize waste now);
    // earlier, keep options open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;
    score += (post_residual as f64) * progress * 0.1;

    // Slight penalty for very small leftover fragments relative to capacity.
    if post_residual > 0 && post_residual < item_size {
        score += (post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: reward tight fits via non-linear decay of post_residual
    let mut score = post_norm * post_norm * (2.0 - post_norm);

    // Smooth polynomial coupling with stream progress:
    // early on, prefer larger post_residual (keep bins flexible);
    // later, penalize any post_residual strongly (compact now).
    let progress_coupling = post_norm * (1.0 - progress) - post_norm * post_norm * progress;
    score += 0.35 * progress_coupling;

    // Dead-space penalty: residuals too small to fit typical future items
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // New-bin candidate: penalize mildly early, more later unless current bin is a bad fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let bad_fit = (bin_residual as f64 - item_size as f64) / cap; // large => item is small relative to bin
        score += 0.8 - 0.6 * progress - 0.4 * bad_fit;
        // open new bin if lookahead item would fit nicely in fresh bin
        if next_item_size > 0 {
            let look_fit = (next_item_size as f64 / cap) * (1.0 - progress);
            score -= 0.3 * look_fit;
        }
    }

    // Prefer filling bins with above-average residual (use "fat" bins first)
    let res_norm = bin_residual as f64 / cap;
    score += 0.2 * (res_norm - mean_residual / cap).max(-1.0).min(1.0) * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item fits into the post_residual smoothly
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let fits = (post_norm - next_norm) / cap;
        if post_residual >= next_item_size {
            score -= 0.25 * (1.0 - (post_norm - next_norm)) * (1.0 - progress);
        } else {
            score += 0.1 * next_norm * progress;
        }
        let _ = fits;
    }

    // Mild pressure to close out bins as stream progresses
    score += 0.05 * progress * (open_bins_count as f64 / (total_items.max(1) as f64).sqrt());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in low modulo classes
    // of 10 are "dead space" wells; reward exact zero and small classes.
    let m = post_residual % 10;
    score += match m {
        0 => -12.0,                      // perfect harmonic closure
        1 | 2 | 3 => 14.0,               // nearly unusable sliver
        4 | 5 | 6 => 6.0,
        _ => 0.0,
    };

    // Integer-division threshold: post_residual below half of smallest
    // plausible item is likely dead unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead harmonic coupling: can next_item_size land exactly in the
    // post-residual's class? Reward exact fit, penalize near-miss.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score += (gap % 10) as f64 * 0.8;
            score -= 4.0; // slight bonus for any feasible follow-up
        } else {
            score += 5.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave
    // awkward residue and the next item is large.
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 25;
        if awkward && next_item_size >= 60 {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Late in the stream, consolidate harder (avoid opening bins late).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (open_bins_count as f64).sqrt();

    // Mild preference for bins below mean residual (balance residuals).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: gaps below the smallest possible item
    // are worthless, so amplify the penalty for very small post_residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize placements that leave
    // large residuals when the bin count is already high.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * (post_residual as f64 / 10.0);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover; penalize dead space more.
        score += 10.0;
    }

    // Compare against mean residual: bins with residuals far below mean are
    // "tight" bins — placing there keeps tight bins usable.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: discourage opening a new bin early in the stream,
    // but allow it late when open bins are numerous and fragmented.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward post_residual close to next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6;

        // Exact match for the next item is excellent
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // If next item can't fit anywhere after this placement, penalize
        if post_residual < next_item_size {
            score += 30.0;
        }
    }

    // Penalize dead space far from mean residual (fragmentation)
    let frag = (post_residual as f64 - mean_residual).abs();
    score += frag * 0.15;

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 120.0;
        // If few fitting bins exist, allow opening a new bin more readily
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
        // Later in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Prefer tighter bins generally
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64).powi(2) / 100.0;

    // Lookahead: penalize leaving a residual that cannot host the next item
    // (creates dead space), but reward residuals that fit it well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slight reward for enabling the next placement.
            score -= 6.0;
            // Extra reward if next item fits almost exactly.
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - (gap as f64) / (bin_capacity as f64)).max(0.0) * 0.3;
        } else {
            // Dead space relative to the lookahead item.
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer using bins that are already relatively full (low residual) to
    // consolidate waste; compare against mean residual of open bins.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins when many bins are already open and
    // mean residual is high (fragmentation signal).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, adjusted by fragmentation state.
        score += 12.0 + 10.0 * (1.0 - progress) - 0.1 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 0.2 * (mean_residual - item_size as f64);
        }
    }

    // Time horizon: late in the stream, be more conservative about waste
    // (fewer chances to recover dead space).
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let nx = next_item_size as f64 / cap;

    // Smooth non-linear base: reward tight fits via a normalized cubic in post_residual.
    let prn = pr / cap;
    let mut score = prn * (1.0 + 0.9 * prn - 1.4 * prn * prn);

    // Polynomial coupling of post_residual with stream progress: late in the stream,
    // tight fits matter more (dead space is costlier).
    score += 0.35 * prn * prn * progress;

    // Reward bins that can also host the lookahead item (smooth quadratic gate).
    let nx_fits = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
    score -= 0.5 * nx_fits * nx * (1.0 + progress);

    // Last-chance bonus: strongly favor the single fitting bin to avoid opening a bin.
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 0.8 * last_chance * fit_frac;

    // Penalize bins whose residual deviates from the mean (non-linear spread term).
    let dev = (pr - mean_residual) / cap;
    score += 0.15 * dev * dev * (1.0 + 2.0 * progress);

    // New-bin candidate: keep it competitive only when no open bin is a good fit.
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += is_new * (0.6 + 0.5 * progress * fit_frac) * (1.0 - 0.3 * (fitting_bins_count as f64).recip());

    // Mild preference for bins that are more filled (less post-residual) overall.
    score += 0.1 * (prn - fit_frac) * (prn - fit_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity fractions (1/2, 1/3, 1/4 of C) — residues that future items
    // (sizes 1..100) can still fill are valuable; tiny slivers are dead space.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalty for dead space: residuals below C/4 are hard to reuse.
    if post_residual < bin_capacity / 4 {
        score += 12.0 + (bin_capacity / 4 - post_residual) as f64;
    } else {
        // Reward residuals that sit in "harmonic" classes divisible by
        // common item sizes (integer division thresholds).
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 10 == 0 { score -= 2.0; }
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible; reward exact class matches.
            score -= 8.0;
            if post_residual == next_item_size { score -= 20.0; }
            if post_residual % next_item_size == 0 { score -= 5.0; }
        } else {
            // Next item won't fit here; penalize more if this residual
            // is small enough to become a sliver.
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    } else {
        // Last item: any residual is pure waste.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large relative to capacity (big items deserve fresh space) or the
    // stream is early and we have room to build good classes.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > 0.6 * c;
        if !large_item && fitting_bins_count > 0 {
            score += 30.0 + 20.0 * (1.0 - progress);
        }
        // Slight early-stream bonus for starting bins when item is large.
        if large_item && progress < 0.5 {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate: prefer bins whose residual is below
    // the mean (tighter bins first), scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) < mean_residual {
        score -= 2.0 * progress;
    } else {
        score += 1.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

