    let mut score = pr + 0.9 * pr * pr / cap;

    // Stream-progress coupling: later in the stream, dead space matters more
    // (less room to amortize waste), so amplify the quadratic term smoothly.
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Reward bins whose residual closely matches the item (smooth Gaussian-like term).
    let fit_quality = (bin_residual as f64 - item) / cap;
    score -= 8.0 * (-fit_quality * fit_quality * 40.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
