        score -= 6.0 + 0.05 * item;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it;
    // smooth coupling between post_residual and next item size.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= 5.0 * (-gap * gap / (cap * cap * 0.02)).exp();
    }

    // Slight penalty for spreading across too many open bins relative to mean residual.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate adjustment: an empty bin is only attractive when no open
    // bin fits well; penalize it mildly so existing bins win on good fits.
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - progress);
        if item > 50.0 {
            score += 0.03 * item;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions (C=100)
    let q = post_residual / 10; // decade class 0..10
    match q {
        0 => score -= 60.0,          // tiny dead space: excellent
        1 => score -= 25.0,          // very good
        2 => score -= 5.0,           // decent
        3 | 4 => score += 10.0,      // mediocre
        5 => score += 25.0,          // half-empty: poor
        _ => score += 40.0,          // wasteful
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainable: reward proportionally to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.4;
            if slack == 0.0 {
                score -= 50.0; // perfect chain
            }
        } else {
            // next item cannot use the leftover: penalize large leftovers
            score += (post_residual as f64 - (bin_capacity - next_item_size.min(&bin_capacity)) as f64).max(0.0) * 0.3;
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit (post_residual small). An empty bin has
    // post_residual == capacity == 100, which lands in the wasteful class,
    // so add pressure proportional to how well existing bins could do.
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // big item now, next is bigger: new bin may pay off
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0; // slightly prefer consolidation late in stream
    }

    // Prefer spreading load when many bins are open and mean residual is high
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 100.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover gap: penalize dead space creation.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: add open-bin pressure so it's chosen only
        // when open bins are few or fits are poor.
        score += (open_bins_count as f64) * 3.0;
        // Slight bonus early in the stream when few bins exist.
        if open_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= (open_bins_count as f64) * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (tighter bins get filled first, keeping loose bins flexible).
    score += ((bin_residual as f64) - mean_residual) * 0.2;

    // Late-stream urgency: as the stream progresses, avoid creating dead space even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize leftover dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.1 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize leaving unusable slivers (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Early in stream: slightly prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    // New-bin candidate should only win when open bins would be badly fragmented
    if bin_residual == bin_capacity {
        score += 35.0 + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Lookahead coupling: penalize leaving residual that next item cannot use
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual is usable by next item -> mild reward scaled by how snug
            let snug = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 * (1.0 - snug);
        } else {
            // dead space relative to lookahead
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Many fitting bins: mild penalty to prefer best fit discrimination
    if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state: if mean residual is high, prefer filling existing bins well
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 10.0 * dev; // favor bins with below-average residual (fuller bins)
    }

    // Time horizon: late in stream, avoid opening new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when alternatives exist
        let mut new_bin_penalty = 30.0 + 60.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 40.0;
        }
        // early stream: new bins are cheap and give flexibility
        new_bin_penalty -= 35.0 * (1.0 - progress);
        score += new_bin_penalty.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, with stream-progress-dependent curvature
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear coupling: quadratic dead-space penalty grows late in the stream
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Interaction with mean residual: prefer bins deviating smoothly from mean
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    // Last-chance bonus: only fitting bin -> smooth sigmoid-like reward
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 12.0 * last_chance * (1.0 - norm_pr);

    // Lookahead: reward if next item fits smoothly into post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = if nx <= pr { 1.0 - (nx / pr.max(1.0)) } else { -1.0 };
        score -= 8.0 * fits * (0.3 + 0.7 * progress);
    }

    // Mild penalty for spreading across many open bins, eased by polynomial of open count
    let ob = open_bins_count as f64;
    score += 0.5 * (ob * ob) / (ob + 10.0) * (1.0 - progress);

    // New-bin candidate: make it attractive only when residual space is large relative to typical need
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress) * (1.0 - norm_pr);
        score += 10.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 capture "dead space classes"
    let r = post_residual % 10;
    let r_penalty = match r {
        0 => -12.0,           // perfectly reusable chunk
        1 | 2 => 6.0,         // nearly useless sliver
        3 | 4 => 2.0,
        5 => -4.0,            // half-decade residual is attractive
        6 | 7 => 0.0,
        8 | 9 => 3.0,
        _ => 0.0,
    };
    score += r_penalty;

    // Integer-division threshold: post_residual / 10 as coarse fill tier
    let tier = post_residual / 10;
    score += (tier as f64) * 0.8; // prefer lower post_residual (tighter fit)

    // Reward tight fits (small post_residual) super-linearly
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 15 {
        score -= 6.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize leaving a large residual
            score += (post_residual as f64) * 0.15;
        }
    }

    // New-bin candidate handling: neutral-ish baseline, penalize slightly unless
    // open bins are crowded or this is a bad fit situation
    if bin_residual == bin_capacity {
        score += 25.0; // default: prefer existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        // early stream: opening bins is cheaper; late stream: conserve
        score -= 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // if mean residual is large, definitely reuse open bins
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    }

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.05;

    // Capacity-fraction coupling: penalize residual as fraction of capacity
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is too small to hold even the smallest item.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, ideal
    } else if post_residual <= 10 {
        // Small unusable gap: heavy penalty scaled by how dead it is.
        score += (11 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        // Moderately small gap: moderate penalty.
        score += (21 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Penalize wasting a nearly-full bin on a small item.
    if item_size < bin_residual / 4 {
        score += 12.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing bins
    // (penalize the new-bin candidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    if bin_residual == bin_capacity {
        score += 25.0 + pressure * 2.0;
    } else {
        score -= 3.0 + pressure * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins below mean residual (filling fuller bins first),
    // keeping emptier bins flexible for future items.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Lookahead: if the next item can use the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit in the resulting gap, penalize leaving a medium gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual > 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with little slack left.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack / 5.0);
    }
    // Penalize residuals too small for any plausible future item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Tight fit reward relative to capacity.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // New-bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64 > mean_residual.max(0.0) + 20.0;
        score += if poor_fit { 5.0 } else { 45.0 };
    }

    // Mild preference for bins with residuals close to the mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that nothing in the plausible size range can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0; // next item won't fit here
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 10.0 * fit_ratio;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins fit poorly or mean residual is very low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_alternatives = (fitting_bins_count == 0) as i32 as f64
            + (mean_residual < item_size as f64 * 0.5) as i32 as f64;
        let bias = 60.0 - 40.0 * poor_alternatives - 10.0 * progress;
        // New bin should lose to good fits but win over wasteful placements.
        score += bias.max(-30.0);
        // Penalize opening bins when many are already open with slack.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild preference for filling bins below mean residual (balance avoidance
    // of many half-empty bins).
    if (bin_residual as f64) > mean_residual + 5.0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: early on, tolerate slack;
    // late in the stream, aggressively avoid dead space.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * norm_pr * pr;

    // Lookahead coupling: reward residuals that can still fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 3.0 * (1.0 - (slack / cap).min(1.0)) * (1.0 - progress);
        } else {
            score += 2.0 * (nxt - pr) / cap * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize bins far from mean residual (fragmentation signal), smoothed
    let dev = (pr - mean_residual).abs() / cap;
    score += 1.0 * dev * (1.0 + progress);

    // New-bin candidate: neutral-ish, slightly discouraged unless very late
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (harmonic class of post_residual).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 60.0; // tiny dead space is fine
    } else if post_residual < 20 {
        score -= 25.0;
    } else {
        // Dead space penalty grows superlinearly for mid-range leftovers.
        score += (post_residual as f64 - 20.0) * 0.9;
    }

    // Harmonic classes: bins whose residual falls in "useless" zones
    // (residuals that almost no item of size 1..=100 can exploit).
    let useless_zone = post_residual > 0 && post_residual < 10;
    if useless_zone {
        score -= 40.0; // 1..9 residual is nearly dead but harmless
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 30.0 + (10u32.saturating_sub(slack.min(10))) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize mildly unless post_residual tiny.
        if post_residual > 15 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so open bins are preferred unless they waste a lot.
        score += 20.0;
        // If mean residual of open bins is large, opening new bin is wasteful.
        score += mean_residual * 0.5;
        // Late in stream, slightly favor reusing bins.
        score -= progress * 10.0;
        // If many bins already open, discourage opening more.
        score += open_bins_count as f64 * 1.5;
        // If this bin is the only fitting option, new-bin penalty stands.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // Modulo coupling: residuals that are multiples of common item classes
    // (e.g. multiples of 10 or 25) are more exploitable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item (assume ~1..100 range,
    // treat gaps below 10 as pure waste; gaps 10..30 as semi-dead).
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space: unusable for any item.
        score += 80.0;
    } else if post_residual < 30 {
        // Semi-dead: only tiny items can use it.
        score += 25.0;
    } else if post_residual < 55 {
        // Moderately usable gap.
        score += 5.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Mild reward if the next item still fits after this placement.
        score -= 8.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        // Penalize closing the door on the lookahead item.
        score += 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins when open_bins_count is high).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        // Slight reward for using existing bins, stronger when many are open.
        score -= 2.0 + 0.5 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Relative fit quality: reward bins whose residual is close to the item size
    // (tight packing), penalize wasteful placements into very loose bins.
    let waste_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * waste_ratio;

    // Mean-residual coupling: if the average residual across open bins is large,
    // there is slack elsewhere; mildly penalize consuming this bin unless it's a tight fit.
    if mean_residual > 40.0 && post_residual > 30 {
        score += 8.0;
    }

    // Late-stream tightening: as the stream progresses, prioritize perfect fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - waste_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly (perfect chaining).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));

        // Exact match is a jackpot: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // If next item won't fit here after placement, penalize mildly
        // unless the bin becomes perfectly tight (post_residual small).
        if next_item_size > post_residual {
            score += 15.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: minimize waste directly.
        score += 20.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Penalize large dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Slight penalty when many bins are open: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Prefer tighter fits overall (small post_residual relative to item).
    score += 0.2 * (post_residual as f64 / (item_size as f64 + 1.0));

    // Early stream: be less aggressive about dead space; late stream: tighten.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Bonus proportional to how well the next item also fits tightly.
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 8.0 * next_tight;
        } else {
            // Penalize placements that strand the next item.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest fit even more.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global fragmentation pressure: if mean residual is low, conserve space
    // by preferring bins that end with minimal waste.
    let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 15.0 * frag * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be conservative (favor spreading);
    // late in the stream, prioritize closing out bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 12.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * progress * tightness;

    // Many open bins: encourage filling existing ones rather than opening more.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins moderately attractive only when the
    // item is large or the current bin fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 20.0 - 25.0 * (item_size as f64 / bin_capacity as f64) + 15.0 * poor_fit;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), non-linearly
    let mut score = norm_pr * norm_pr * 120.0 + norm_pr * 40.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly.
    let coupling = (0.5 + progress) * norm_pr * norm_pr * 80.0
                 - progress * norm_pr * 15.0;
    score += coupling;

    // Cubic term: heavily penalize mid-range residuals that are hard to fill later
    score += (norm_pr - 0.5) * (norm_pr - 0.5) * (norm_pr - 0.5) * 60.0 * (0.3 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 18.0 * fit_quality * fit_quality;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0 * (1.0 - norm_pr);
        }
    }

    // New-bin candidate handling: empty bin gets a mild bias so it's chosen
    // only when open bins have poor fits (large normalized post_residual there).
    if bin_residual == bin_capacity {
        score += 10.0 + 10.0 * (1.0 - progress);
    }

    // Prefer consolidating into fewer bins when residuals are similar to mean
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity fractions.
    // Residuals in (0, 10] are "dead space" class -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit class: residual exactly 0 or a divisor-class of capacity.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Integer-division thresholds: classify post_residual into quarters of capacity.
    let q = post_residual / 25; // 0..4 harmonic class
    score += q as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 50.0;
        } else if slack < 10 {
            score -= 25.0;
        } else {
            score -= 10.0 - (slack as f64).min(10.0) * 0.5;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize leftover dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate logic: only attractive when item is large and open bins are tight.
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let mut bonus = 0.0;
        if big_item { bonus += 15.0; }
        if tightness < 0.25 { bonus += 10.0; }
        if next_item_size > 0 && next_item_size >= item_size { bonus += 8.0; }
        // Early stream: prefer consolidating into open bins.
        bonus -= (1.0 - progress) * 10.0;
        score += 30.0 - bonus; // baseline penalty for new bins, reduced by bonus
    }

    // Prefer bins with below-mean residual (keep large residual bins flexible).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Modulo-class coupling: reward residuals that are multiples of common item classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: strict dead-space avoidance with a non-linear penalty on unusable gaps.
    // Gaps below the minimum item size (1..=100 interface, but conservatively < 20)
    // are "dead space" — penalize them super-linearly.
    let mut score = post_residual as f64;

    if post_residual < 20 {
        // Unusable small gap: strong penalty, worse the smaller the gap is usable nowhere.
        score += (20 - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect fill: big reward.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Lookahead: if the next item fits the post-residual, reward keeping this bin alive;
    // if the next item is large and post_residual is tiny, this bin is nearly done anyway.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 8.0;
        } else if post_residual < next_item_size {
            // Gap that the next item cannot use: mild extra penalty scaled by gap smallness.
            score += 0.15 * (post_residual as f64).min(15.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new ones); with few open bins, new bins are cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure so it's chosen only
        // when no existing bin offers a good fit.
        score += 40.0 + pressure;
        // Late in the stream, opening new bins is especially wasteful.
        score += 20.0 * progress;
    } else {
        // Existing bin: slight reward proportional to pressure (favor reuse).
        score -= 0.3 * pressure;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already "used up" — finishing it off is good.
    let dev = mean_residual - post_residual as f64;
    score += 0.2 * dev; // below-mean residual (dev>0) lowers score -> favor these bins.

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (low post_residual) via squared dead-space penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: strongly reward when the NEXT item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chain: item then next item fill the bin completely
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it matches leftover
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 1.5;
        } else {
            // next item does NOT fit here: penalize bins whose residual blocks lookahead
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.8;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual above the mean when placing large items
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mean_gap = bin_residual as f64 - mean_residual;
    score -= mean_gap * (0.3 + 0.5 * (1.0 - progress));

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 100.0;
        // open a new bin if current bin leaves awkward dead space for next item
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score -= 90.0;
        }
        // early in stream: opening bins is cheaper; late: prefer consolidation
        score += 80.0 * progress;
    }

    // Mild penalty for very large items creating huge residuals
    score += (item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * (next_item_size as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state coupling: many open bins with large mean residual
    // suggests we should consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln_1p();
    score += 3.0 * consolidation * (1.0 - 0.5 * progress);

    // New-bin candidate logic: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible_waste = if next_item_size > 0 {
            (bin_capacity as f64 - item_size as f64) - (bin_capacity as f64 - next_item_size as f64).min(bin_capacity as f64)
        } else {
            bin_capacity as f64 - item_size as f64
        };
        score += 30.0 - 20.0 * progress;
        if fitting_bins_count > 0 {
            // Deter opening a new bin when alternatives exist, unless
            // alternatives would leave large dead space.
            let alt_waste_estimate = mean_residual - item_size as f64;
            if alt_waste_estimate > 40.0 {
                score -= 15.0;
            }
        }
        let _ = best_possible_waste;
    }

    // Mild time-horizon term: late in the stream, prefer filling bins fully.
    score += 2.0 * progress * (bin_residual as f64 - post_residual as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (low post_residual) strongly.
    // Late: dead space matters less, so relax the penalty smoothly.
    let tightness = post / cap; // 0..1
    let poly = tightness * tightness * (1.0 - progress) + tightness * (1.0 - progress) * (1.0 - progress);
    score += 40.0 * poly;

    // Reward excellent fits (small post residual) more when few bins can fit the item.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - tightness) * (1.0 - progress);
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64).ln() * (1.0 - progress);
    }

    // Lookahead: if next item fits into the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let slack = (post - next) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            // Penalize leaving residual too small for the known next item.
            let miss = (next - post) / cap;
            score += 10.0 * miss * (1.0 - miss);
        }
    }

    // Coupling with mean residual: placing into bins far from mean residual
    // homogenizes bin states; reward balancing slightly via smooth term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    // Penalize opening a brand-new bin when plenty of open bins can fit,
    // with a smoothly decaying pressure over the stream.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let spread = mean_residual / cap;
        score += 25.0 * (1.0 - spread) * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more valuable (wasted capacity is low).
    let post = post_residual;
    let class = post / 10; // integer division: 0..10 harmonic classes
    score += match class {
        0 => -30.0,                    // near-perfect fit
        1 => -20.0,
        2 => -10.0,
        3 => 0.0,
        4 => 5.0,
        5 => 10.0,
        6 => 15.0,
        7 => 20.0,
        8 => 25.0,
        9 => 30.0,
        _ => 35.0,                     // essentially untouched bin
    };

    // Modulo coupling: residues that pair well with common item sizes
    // (multiples of 10 / 5) get a bonus, since next items likely fit.
    if post % 10 == 0 {
        score -= 8.0;
    } else if post % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size <= post {
            score -= (post - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here; penalize creating a dead-end bin.
            score += (next_item_size - post) as f64 * 0.3;
        }
    }

    // Last-chance bin: if only this bin can fit the item, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: residual == capacity. Make it attractive only when
    // current bins are crowded (high mean fill) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fill = (cap - mean_residual) / cap;
        let discount = 10.0 * mean_fill + 15.0 * progress;
        score = score - discount + 20.0; // baseline penalty, offset by discount
        if post % 10 == 0 {
            score -= 3.0; // fresh bin keeps clean harmonic alignment
        }
    }

    // Slight preference to fill bins that are already heavily used relative
    // to the fleet average (consolidation pressure).
    let fill_gap = mean_residual - bin_residual as f64;
    score -= fill_gap * 0.15;

    // Small tie-break noise via deterministic hash of state (no RNG seeds).
    let h = (item_size as u64)
        .wrapping_mul(0x9E3779B97F4A7C15)
        .wrapping_add(bin_residual as u64)
        .wrapping_add((step_index as u64) << 32);
    score + ((h >> 60) as f64) * 0.01
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item (1..100 range, assume min ~10-ish, but be safe with a graded penalty).
    if post_residual > 0 {
        // dead space that is too small for a typical small item gets quadratic penalty
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 60.0 * (10.0 - dead) / 10.0; // nearly-full waste penalty
        } else if dead < 25.0 {
            score += 15.0 * (25.0 - dead) / 25.0; // awkward small gap penalty
        }
        // Perfect fit: zero dead space strongly rewarded
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; if this bin would be left with a tiny gap, penalize
            if post_residual < next_item_size && post_residual > 0 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a fresh bin
        score = (bin_capacity as f64) * 0.5 + 30.0;
        // If existing bins fit well (mean residual small relative to item), make new bin less attractive
        let mean_fit_gap = mean_residual - item_size as f64;
        if mean_fit_gap >= 0.0 && mean_fit_gap < 20.0 {
            score += 40.0;
        }
        // Late in the stream, opening new bins is more costly (fewer future items to fill it)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If only one fitting bin exists, opening a new bin is bad
        if fitting_bins_count <= 1 {
            score += 100.0;
        }
    } else {
        // Mild pressure to prefer bins with smaller residual when many bins are open
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space penalty scaled by gap to next item
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residuals far from mean (fragmentation avoidance)
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Slight bias toward existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0; // next item won't fit here; bin becomes dead-ish
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;

    // Prefer reusing open bins vs new bin, modulated by progress and mean residual.
    let reuse_bonus = 6.0 + 14.0 * progress;
    score -= reuse_bonus * (1.0 - new_bin);
    score += 10.0 * new_bin * (1.0 - 0.5 * progress);

    // If mean residual across bins is high, opening a new bin is less costly.
    if new_bin > 0.5 {
        score -= 4.0 * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * open_bins_count as f64 * new_bin;

    // Slight preference to place into emptier bins when residuals are similar.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (0.8 + 1.6 * p2 + 0.9 * p3);

    let mut score = pr + 12.0 * coupling;

    // Reward tight fits via smooth decay of post_residual
    score -= 18.0 * (-pr / 14.0).exp() * (1.0 + p2);

    // Penalize dead space that can't fit a typical next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (nx - pr).max(0.0);
        score += 0.6 * waste * (0.5 + progress);
        // Reward leaving room exactly for the lookahead item
        score -= 10.0 * (-((pr - nx).abs() / 10.0).powi(2));
    }

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr) * (0.6 + 0.8 * progress);
    }

    // Mild pressure toward consolidation as bins accumulate
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: penalize opening fresh bins, more so later in stream
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes via integer division.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Class bins of size 10: residuals in [1..10] are nearly perfect,
        // larger classes progressively worse.
        let class = post_residual / 10; // 0..10
        score += class as f64 * 2.5;
        // Very small residuals (1..=5) are excellent dead space; reward.
        if post_residual <= 5 {
            score -= 12.0;
        } else if post_residual <= 10 {
            score -= 6.0;
        }
    }

    // Harmonic compatibility: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item still fits: good chaining, reward scaled by how snug.
            let snug = (post_residual - next_item_size) as f64;
            score -= 8.0 - (snug / 20.0).min(6.0);
        } else {
            // Next item won't fit: penalize, worse when post_residual is large
            // enough that it feels wasteful but still unusable.
            score += 6.0 + ((post_residual as f64) / 25.0).min(10.0);
        }
        // Exact harmonic match: post_residual == next_item_size is ideal.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Penalize the fresh bin (residual == capacity)
    // unless the stream is early or open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 20.0;
        // Early stream: opening bins is cheap/necessary.
        penalty *= (1.0 - progress).max(0.1);
        // Many open bins with high mean residual -> fragmentation; opening a
        // fresh bin is less bad, so reduce penalty.
        let frag = mean_residual / bin_capacity as f64;
        penalty *= (1.0 - frag * 0.5).max(0.3);
        // If several bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            penalty += 10.0 * (fitting_bins_count as f64).min(4.0);
        }
        score += penalty;
    }

    // Mild preference for tighter bins overall (best-fit backbone).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Modulo tie-breaker: prefer post_residuals that are harmonically
    // divisible into common item sizes (10-unit grid alignment).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold anything are pure waste.
    let dead_threshold = 10.0; // smallest item class
    if (post_residual as f64) < dead_threshold {
        score -= 25.0; // near-perfect fit, strongly reward
    } else if (post_residual as f64) <= 20.0 {
        // small gap: only useful if next item can use it
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 8.0;
        } else {
            score += 12.0; // likely dead space
        }
    } else {
        // medium/large residual: reward if it matches the lookahead item
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 4.0;
        }
        // penalize residuals in the awkward 21..40 band (hard to fill later)
        if post_residual <= 40 {
            score += 6.0;
        }
    }

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: only one bin can fit the item; use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: prefer keeping the number of active bins low,
    // but only for genuine bins (a new empty bin has residual == capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is penalized more when many bins are already open.
        score += 10.0 + 1.5 * open_bins_count as f64;
        // Slightly more willing to open early in the stream (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    } else {
        score += 0.3 * open_bins_count as f64;
    }

    // Prefer bins with residual below the mean (consolidating fuller bins).
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), scaled
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain match: strong reward
            if gap == 0.0 {
                score -= 40.0;
            } else {
                score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item won't fit in this bin after placement: penalize wasted chain opportunity
            score += 8.0;
        }
    } else {
        // Last item: just minimize post_residual
        score -= 5.0;
    }

    // Penalize bins whose residual is far below mean (already tight bins should be used first)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin attractive only when no good fit exists
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a perfect fit but below bad fits
        score = bin_capacity as f64 * 0.9 + 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Empty bin can host the chain too
            let gap = (post_residual - next_item_size) as f64;
            if gap == 0.0 { score -= 45.0; }
        }
        // If the only alternative is a poor fit, allow new bin
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in stream, prefer consolidating into open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    // Mild penalty for creating tiny dead space (< 10 unusable for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward the best available fit: minimal post-residual.
    // Reward tight fits more aggressively as the stream progresses.
    score -= (bin_capacity as f64 - post_residual as f64) * (0.15 + 0.35 * t);

    // Last-chance bin: placing here avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 + 40.0 * t;
    }

    // Lookahead: if the next item fits into the post-residual, this placement
    // preserves a useful bin; reward it proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - waste / bin_capacity as f64);
    }
    // If next item almost fits (within 10), keep the bin attractive anyway.
    else if next_item_size > 0 && post_residual > 0 && next_item_size - post_residual.min(next_item_size) <= 10 && post_residual < next_item_size {
        score += 5.0;
    }

    // Penalize creating small, hard-to-use dead space (< 10) in an existing bin.
    if post_residual > 0 && post_residual < 10 && bin_residual < bin_capacity {
        score += 30.0 * (1.0 - t);
    }

    // New-bin candidate: default mild penalty so we prefer existing bins...
    if bin_residual == bin_capacity {
        score += 45.0;
        // ...but open a new bin when the item is large relative to residuals
        // or the current bin leaves a very wasteful remainder.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio > 0.25 {
            score -= 70.0 * waste_ratio;
        }
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 50.0;
        }
        // Late in the stream, consolidate: prefer existing bins even more.
        if t > 0.8 {
            score += 25.0 * (t - 0.8) * 5.0;
        }
        // Many open bins with slack: discourage opening yet another.
        if open_bins_count > 3 && mean_residual > item_size as f64 * 1.5 {
            score += 30.0;
        }
    }

    // Slight preference for bins whose residual is close to the mean
    // (balanced packing keeps flexibility).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space, with non-linear (quadratic/cubic) shaping
    let mut score = x * (1.0 + 0.8 * x + 0.6 * x * x) * cap;

    // Non-linear coupling of post_residual with stream progress:
    // early on, waste matters less; late, tight fits are crucial.
    let prog_coupling = pr * pr / cap * (0.5 + 1.5 * progress * progress);
    score += prog_coupling;

    // Smooth interaction: item size relative to capacity vs progress
    let it = item_size as f64 / cap;
    score -= 30.0 * it * (1.0 - it) * (0.3 + 0.7 * progress);

    // Penalize opening new bins when fitting bins exist (smooth logistic-like)
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        let pressure = 1.0 / (1.0 + (fitting_bins_count as f64));
        score += (5.0 + 25.0 * progress) * pressure * (1.0 + 0.2 * openness);
    } else {
        // Reward scarce fitting capacity (last chance bin)
        if fitting_bins_count == 1 {
            score -= 12.0 * (1.0 - progress);
        }
    }

    // Lookahead: smooth bonus if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr - nx).max(0.0);
        let fit_quality = 1.0 - (fits / cap).abs();
        score -= 8.0 * fit_quality * fit_quality * (0.5 + 0.5 * progress);
    }

    // Mild attraction to bins near mean residual state (smooth)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: group post_residual into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as u32; // 0..7 harmonic classes of residual

    // Reward tight fits (small class), with non-linear emphasis
    let class_penalty = match class {
        0 => -30.0,
        1 => -18.0,
        2 => -8.0,
        3 => 0.0,
        4 => 6.0,
        5 => 12.0,
        6 => 20.0,
        _ => 30.0,
    };
    score += class_penalty;

    // Perfect fit: zero post residual is ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo logic on post_residual: leftovers that pair with common small items
    let mod16 = post_residual % 16;
    if mod16 == 0 && post_residual > 0 {
        score -= 6.0; // clean multiple of 16 likely reusable
    } else if mod16 == 1 || mod16 == 2 {
        score += 8.0; // near-dead sliver
    }

    // Lookahead: if next item fits the post residual exactly, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // favor residual classes that leave another harmonic-compatible gap
            let next_gap = post_residual - next_item_size;
            if next_gap % 8 == 0 {
                score -= 10.0;
            }
            score += (next_gap as f64) * 0.05;
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin leaves bad dead space
    if bin_residual == bin_capacity {
        // opening fresh is penalized mildly; grows with stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 + 20.0 + 15.0 * progress;
        if post_residual == 0 { score += 40.0; } // undo perfect-fit bonus for empty bin
        if item_size >= 60 { score -= 25.0; } // big items may deserve a fresh bin
    }

    // Prefer filling bins with large residuals when many bins are open
    score += mean_residual * 0.08 - (open_bins_count as f64) * 0.5;

    // Integer-division threshold on post_residual
    let half = bin_capacity / 2;
    if post_residual > 0 && post_residual <= half / 4 {
        score += 15.0; // tiny unusable gap penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: gaps too small to hold even the smallest item (1)
    // are pure waste; gaps below the typical item size are risky.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual < 20 {
        score += 40.0;
    }

    // Reward leaving a gap that can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing bins
    // (penalize the new-bin candidate more as open_bins_count grows).
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: base penalty so it only wins when fits are awful.
    if bin_residual == bin_capacity {
        score += 250.0 + mean_residual * 0.5;
    }

    // Late in the stream, consolidation matters more: tighten dead-space tolerance.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Prefer bins whose residual is close to the mean (balance residuals),
    // keeping a spread of usable gaps across bins.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space for next item: penalize small post_residual that can't fit next item
            score += 25.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Compare post_residual against mean residual: avoid making bin far below average
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins exist that fit reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 120.0 + 0.3 * mean_residual;
    }

    // Late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.2 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: post residual too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward if next item can fit into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
        // Reward exact chain: item + next item nearly fills the bin
        let chain_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if chain_fill > 0.95 && bin_residual >= item_size + next_item_size {
            score -= 20.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > item_size as f64 * 1.5 {
        score -= 4.0;
    }
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.6
            || (next_item_size > 0 && post_residual < next_item_size);
        if poor_fit {
            score -= 5.0;
        } else {
            score += 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress) - 12.0 * pr_norm * (1.0 - pr_norm) * (1.0 + progress);

    // Penalize large dead space quadratically, amplified late in stream
    score += (pr_norm * pr_norm) * cap * (0.3 + 0.7 * progress * progress);

    // Reward tight fits (small post residual) with cubic decay
    score -= (1.0 - pr_norm).powi(3) * 8.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (nxt / cap);
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty when many bins open and this bin deviates from mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * (2.0 + 0.1 * open_bins_count as f64);

    // New-bin candidate handling: keep it slightly less attractive unless residuals are poor
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * mean_residual / cap * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual), with harmonic scaling.
    let fit_ratio = post_residual as f64 / cap; // 0.0 = perfect fit
    score = post_residual as f64 * (1.0 + 2.0 * fit_ratio);

    // Harmonic class of post_residual: dead space buckets.
    // Residuals <= 10 are "sealed" (unusable for min-size items) -> strong reward.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual > 50 {
        // Large leftover: wasteful split.
        score += 10.0 + 0.2 * (post_residual as f64 - 50.0);
    }

    // Integer-division thresholds: pair current leftover with next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            // This bin can also host the next item -> chain bonus.
            let slack = post_residual - next_item_size;
            score -= 6.0 + slack as f64 / cap;
            if slack <= 10 {
                score -= 6.0; // chain seals bin perfectly
            }
        } else {
            // Next item cannot fit here; leftover is dead unless small.
            if post_residual > 10 {
                score += 5.0;
            }
            // If next item is huge and barely fits a fresh bin, prefer new bin.
            if nx >= 0.7 * cap && fit_ratio > 0.3 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral-ish default, opened only when fits are bad.
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 0.3 * mean_residual;
        if next_item_size > 0 && (next_item_size as f64) / cap > 0.5 {
            score -= 10.0; // big next item: fresh bin valuable
        }
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    }

    // Stream progression: late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (mean_residual / cap);

    // Modulo-flavored harmonic penalty: residuals in awkward classes (11..=19 mod 30)
    // tend to waste space against typical item sizes.
    let m = post_residual % 30;
    if m >= 11 && m <= 19 && post_residual > 20 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps of 1..=9 are almost unusable (min item is small,
    // but tiny gaps waste capacity with near-certainty). Penalize them quadratically.
    if post_residual > 0 && post_residual <= 9 {
        score += (10 - post_residual as i32).pow(2) as f64 * 3.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if the leftover gap cannot fit the next item but is large-ish (trapped space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists;
    // encourage using existing bins so fewer bins stay open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the current mean residual (best-fit flavor with coupling).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make the empty bin attractive only when the item is large and
    // no open bin offers a good fit; otherwise keep it unattractive via residual baseline.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scales down late in the stream when
        // consolidation matters less than clean packing.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 55.0 - 15.0 * progress;
        // If item is large, a fresh bin guarantees a good future; discount the cost.
        if item_size >= bin_capacity / 2 {
            new_bin_cost -= 20.0;
        }
        // If several bins fit the item, opening a new bin is rarely justified.
        if fitting_bins_count > 2 {
            new_bin_cost += 25.0;
        }
        // If the next item is large too, a fresh bin pairs them well.
        if next_item_size >= bin_capacity / 2 {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the remaining space
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits with small leftover: strong lookahead reward
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 40.0 - (slack_after_next as f64).min(40.0);
    }
    // Next item does NOT fit: penalize proportionally to wasted potential
    else if next_item_size > post_residual {
        let gap = (next_item_size - post_residual) as f64;
        score += (gap * 0.5).min(25.0);
    }

    // Tight fit reward (small post_residual is good unless zero)
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 50.0; // bin exactly closed, excellent
    } else if pr < 10.0 {
        score -= 20.0; // near-perfect packing
    } else {
        // dead-space penalty grows super-linearly for unusable gaps
        score += (pr * pr) / (bin_capacity as f64 * 2.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - pr) * 0.3;

    // Late in the stream, consolidate aggressively into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    // Mild preference for reusing existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize post-residuals that are small but unusable (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow: penalize proportionally to wasted capacity.
        score += 0.15 * post_residual as f64;
    }

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more conservative (favor new bins
    // for poor fits); late in the stream, squeeze everything in.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> favor filling
    // existing bins rather than opening more.
    if open_bins_count > 0 {
        let fill_urgency = mean_residual / bin_capacity as f64;
        score -= 5.0 * fill_urgency * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate: only attractive if this bin is empty and the fit is
    // genuinely poor elsewhere (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - tightness);
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: squared post-residual penalizes dead space increasingly
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling of post-residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - norm_pr; // 1 = perfect fit
    score -= 8.0 * tightness * tightness * (0.5 + 0.5 * progress) * cap;

    // Penalize large post-residuals more as the stream advances (fewer chances to fill them)
    score += 6.0 * norm_pr * norm_pr * norm_pr * (0.3 + 0.7 * progress) * cap;

    // Lookahead: reward if next item fits into resulting post_residual (smooth ramp)
    if next_item_size > 0 {
        let fit_ratio = if pr > 0.0 { (norm_next / norm_pr).min(1.2) } else { 0.0 };
        score -= 3.0 * (1.0 - fit_ratio.abs()) * (1.0 + progress);
        // Penalize if post_residual is just barely below next item (near-miss dead space)
        let gap = norm_pr - norm_next;
        score += 2.0 * (1.0 / (1.0 + (gap * 40.0).abs())) * (gap < 0.0) as i32 as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty relative to mean residual: avoid wasting a tight bin when slack is abundant
    score += 1.5 * (mean_residual - pr).abs() / cap;

    // Slight penalty for opening a new bin when many bins are open and progress is high
    if bin_residual == bin_capacity {
        score += (2.0 + 6.0 * progress) * (1.0 + (open_bins_count as f64).ln().max(0.0) * 0.2);
        // but allow new bin if item is large relative to capacity
        score -= 4.0 * norm_item;
    }

    // Smooth diversity term: prefer bins whose residual deviates from mean when item is large
    score += 0.8 * ((pr - mean_residual) / cap).powi(2) * (1.0 + norm_item);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 60.0;
        return score;
    }

    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: residues modulo 10.
    // Residues 0..5 are "usable" slots (many item sizes can re-enter);
    // residues 6..9 are dead-space prone -> penalize.
    let residue_class = post_residual % 10;
    if residue_class <= 5 {
        score -= (5 - residue_class) as f64 * 1.5;
    } else {
        score += (residue_class - 5) as f64 * 2.0;
    }

    // Tiny unusable slivers (1..=4) are dead space regardless of class
    if post_residual <= 4 {
        score += 25.0;
    }

    // Chain potential: does the lookahead item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic bonus scaled by how tightly next item nests
        let nest_tightness = (post_residual - next_item_size) as f64;
        score -= 12.0 - nest_tightness * 0.2;
    } else if next_item_size > 0 {
        // post_residual cannot host next item: mild penalty if sliver
        if post_residual < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Congestion pressure: many open bins -> prefer consolidation
    score += open_bins_count as f64 * 0.3;

    // Progress coupling: late in stream, tighten packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    // New-bin candidate handling: it starts with score = capacity - item_size.
    // Make it attractive only when the item is large (few future fits) or
    // stream is early (amortize the bin over many items).
    if is_new_bin {
        let early_bonus = (1.0 - progress) * 15.0;
        let large_item_bonus = if item_size >= 60 { 10.0 } else if item_size >= 40 { 4.0 } else { 0.0 };
        score -= early_bonus + large_item_bonus;
        // Mean residual high => open bins are fragmented; new bin less costly
        score -= (mean_residual / bin_capacity as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps are mildly penalized to prefer perfect fills.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the resulting gap, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if next item cannot fit into the post residual (dead end for this bin).
    if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and stream progress.
        score += (open_bins_count as f64) * 3.0 + progress * 15.0;
        // A new bin is acceptable if the item fits poorly everywhere else.
        if fitting_bins_count <= 1 && post_residual < 10 {
            score -= 50.0;
        }
    } else {
        // Reward using existing bins, more so when they are scarce.
        score -= 2.0;
        // Last-chance bin: strongly favor filling it to avoid waste.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Favor bins whose residual is below the mean residual (tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward exact/near-exact fits extra.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect chain: next item exactly fills remaining space.
        if gap == 0.0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize dead space proportionally.
        let wasted = post_residual as f64;
        score += 0.5 * wasted;
        // Harsher if residual is small-but-unusable (dead space).
        if post_residual < 10 && post_residual > 0 {
            score += 25.0;
        }
    }

    // Relative to mean residual: bins already fragmented get penalized.
    if mean_residual > 0.0 {
        score += 0.3 * (post_residual as f64 - mean_residual).abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item barely fits anywhere or nothing fits) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = item_size as f64 / bin_capacity as f64;
        // Big items early or with lookahead mismatch justify a fresh bin.
        score = 20.0 + 60.0 * (1.0 - tightness) - 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // fresh bin can chain the next item too
        }
        if fitting_bins_count <= 1 {
            score -= 25.0; // no good alternative open bin
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that no future item can use:
    // if post_residual is smaller than the minimum plausible item, it's waste
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // partial reward proportional to how well next item uses the leftover
            let next_use = next_item_size as f64 / post_residual as f64;
            score -= next_use * 20.0;
        } else {
            // next item won't fit here; slight penalty for leaving awkward gap
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64; // = 1 - item/C
        let scarcity_penalty = if fitting_bins_count == 0 { 0.0 } else { 45.0 };
        // Opening a bin for a large item wastes little; for a small item it's wasteful
        score += 70.0 + fit_quality * 50.0 + scarcity_penalty;
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Encourage packing into bins with below-mean residual (balance-aware)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    // Mild pressure to reduce number of open bins early
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + x * x * x * progress;
    score += 40.0 * poly;

    // Penalize large dead space late in the stream, smooth cubic term
    score += 20.0 * (1.0 - progress) * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Reward tight fits: small post residual gets a smooth quadratic bonus
    score -= 15.0 * (1.0 - x) * (1.0 - x) * progress;

    // Last-chance bin bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: favor leaving room for the next item
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let gap = (pr - nx) / cap;
        if gap >= 0.0 {
            score -= 10.0 * gap * (1.0 - gap);
        } else {
            score += 8.0 * (-gap);
        }
    }

    // Mild penalty when bin deviates from mean residual (smooth coupling)
    score += 0.05 * (pr - mean_residual).abs();

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.02 * open_bins_count as f64 * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by large
    // common item sizes (e.g. multiples of 10/20/25) are more reusable.
    let cap = bin_capacity;
    if post_residual == 0 {
        score -= 30.0; // perfect fit is always best
    } else {
        let mut usable_bonus = 0.0;
        for m in [25u32, 20, 10, 5].iter() {
            if post_residual % m == 0 {
                usable_bonus += 6.0;
            }
        }
        score -= usable_bonus;
        // Dead space penalty: small unclassifiable residuals are wasted.
        if post_residual < 10 {
            score += 18.0;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // extra reward if next item fills the bin completely afterwards
            if post_residual - next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // post residual too small for next item: mild penalty scaled by waste
            score += 4.0 * (1.0 - post_residual as f64 / cap as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when the fit
    // elsewhere is poor. Penalize the fresh bin moderately, but relax the
    // penalty when the current item is large relative to capacity.
    if bin_residual == cap {
        let large_item = item_size as f64 / cap as f64;
        score += 10.0 - 8.0 * large_item;
        // early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
    }

    // Prefer bins with residual below mean (consolidating fuller bins),
    // keeping emptier bins flexible for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild tie-break: favor tighter fits via fractional tightness.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are perfect (waste floor), residuals in the awkward 11..30 range are
    // likely unusable dead space -> heavy penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score -= 25.0; // tiny gap, nearly unusable anyway
    } else if post_residual <= 30 {
        score += 45.0; // awkward dead zone: hard to fill later
    } else if post_residual <= 50 {
        score += 12.0; // moderately awkward
    }

    // Reward tight fits relative to item size (small waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        // But if the leftover would be awkward dead space, soften the bonus.
        if post_residual > 0 && post_residual <= 30 {
            score += 25.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly (chained fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 35.0; // next item fills bin completely
            } else if slack < 10 {
                score -= 15.0;
            } else if slack <= 30 {
                score += 10.0; // next placement would create dead space
            }
        } else {
            // Next item won't fit here; prefer keeping larger residual for it.
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage scattering across many open bins; keep
    // bin count low by mildly favoring already-open bins vs. new bin.
    if bin_residual != bin_capacity {
        score -= 6.0 + (open_bins_count as f64).min(10.0);
    } else {
        // New-bin candidate: penalize opening a new bin when the item is small
        // (wasteful) but allow it for large items needing fresh space.
        score += 15.0 + 0.35 * item_size as f64;
        // If no open bin fits (fitting_bins_count == 0 among open bins),
        // the new bin must win; remove the penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid spawning bins with large residual.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mean residual coupling: when open bins are already fragmented (high mean
    // residual), be extra strict about adding more dead space.
    if mean_residual > 40.0 && post_residual > 0 && post_residual <= 30 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 1.0 {
            score -= 120.0; // perfect 2-step chain
        } else if post >= nxt {
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item can't fit here; penalize leaving dead space
            score += (nxt - post) * 0.5;
        }
        // bonus if next item fills bin completely after chaining
        if (post - nxt).abs() < 1.0 {
            score -= 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong incentive to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + 10.0 * (open_bins_count as f64).ln();
    }

    // Slight penalty for very small unusable residues
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize leaving dead space that no future item (min size 1) could use badly:
    // small post residuals that are too small for typical items are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            score -= 20.0;
        } else {
            // next item cannot use this bin's remainder; slight penalty for tight residuals
            score += (post_residual as f64) * 0.5;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins
    // less greedily to keep flexibility); late in stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 30.0;

    // Prefer bins with residual below mean (consolidating fullness) when many bins open.
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
    }

    // New-bin candidate: make empty bin attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced when the item is large or fit is bad
        let poor_fit = if post_residual > 40 { 1.0 } else { 0.0 };
        score = 70.0 + poor_fit * 50.0 - (item_size as f64) * 0.4;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight packing)
    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, dead space is more costly -> amplify penalty on large residuals.
    let t = progress;
    let coupling = 1.0 + t * t * (3.0 - 2.0 * t); // smoothstep in [1,2]
    score += 0.6 * coupling * (post / cap) * post * 0.01;

    // Reward near-perfect fits via smooth quadratic trough
    let fit_frac = 1.0 - (post / cap);
    score -= 12.0 * fit_frac * fit_frac;

    // Penalize residuals that cannot fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = ((n - post) / cap).max(0.0);
        score += 8.0 * gap * gap * cap * 0.01;
        // Bonus if post_residual leaves room for next item (smooth reward)
        let slack_fit = (post / n).min(1.0);
        score -= 4.0 * slack_fit * slack_fit;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for very large post_residual relative to mean residual (dead space)
    score += 0.05 * (post - mean_residual).max(0.0);

    // New-bin candidate: keep it slightly unattractive unless residuals are large
    if bin_residual == bin_capacity {
        let avg_dead = mean_residual / cap;
        score += 6.0 * (1.0 - avg_dead) * (1.0 - avg_dead) - 3.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over
    let class = (frac * 10.0).floor(); // 0..10 harmonic class

    // Penalize residuals in awkward harmonic classes (small but unusable leftovers).
    // Class 0: perfect fit -> huge reward. Classes 1-3: dead space -> penalize extra.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score += 40.0; // tiny dead space, bad
    } else if post_residual <= 15 {
        score += 15.0;
    } else if post_residual <= 25 {
        score += 5.0;
    } else {
        // larger residuals are more reusable: mild reward scaling
        score -= 10.0 * (1.0 - frac);
    }

    // Integer-division threshold: residual divisible into common item sizes is good.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 12.0; // round residual, easy to fill later
    }
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0; // keeps the chain going
            // exact harmonic match with next item
            if next_item_size == post_residual {
                score -= 50.0;
            }
            // next item divides residual into round pieces
            let rem2 = post_residual - next_item_size;
            if rem2 == 0 {
                score -= 60.0;
            }
        } else {
            // next item won't fit here; residual should still be "harmonically useful"
            score += 8.0;
        }
    } else {
        // last item: prefer perfect fill
        score -= 20.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // with alternatives, prefer tighter fits more aggressively
        score += 3.0 * (fitting_bins_count as f64).min(5.0);
    }

    // New-bin candidate handling: only open a new bin when the item fits badly
    // everywhere (large item relative to mean residual) or early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = (item_size as f64) > mean_residual * 0.9;
        if bad_fit || open_bins_count == 0 || progress < 0.02 {
            score -= 25.0; // opening fresh is attractive
        } else {
            score += 60.0; // discourage wasting fresh capacity
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Progress-based tie-breaker: later in the stream, squeeze harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residuals that can still host a mid/large item later.
    if post_residual >= 50 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
