    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size < 10 {
        score += 15.0; // would create new dead space
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins are open.
    score += open_bins_count as f64 * 0.4;

    // Slight preference for tighter bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: discourage opening a new bin unless it is genuinely better
    // (empty bin has huge residual, so give it a fixed handicap to overcome).
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    // Progress factor: later in the stream, be slightly more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower score when post_residual is small.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: strongly reward exact match between post_residual and next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 50.0; // perfect chain: next item fills this bin exactly
        } else if (post_residual as u32) >= next_item_size {
            let gap = post_residual as f64 - next;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64); // next item fits after this one
        } else {
            // next item cannot follow into this bin: penalize proportionally to waste
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }

        // Bonus if the item after this placement leaves a residual matching common mid sizes
        if post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= 1 && after <= 100 {
                score -= 0.05 * after as f64; // mild preference to keep useful leftovers
            }
        }
    }

    // Compare against mean residual: prefer bins whose residual deviates favorably.
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 0.15 * (res - mean_residual); // larger-than-average space: good host
    } else {
        score += 0.15 * (mean_residual - res); // below-average space: risky
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score = 40.0 + waste * 0.3;
        if post_residual as f64 <= 5.0 {
            score -= 60.0; // near-perfect fit would be wasted by opening a new bin
        }
        // Late in the stream, prefer using existing bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Encourage consolidation when many bins are open.
    if open_bins_count > 5 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
