    score -= 40.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when the fit is poor
    // or when the next item pairs well with a fresh bin.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) < 0.35 * (bin_capacity as f64);
        let pairs_with_next = next_item_size > 0 && (next_item_size as u64 + item_size as u64) > bin_capacity as u64;
        if poor_fit || pairs_with_next {
            score -= 35.0;
        } else {
            score += 30.0;
        }
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 1.5 * (item_size as f64) && bin_residual < mean_residual {
        score -= 8.0 * (1.0 - progress);
    }

    // Prefer filling bins with larger residuals early (keep small residuals flexible).
    score += 0.05 * (bin_residual as f64) * (1.0 - progress);

    // Mild penalty for opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Smooth non-linear coupling: base cost grows superlinearly with wasted space
    let mut score = post_norm * (1.0 + 2.0 * post_norm * post_norm) * cap;

    // Progress-dependent tightening: later in the stream, penalize residual more (compact early, refine late)
    score += progress * 12.0 * post_norm * post_norm * cap;

    // Interaction with mean residual: prefer bins whose residual deviates below mean (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        // smooth penalty when next item cannot fit (dead space risk)
        let gap = (next_item_size as f64 - post) / cap;
        score += 10.0 * gap;
    }

    // New-bin candidate handling: mildly discourage opening new bins when fitting bins exist
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    // Mild penalty for bin proliferation
    score += 0.3 * open_bins_count as f64 * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by divisibility
    // Residuals that are "usable" (multiples of small item sizes) are penalized less.
    let pr = post_residual;
    if pr > 0 {
        // class 0: divisible by 10 (very usable)
        // class 1: divisible by 5
        // class 2: divisible by 3
        // class 3: prime-ish / awkward
        let class = if pr % 10 == 0 {
            0
        } else if pr % 5 == 0 {
            1
        } else if pr % 3 == 0 {
            2
        } else {
            3
        };
        score += class as f64 * 3.0;

        // Small residuals are dead space; penalize non-zero small leftovers hard
        if pr < 10 {
            score += (10 - pr) as f64 * 5.0;
        } else if pr <= 20 {
            score += (20 - pr) as f64 * 1.5;
        }
    }

    // Coupling with next_item_size: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // next item fits: leftover after next placement matters
            let pr2 = post_residual - next_item_size;
            score -= 30.0 - (pr2 as f64).min(30.0);
            if pr2 == 0 {
                score -= 150.0;
            }
        } else {
            // next item does NOT fit here: penalize more if this bin was tight
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 500.0;
        // early in stream, cheaper to open new bins (keep flexibility)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 150.0;
        // if many open bins with large mean residual, prefer reusing them
        score += open_bins_count as f64 * 5.0;
        if mean_residual >= item_size as f64 {
            score += 120.0;
        }
    }

    // Prefer filling fuller bins (tightness reward)
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill * 60.0;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (small waste ratio).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive if it enables a good lookahead fit
    // or open bins are very fragmented.
    if bin_residual == bin_capacity {
        let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size { 15.0 } else { 0.0 };
        score = 100.0 - lookahead_bonus + 5.0 * open_bins_count as f64;
        // Prefer new bin when existing bins are nearly full / fragmented.
        if mean_residual < item_size as f64 {
            score -= 60.0;
        }
        // Late in the stream, consolidation matters less; discourage extra bins mildly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Pressure from too many open bins: favor filling existing ones.
    score += 2.0 * open_bins_count as f64;

    // Lookahead: penalize leaving a residual that exactly wastes the next item's fit.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual as f64 >= next_item_size as f64 {
            // next item fits exactly-ish: strong reward
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable fragments (hard to fill later)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Slight preference for opening new bins early in the stream when
    // current bins would be badly fragmented
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size (1) is less of an issue; scale waste quadratically.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste * waste;

    // Lookahead: if the next item also fits in the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Even better if next item fits snugly afterwards.
        let next_post = post_residual as f64 - next_item_size as f64;
        score -= 8.0 * (1.0 - next_post / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Leaving a residual the next item cannot use: mild penalty proportional
        // to how "stranded" the space is.
        score += 4.0 * (post_residual as f64 / next_item_size as f64).min(1.0);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and would leave a well-balanced residual.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= bin_capacity / 2 {
            score -= 18.0;
        }
        // Early in the stream, new bins are cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // Many open bins with high mean residual: avoid adding another.
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Prefer bins whose residual deviates favorably from the mean (fill emptier
    // bins when mean residual is high, keep tight bins tight).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for filling bins with larger residual when late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late, penalize it quadratically.
    let progress_coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += 30.0 * progress_coupling;

    // Cubic dead-space penalty: strongly discourage residuals that become unusable
    let unusable_threshold = 10.0;
    let dead = ((unusable_threshold - pr).max(0.0)) / cap;
    score += 60.0 * dead * dead * (1.0 + progress);

    // Lookahead: reward bins whose residual can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let snug = 1.0 - ((pr - nx) / cap);
            score -= 15.0 * snug * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Crowd-out penalty: many open bins with high mean residual -> prefer consolidation
    let mean_norm = mean_residual / cap;
    if norm_pr < mean_norm {
        score -= 8.0 * (mean_norm - norm_pr) * (open_bins_count as f64).ln().max(1.0);
    } else {
        score += 8.0 * (norm_pr - mean_norm);
    }

    // Slight preference for opening new bins early when current fit is loose
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: harmonic class post_residual % 10 == 0
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead space penalty for small unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: does next item fit in post_residual? Reward if yes.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic bonus: post_residual - next_item_size in nice class
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is huge
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Fraction-of-capacity coupling on residual classes
    let residual_quarter = bin_residual / (bin_capacity / 4);
    score += match residual_quarter {
        0 => 5.0,
        1 => 0.0,
        2 => -2.0,
        _ => -4.0,
    };

    // Stream progression: later in stream, be more aggressive about filling bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Prefer bins below mean residual (tighter bins) mildly
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical items (<= 10) are unusable "dead space" -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small gaps that only fit the tiniest items are near-waste.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits (waste-free packing).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading items across many bins
    // unless the fit is genuinely good.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item could use the post_residual,
    // reward leaving exactly that amount of space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap the next item almost fits but not quite.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Early in the stream, be slightly more willing to open bins to build
    // a diverse residual pool; later, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress);

    // New-bin candidate (fresh empty bin): neutral base, penalized unless
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced consolidation) unless it creates dead space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact 2-step matches: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        // Perfect match bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual that next item can't use
        if next_item_size > post_residual {
            score += 15.0;
        }
    }

    // Small post-residual is good (tight fit), but avoid unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward bins that are tighter than the mean residual (good consolidation)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening new bins when open bins exist that fit
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional waste relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward leaving exactly enough room for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (-slack / 20.0).exp();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    let pressure = (open_bins_count as f64 / (mean_residual + 1.0)).tanh();
    score -= 10.0 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for opening a new bin, stronger early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress) + 5.0;
        // Opening a new bin is acceptable if no good fit exists elsewhere.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Penalize bins whose residual deviates far from the mean (balance preservation).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Late-stream consolidation: favor existing bins as the stream ends.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * horizon;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - post / cap; // 0..1, higher = tighter fit
    let progress_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 24.0 * tightness * tightness * progress_weight;

    // Penalize dead space quadratically, scaled by mean residual context
    let dead = post / cap;
    score += 18.0 * dead * dead * (1.0 - progress_weight);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * tightness;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_ratio = next_item_size as f64 / post.max(1.0);
        score -= 12.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * progress;

    // Context term coupling bin residual with mean residual
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals divisible by common item sizes
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for d in [10u32, 20, 25, 50, 100].iter() {
            if pr % d == 0 {
                harmony += 1.0;
            }
        }
        score -= harmony * 6.0;
        // small dead-space penalty: residuals below 10 are nearly unusable
        if pr < 10 {
            score += 40.0;
        }
    } else {
        // perfect fill is ideal
        score -= 60.0;
    }

    // Next-item coupling: reward residuals that can host the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (next_item_size as f64) * 0.15;
            // exact chain fit
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // Tight fit reward: fraction of bin used by this item
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Prefer fuller bins when many bins are open (keep bin count down)
    score += (open_bins_count as f64) * 0.5 * (1.0 - fill_frac);

    // Mean residual coupling: avoid disturbing bins far from the mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Progress scaling: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: make empty bins attractive only when item is large
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        if large > 0.6 {
            score -= 25.0 * (large - 0.6) / 0.4;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item are pure waste -> strong penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.max(1)) {
        score += 40.0;
    }

    // Reward near-perfect fits (post_residual very small but not penalized above).
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Penalize leaving a gap that cannot fit the lookahead item (k=2 lookahead),
    // but only if the gap also can't fit a mid-range item -> likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; prefer
    // consolidating when many bins are already open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Brand-new bin candidate: make it unattractive unless it is the only option.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 3.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open a new bin
        }
    }

    // Mild preference for bins whose residual deviates from the mean
    // (keep homogeneous bins for future flexibility).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Late-stream tightening: as the stream progresses, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post_residual is better, but only if it's not dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // The next item can still fit here: reward proportionally to slack alignment
        let alignment = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 25.0 * alignment;
    } else {
        // Dead space: post_residual too small for the next item — penalize.
        let deadness = if next_item_size > 0 {
            (next_item_size - post_residual) as f64 / bin_capacity as f64
        } else {
            post_residual as f64 / bin_capacity as f64
        };
        score += 20.0 * deadness;
    }

    // Penalize waste relative to mean residual: creating below-average residuals fragments the fleet.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless this fit is poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If next item is large and this item leaves nothing usable, new bin is fine.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Slight bonus for keeping residuals that match common item sizes (divisibility-friendly).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with mild non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * norm_post * (1.0 - progress));

    // Non-linear coupling with stream progress: as the stream matures, dead space
    // becomes increasingly costly (quadratic growth in progress).
    score += 12.0 * norm_post * norm_post * (0.5 + progress);

    // Penalize post_residual that cannot accommodate the lookahead item
    // (wasted potential), smoothed rather than piecewise.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            let deficit = (nx - post) / cap;
            score += 25.0 * deficit * deficit * (1.0 + progress);
        } else {
            // Reward bins whose leftover exactly primes the next item (smooth bonus).
            let slack = (post - nx) / cap;
            score -= 8.0 * (-6.0 * slack).exp();
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smooth ramp by scarcity).
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Cost of opening a bin: declines slightly as stream progresses is wrong
        // direction; keep it costly, but cheaper when mean residual is large
        // (existing bins are fragmented) or many bins already open.
        let fragmentation = (mean_residual / cap).min(1.0);
        score = 0.55 * cap
            - 15.0 * fragmentation
            - 4.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Mild preference for packing into bins that are already below-average residual
        // (consolidation), smooth interaction with progress.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * dev * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo structure of capacity
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -25.0,                 // perfectly divisible residual: excellent
        5 => -12.0,                 // half-class: good
        1 | 2 | 3 | 4 => 6.0,       // small slivers: near-dead space
        _ => 0.0,
    };
    score += class_penalty;

    // Penalize tiny unusable residuals (dead space), scaled by item size
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual (perfect chain)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let nclass = (post_residual - next_item_size) % 10;
            if nclass == 0 { score -= 15.0; }
            score -= 5.0;
        } else {
            // next item won't fit here: mild penalty for wasting the slot
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline, penalize opening new bins
    // when decent fits exist among open bins
    if bin_residual == bin_capacity {
        // opening a new bin costs ~ one bin: add fixed penalty
        score += 55.0;
        // less penalty late in stream if many bins already open? keep fixed.
        // reward opening new bin if item is huge and residuals are tight
        if item_size >= 70 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    } else {
        // prefer tighter existing bins: reward small residual before placement
        score += (bin_residual as f64) * 0.15;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter than mean)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Mild stream-position coupling: early on, be conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest future item (min size 1..10) are effectively wasted.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0; // unusable sliver
    }
    // Dead space that cannot fit the lookahead item (when known) is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fit_ratio * fit_ratio;
    }

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading out; new empty bins get penalized.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Progress: late in the stream, tighten up and prefer tight fits even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - fit_ratio_safe(item_size, bin_residual));

    // Prefer bins whose residual is below the mean (consolidating fuller bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

#[inline]
fn fit_ratio_safe(item_size: u32, bin_residual: u32) -> f64 {
    if bin_residual == 0 { 0.0 } else { (item_size as f64 / bin_residual as f64).min(1.0) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits exactly
    // into the post-residual (chain of perfect fills).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space smaller than next item: penalize, worse when very small.
            let dead = post_residual as f64;
            let dead_ratio = dead / bin_capacity as f64;
            score += 120.0 * (1.0 - dead_ratio) * (1.0 - dead_ratio);
            // Extra penalty if next item barely misses (near-miss dead space).
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += 60.0 * (1.0 - miss / 10.0);
            }
        }
    } else {
        // Last item: strongly prefer tightest fill.
        score -= 300.0;
    }

    // Relative to mean residual: bins with residuals well below mean are
    // "tight" bins — using them keeps loose bins available for future items.
    let res_f = bin_residual as f64;
    let dev = res_f - mean_residual;
    if dev < 0.0 {
        score += 0.5 * dev; // tighter than average -> slightly penalize using it
    } else {
        score += 0.3 * dev; // looser than average -> favor using it
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: empty bin is a fallback. Prefer it only
    // when no open bin offers a decent fit. Penalize opening new bins
    // increasingly as stream matures.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 180.0 + 200.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > item_size {
            new_bin_penalty -= 80.0;
        }
        // Many open bins: discourage more.
        new_bin_penalty += 5.0 * open_bins_count as f64;
        score += new_bin_penalty;
    }

    // Small structural bonus for high fill fraction.
    score -= 0.2 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual > 50 && post_residual < 60 {
        score += 8.0; // awkward residual band
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Lookahead coupling: prefer bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if next item fits almost exactly.
            let next_fit = (post_residual as f64 - next_item_size as f64).abs();
            score -= 8.0 * (1.0 - next_fit / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Global state: many open bins with slack -> prefer filling existing ones.
    if open_bins_count > 4 {
        let pressure = mean_residual / bin_capacity as f64;
        score -= 10.0 * pressure * ((open_bins_count as f64).ln() / 3.0).min(2.0);
    }

    // Time horizon: early in stream, keep bins flexible; late, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate: only attractive when item barely fits nothing well
    // or current bin would leave a large awkward residual.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score = 60.0 + 40.0 * poor_fit;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // fresh bin can host next item too
        }
        if fitting_bins_count <= 1 {
            score -= 70.0; // no real alternative: opening new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: waste matters more as stream progresses
    score += 25.0 * progress * norm_pr * norm_pr;

    // Reward tight fits smoothly (small post_residual)
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness;

    // Penalize residual that cannot fit the lookahead item (dead space), smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let deficit = (ni - pr) / cap;
            score += 40.0 * deficit * (1.0 + progress);
        } else {
            // Reward leaving room for the next item
            let slack = (pr - ni) / cap;
            score -= 10.0 * slack * (1.0 - slack);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild pressure from number of open bins: prefer filling existing bins when many are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // Divergence from mean residual: prefer bins whose residual is near the mean (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: smooth penalty scaled by how well the item would fit and stream progress
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit: strongly favored
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -9.0
    } else if pr <= 9 {
        22.0 // tiny dead space is nearly unusable
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: leftover that cannot host the next item is wasted.
    if next_item_size > 0 {
        if pr < next_item_size && pr > 0 {
            score += 14.0 * (1.0 - pr as f64 / next_item_size as f64);
        } else if pr >= next_item_size {
            // leftover can still host next item: reward proportional slack
            score -= 6.0 * (pr as f64 / bin_capacity as f64);
        }
        // Integer-division coupling: how many next-items could this residual hold
        let fits_next = (pr / next_item_size.max(1)) as f64;
        score -= 5.0 * fits_next.min(3.0);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    // or open bins are congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 30.0 + 25.0 * progress + 4.0 * congestion;
        if post_residual % 10 == 0 && post_residual >= 20 {
            score -= 20.0; // fresh bin with harmonic residual is fine early
        }
    }

    // Prefer tightest fill relative to mean residual across open bins.
    score -= 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot hold even the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward near-perfect fits (post residual very small but nonzero).
    if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward exact fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling with dead space: penalize gaps too small for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 15.0 + open_bins_count as f64 * 4.0;
    } else {
        // Mild reward for filling already-open bins proportional to occupancy.
        score -= (bin_capacity - bin_residual) as f64 * 0.15;
    }

    // Early stream: be a bit more tolerant of opening bins (future flexibility);
    // late stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if new_bin {
        score -= progress * 10.0;
    } else {
        score -= progress * 5.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight -> good candidate; if far above, penalize slightly.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + gap);
        if gap == 0.0 {
            score -= 20.0; // perfect 2-step chain
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot fit in the leftover: dead space penalty scaled by gap.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.15 * dead;
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably.
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer existing bins generally; only open a new
    // bin when the current bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        // Base new-bin score: slightly above a decent fit.
        score += 10.0;
        // Opening a new bin is attractive if the item is large and would leave
        // a tiny residual elsewhere anyway, or if no existing bin fits well.
        let frac = (item_size as f64) / (bin_capacity as f64);
        if frac > 0.8 {
            score -= 30.0; // large items start fresh bins
        }
        if post_residual as f64 > mean_residual + 20.0 {
            score += 15.0; // would create above-average dead space
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Small penalty for many open bins to encourage consolidation.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins whose leftover still accommodates the next item.
            score -= 0.25 * (post_residual - next_item_size) as f64;
        }
    } else {
        // End of stream: just minimize post_residual.
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Time horizon: early on, prefer compacting into existing bins less aggressively
    // (keep flexibility); late, squeeze hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * tightness;

    // Global residual balance: prefer bins near the mean residual (keeps bins uniform,
    // leaving large bins for large future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Many open bins: discourage spreading; fewer open bins: encourage reuse.
    score += 0.05 * open_bins_count as f64;
    score -= 0.03 * (open_bins_count as f64) * tightness;

    // New-bin candidate: penalize slightly so we only open when existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 6.0 + 3.0 * progress;
        // But if next item is large and this item is small, opening fresh is fine.
        if next_item_size >= 70 && item_size <= 30 {
            score -= 5.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score = score * (0.5 + poly) + 30.0 * progress * poly;

    // Reward tight fits, more strongly later in the stream
    let tight = 1.0 - norm_pr;
    score -= 40.0 * tight * tight * (0.5 + progress);

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly prefer using a lone fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 12.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 8.0 * (ns - pr) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize mildly unless residuals elsewhere are tight
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * (1.0 - mean_residual / cap) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common size buckets) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead space penalty: leftover in (0, 10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic class reward: post_residual divisible by 10 or 25 keeps space
    // packable by typical item sizes.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Fraction-of-capacity coupling: leftover near half or full capacity is
    // flexible; leftover in the awkward 60..80 band is penalized mildly.
    let frac = pr / cap;
    if (0.15..0.45).contains(&frac) {
        score -= 3.0;
    }
    if (0.60..0.80).contains(&frac) {
        score += 2.0;
    }

    // Lookahead harmony: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= (next_item_size as f64) * 0.15;
        } else {
            // next item cannot fit here: slight penalty for wasting big space
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // have poor fits. Make empty bin score track mean residual pressure.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced when open bins are crowded.
        score = cap * 0.35 - mean_residual * 0.4;
        if open_bins_count == 0 {
            score -= 50.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild pressure toward filling already-crowded bins.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // mildly awkward gap
    }

    // Reward very tight fits (waste < 5).
    if post_residual < 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: prefer a fresh bin when the item is large
    // (leaves a clean large residual) or when existing bins would be wrecked.
    if bin_residual == bin_capacity {
        let frac = post_residual as f64 / bin_capacity as f64;
        // Fresh bin is attractive if the leftover space is large and reusable
        // or if the item nearly fills the bin.
        if frac > 0.5 || post_residual < 5 {
            score -= 10.0 + 8.0 * frac;
        }
        // Pressure: with many open bins, opening another is costly.
        score += open_bins_count as f64 * 0.8;
    } else {
        // Open-bin pressure: reusing open bins keeps the count down.
        score -= open_bins_count as f64 * 0.3;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 4.0; // would create dead space for the next item
    }

    // Slight preference for balancing residuals toward the mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            // Next item fits here afterwards: reward tight coupling.
            let tightness = 1.0 - ((post_residual as f64 - next) / bin_capacity as f64);
            score -= 40.0 + 60.0 * tightness;
        } else {
            // Post residual too small for next item: penalize unusable sliver,
            // worse when the sliver is tiny (dead space).
            let sliver = post_residual as f64;
            score += 20.0 + 30.0 * (1.0 - sliver / (bin_capacity as f64 * 0.5).min(1.0).max(0.0).max(sliver / (bin_capacity as f64 * 0.5)));
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (consolidate),
    // penalize packing into already-loose bins.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // but allow it early in the stream or when item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_if_open = bin_capacity as f64 - item_size as f64;
        score += 120.0 * (1.0 - progress) + 0.3 * waste_if_open - 50.0 * (open_bins_count as f64 / 10.0).min(1.0);
        // New bin attractive if item is huge relative to typical residual.
        if (item_size as f64) > mean_residual {
            score -= 80.0;
        }
    }

    // Mild preference for tighter existing bins overall.
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (hard-to-fill leftovers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Last-chance bonus: avoid opening a new bin if this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Perfect chain: current fit leaves exactly room for next item
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: prefer new bin only when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin
        score += 20.0;
        // Early in stream, new bins are cheaper; late, prefer filling open bins
        score -= 15.0 * (1.0 - progress);
        // If many open bins with large mean residual, opening new bin is wasteful
        score += (mean_residual / bin_capacity as f64) * 10.0;
        // If item is large relative to typical residual, new bin may be wise
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
        // Last chance among fitting bins: strongly discourage new bin
        if fitting_bins_count >= 1 && bin_residual == bin_capacity {
            score += 8.0 * (fitting_bins_count as f64);
        }
    }

    // Prefer bins with residual close to capacity-average (balanced usage)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Slight preference for fewer open bins overall
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base: favor tight fits (small post_residual), with mild non-linear shaping.
    score += 0.35 * (post / cap) * (1.0 - post / cap) * cap * 0.1;

    // Dead-space penalty: residuals too small to ever be useful are penalized strongly.
    let min_useful = 10.0_f64.min(cap);
    if post < min_useful {
        score += (min_useful - post) * 2.5;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // more so as the stream progresses (compounding future-fit value).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= (1.0 + 3.0 * progress) * (1.0 - slack) * 6.0;
        } else {
            // Post residual nearly useless for the known next item: mild penalty.
            score += (1.0 - progress) * 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 + 0.5 * progress);
    }

    // New-bin candidate handling: an empty bin should only win when open-bin fits are bad.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more when many bins are open and mean residual is large.
        let mean_waste = mean_residual.max(0.0) / cap;
        score += 15.0 + 8.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * mean_waste;
        // But if the current item is large and leaves little room, new-bin penalty softens.
        score -= (item_size as f64 / cap) * 10.0;
    } else {
        // Mild preference for fuller bins among open candidates (best-fit reinforcement).
        score -= (1.0 - bin_residual as f64 / cap) * 3.0;
    }

    // Smooth stream-progress coupling: early on, keep bins flexible (favor larger post_residual
    // slightly); late, pack tightly (favor small post_residual aggressively).
    let flexibility = (1.0 - progress) * (post / cap);
    score += 4.0 * flexibility * (1.0 - flexibility);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals that are "usable"
    // for common future item sizes should be rewarded (score reduced).
    let pr = post_residual;
    // Class A: residual >= 50 (can host a large item) -> strongly usable.
    if pr >= 50 {
        score -= 18.0;
    } else if pr >= 34 {
        score -= 9.0;
    } else if pr >= 25 {
        score -= 4.0;
    } else if pr >= 10 {
        score -= 1.0;
    } else {
        // Dead space: 0..9 residual is nearly unusable (min item is 10).
        score += 14.0;
    }

    // Modulo structure: residuals divisible by common size classes (10, 20, 25)
    // are more likely reusable -> reward via harmonic classes.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 5.0;
        }
        if pr % 25 == 0 {
            score -= 3.0;
        }
        if pr % 20 == 0 {
            score -= 2.0;
        }
    }

    // Exact fit is ideal.
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // Next item fits: reward proportional to how well it packs.
            score -= 6.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else if next_item_size > pr && next_item_size - pr <= 10 {
            // Near miss: mild penalty for blocking the chain.
            score += 4.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it only wins when
    // all open bins are poor fits, but allow it when residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheap; late, prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If many open bins already have large mean residual, reuse them.
        if mean_residual > 40.0 {
            score += 6.0;
        }
    }

    // Prefer bins tighter than the fleet average (good utilization).
    let residual_frac = bin_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    if residual_frac < mean_frac {
        score -= 3.0 * (mean_frac - residual_frac);
    } else {
        score += 2.0 * (residual_frac - mean_frac);
    }

    // Large items should prefer large residuals (avoid stranding big holes).
    if item_size >= 60 && bin_residual < item_size + 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 && post_residual > 0 {
        score += 25.0;
    }

    // Reward near-perfect fits (waste below 10 is "recovered" capacity).
    if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; it wins only when all
        // open bins would leave large dead space.
        score += 15.0 + 0.05 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: nothing fits anywhere else
        }
    } else {
        // Prefer bins whose residual is close to what we consume (tight packing).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.10 * gap;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (creates a perfect follow-up slot).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Open-bin count pressure: many open bins -> consolidate into existing ones.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins below the mean residual (fill the emptier bins first
    // keeps more tight bins available for future items).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Late in the stream, tighten up: dead space matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not exact-zero fits
    // that leave nothing for the next item unless the next item is tiny.
    let pr = post_residual as f64;

    // 2-step lookahead: strongly reward bins whose post_residual can host next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // next item fits here afterwards: reward proportionally to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
            // exact chain fit (item + next fills bin) is ideal
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // next item won't fit after this placement: penalize, scaled by how
            // much we "waste" relative to the next item's size
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.3 * waste;
        }
        // If the NEXT item would perfectly fill the current residual (i.e. this
        // item should go elsewhere so the next item takes this bin), penalize
        // using this bin for the current item.
        if bin_residual == next_item_size && next_item_size >= item_size {
            score += 15.0;
        }
    } else {
        // Last item: pure tight-fit preference.
        score = pr;
    }

    // Dead-space penalty: small post_residual that can't fit typical items
    // (items >= 1..100 unknown, but tiny residuals < 10 are usually dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Compare against mean residual: placing into a bin with residual far below
    // mean concentrates waste; placing into larger-than-mean residual is safer.
    if pr > mean_residual {
        score -= 0.15 * (pr - mean_residual);
    } else {
        score += 0.15 * (mean_residual - pr);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in
    // the stream or when the item is huge and no bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // A new bin wastes (C - item). Penalize unless item is large or we are early.
        score = bin_capacity as f64 - 40.0 * fill_ratio - 15.0 * (1.0 - progress);
        // If only candidate, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: post_residual near zero is good.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Penalize dead space that no future item can plausibly use:
    // small residuals (<10) are pure waste unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slightly penalize leaving medium gaps
            if post_residual >= 10 && post_residual < next_item_size {
                score += 4.0;
            }
        }
    }

    // New-bin candidate logic: opening a new bin is attractive only when
    // existing fits are poor (high post_residual) or few bins fit the item.
    if is_new_bin {
        let waste_if_open = (bin_capacity - item_size) as f64;
        let poor_existing = if fitting_bins_count > 0 {
            (post_residual as f64 / bin_capacity as f64) // residual of new bin after placement
        } else {
            0.0
        };
        // Early in the stream: prefer new bins to keep flexibility.
        let early_bonus = (1.0 - t) * 10.0;
        // Many open bins with low mean residual: prefer consolidation instead.
        let crowding = open_bins_count as f64 * 0.5;
        let mean_gap = (mean_residual - waste_if_open).abs();
        score += 15.0 + poor_existing * 20.0 - early_bonus + crowding * 0.3
                 - mean_gap * 0.1;
        // Perfect fill of a fresh bin is great.
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Mild preference for fuller bins relative to the fleet average.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Late-stream consolidation: favor existing bins more as stream ends.
    score += t * 3.0 * (open_bins_count as f64).ln().max(0.0) * if is_new_bin { 1.0 } else { -0.2 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are mildly tolerated; late in the stream,
    // wasted residual is penalized super-linearly.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (pr * pr) / cap;

    // Reward tight fits with a smooth saturating term.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);

    // Lookahead coupling: if the next item can use the post residual,
    // reward this placement smoothly; otherwise penalize slightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = (pr - nxt).max(0.0) / cap;
        let exact = (pr - nxt).abs() as f64 / cap;
        score -= 8.0 * compat * (1.0 - compat);
        score += 6.0 * exact * exact;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    // (smoothly damped by progress so new bins are more attractive early).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - 0.5 * progress);
    }

    // Slight penalty for residual far from mean residual (outlier dead space).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Mild penalty for opening new bins late in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Class 0: divisible by 10 (clean slot), Class 1: odd/awkward, etc.
    let harmonic_class = (post_residual % 10) as f64;
    score += harmonic_class * 1.7;

    // Perfect fit: extremely desirable
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Post residual in harmonic "dead zone": small leftovers are dead space
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits, but check harmonic alignment of the double leftover
            let chain = post_residual - next_item_size;
            score -= 120.0 - (chain % 10) as f64 * 4.0;
            if chain == 0 {
                score -= 250.0;
            }
        } else {
            // next item won't fit here; penalize more if this bin was the only option
            score += 25.0;
        }
    } else {
        // last item: prefer tightest packing
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so we prefer existing bins with decent fit
        score += 180.0;
        // if many bins fit, discourage new bin strongly
        if fitting_bins_count > 2 {
            score += 120.0;
        }
        // if no other bin fits well (post_residual small in others implied by low mean residual),
        // allow opening a fresh bin
        if mean_residual < 20.0 {
            score -= 150.0;
        }
        // mid-stream: fresh bins keep future flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0;
    }

    // Reward packing into bins whose residual is far above mean (consolidate space)
    if bin_residual as f64 > mean_residual + 15.0 && !is_new_bin {
        score -= 30.0;
    }

    // Integer-division threshold: large post residual chunks are flexible
    if post_residual / 20 >= 2 {
        score -= 15.0;
    }

    // Penalize creating residual just below common item sizes (10..80) — awkward gaps
    let gaps = [10u32, 20, 30, 40, 50, 60, 70, 80];
    for g in gaps.iter() {
        if post_residual > *g && post_residual < g + 9 {
            score += 12.0;
        }
    }

    // Many open bins: encourage closing small-residual bins
    if open_bins_count > 8 && post_residual < 15 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the smallest possible item are pure waste.
    if post_residual < 10 {
        score += 200.0; // dead space, nothing can ever fill it
    } else if post_residual < 25 {
        // small unusable-ish gaps: strongly penalized
        score += 60.0;
    } else if post_residual >= 25 && post_residual <= 45 {
        // medium gaps can host typical items: mild bonus
        score -= 15.0;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward if the lookahead item exactly fills the remaining gap
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // gap too small for the next item -> it becomes semi-dead unless future items fit
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // new-bin candidate: apply open-bin pressure penalty
        score += 30.0 + pressure;
    } else {
        // slight reward for existing bins proportional to consolidation need
        score -= pressure * 0.1;
    }

    // Prefer bins with residual close to mean (balanced packing) mildly
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    // Tight-fit bonus: fraction of bin used
    let used_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= used_frac * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the leftover space matches the next item
    if next_item_size > 0 {
        let lookahead_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: next item exactly fills the post residual
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward proportionally to tightness of the chain
            score -= 150.0 * (1.0 - lookahead_diff / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space creation
            score += 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // Extra penalty if the leftover is too small for typical items (wasted space)
        if post_residual < 10 && post_residual > 0 {
            score += 80.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score += 0.0;
    }

    // Compare against mean residual: prefer bins with below-average residual (tighter bins)
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.5 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 200.0;
        // But if the item is large relative to capacity, a fresh bin is more attractive
        score -= 1.5 * item_size as f64;
        // If many open bins exist with poor average residual, fresh bin is reasonable
        if mean_residual < 20.0 {
            score -= 100.0;
        }
    }

    // Mild preference for consolidating into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 18.0;
    } else if post_residual < 10 {
        // Small but nonzero dead space: penalize — this space is likely unusable.
        score += 10.0 + (10 - post_residual) as f64 * 0.8;
    }

    // Lookahead: if the next item can chain into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 7.0 * chain_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual can't host the next item: mild penalty proportional to wasted potential.
        score += 1.5;
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: mildly penalize so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.25 * open_bins_count as f64;
        // If the item is large relative to capacity, opening fresh is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 4.0;
    }

    // Global state coupling: when mean residual across bins is high, prefer bins
    // that consume from the residual-rich pool (large fill).
    score -= 0.05 * mean_residual * (item_size as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 4.0 * progress;
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let item = item_size as f64;

    // Base: penalize post residual, with non-linear (quadratic) waste shaping.
    let mut score = pr + 0.012 * pr * pr / capacity;

    // Smooth interaction: waste is more costly as stream progresses.
    let progress_coupling = 1.0 + 0.9 * progress * progress;
    score *= progress_coupling;

    // Tight fits rewarded: subtract when post_residual is a small fraction of capacity,
    // using smooth saturating term (1 - (pr/C)^2).
    let tightness = 1.0 - (pr / capacity) * (pr / capacity);
    score -= 6.0 * tightness * (item / capacity);

    // Penalize bins whose residual deviates from mean residual (fragmentation steering).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / capacity;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how well it fits).
    if fitting_bins_count <= 1 {
        score -= 8.0 * tightness;
    }

    // Lookahead: reward leaving room for the next item (smooth overlap term).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 3.0 * (1.0 - (gap / capacity) * (gap / capacity));
        } else {
            score += 0.03 * (-gap) * (-gap) / capacity;
        }
    }

    // Mild penalty on opening new bins when many are open (encourage consolidation).
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: post_residual small relative to item size
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Fractional fill reward
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Harmonic class: penalize post_residual that can't fit common small items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space class
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New bin candidate: penalize opening a new bin unless current bins are bad
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if open bins are fragmented, new bin is less bad
        if mean_residual < 15.0 {
            score -= 45.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins below mean residual (consolidate emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Progress: as stream nears end, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below ~10 are nearly unusable
    // for future items (items >= 1..100, but typical min ~10), so penalize
    // small-but-nonzero gaps super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 8.0; // dead space penalty
        } else if pr < 20.0 {
            score += (20.0 - pr) * 2.5; // awkward gap penalty
        } else {
            score -= pr * 0.3; // large residual is valuable, reward
        }
    } else {
        score -= 30.0; // perfect fit: bin fully consumed
    }

    // Pressure from number of open bins: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are very full (small mean residual) or none fit well.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.5; // default penalty for new bin
        if mean_residual < 15.0 {
            score -= 35.0; // open bins nearly full -> prefer fresh bin
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 15.0; // lookahead: fresh bin keeps room for next item
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 - gap.min(20.0) * 0.5;
    }

    // Slight preference for tighter fits overall (item fills larger share)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover space matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff); // tight match with next item is highly rewarded

        // If next item fits exactly in the post-residual, big bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit in post-residual, penalize dead space proportionally.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0;
    }

    // Penalize leaving large unusable gaps relative to mean residual.
    if (post_residual as f64) > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for opening new bins when open bins exist and fit reasonably.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 0.2 * open_bins_count as f64;
    }

    // Prefer bins with less residual overall (best-fit bias).
    score += 0.1 * bin_residual as f64;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (low post-residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 30.0;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 12.0; // next item cannot use leftover space
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win.
        score += 15.0;
        // If many bins fit the item, discourage new bin strongly.
        if fitting_bins_count > 2 {
            score += 40.0;
        }
        // If item is large relative to mean residual, opening a fresh bin is fine.
        let mean_fit_gap = mean_residual - item_size as f64;
        if mean_fit_gap < 0.0 || (fitting_bins_count > 0 && mean_fit_gap > 0.0 && mean_fit_gap < 15.0) {
            score -= 20.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    // Slight preference for filling bins with larger residuals when mean residual is high.
    if !is_new_bin {
        let residual_gap = bin_residual as f64 - mean_residual;
        score += residual_gap * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;

    // Smooth polynomial coupling: post_residual weighted by stream progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (pr - mean_residual) / cap;
    score += 15.0 * dead * dead;

    // Lookahead: reward bins whose post_residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild penalty for bin proliferation early
    score += 3.0 * (open_bins_count as f64 / (total_items as f64 + 1.0)) * (1.0 - progress);

    // Favor large item fraction into residual (efficient packing)
    score -= 10.0 * norm_item * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "usable" class (>= 10, or exactly 0) are rewarded; tiny dead space is penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fill
    } else if pr < 10 {
        score += 30.0; // dead space class: unusable for any future item
    } else {
        // reward residuals that are "harmonic" with common item sizes
        // (multiples of 5 and >= 20 are highly reusable)
        if pr % 5 == 0 {
            score -= 6.0;
        }
        if pr >= 20 {
            score -= (pr as f64) * 0.15;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportionally to how much it consumes
            score -= 10.0 + (next_item_size as f64 / pr as f64) * 15.0;
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 4.0 + ((next_item_size - pr) as f64) * 0.1;
        }
    } else {
        // last item: prefer zero residual strongly
        score += (pr as f64) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity && pr < 10 {
        score -= 20.0;
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for large items or when the
        // current item leaves a poor harmonic class in every existing bin.
        // Base cost of opening a bin:
        score += 35.0;
        // Large items are better placed in fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // If next item is large too, fresh bin pairs well (post_residual = 100 - item).
        if next_item_size > 0 && next_item_size == pr {
            score -= 45.0;
        }
        // Late in the stream, avoid bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // Many open bins: discourage opening yet another one.
        score += (open_bins_count as f64) * 1.5;
    } else {
        // Reward using bins whose residual is below the mean (tight packing).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Small tie-breaking preference for tighter current fit.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 8.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Deviation from mean residual: prefer bins close to mean (balanced packing),
    // but avoid leaving large residuals when mean is small.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: make it attractive only when existing bins would leave bad gaps.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by avoiding dead space.
        score = 45.0 + 0.3 * open_bins_count as f64;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
        if item_size >= 50 {
            score -= 8.0; // large items fit well in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post_residual).
    score += (post_residual as f64) * 0.02;

    // 2-step lookahead: reward when next item fits into post_residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect match for next item: big reward.
            if slack == 0.0 {
                score -= 40.0;
            } else {
                score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow here; mild penalty scaled by gap.
            score += 0.05 * ((next_item_size - post_residual) as f64);
        }
    }

    // Compare post_residual to mean residual: leaving near-average residual is fine,
    // extreme dead space is penalized.
    score += 0.10 * ((post_residual as f64 - mean_residual).abs());

    // Penalize small unusable dead space (< 10) that no item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish baseline; lookahead reward if next item pairs with item_size.
        if next_item_size > 0 {
            let pair = (item_size + next_item_size) as f64;
            if pair <= bin_capacity as f64 {
                let rem = bin_capacity as f64 - pair;
                score -= 18.0 * (1.0 - rem / bin_capacity as f64);
            } else {
                score += 10.0;
            }
        }
        // Discourage opening new bins when good existing options exist.
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 8.0;
        }
    }

    // Late in the stream: consolidate more aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space is disproportionately good).
    if post_residual < 10 {
        score -= 60.0;
    } else if post_residual < 25 {
        score -= 25.0;
    }

    // Penalize creating dead space that nothing small could use later.
    if post_residual > 0 && post_residual < 10 {
        score += 0.0; // tiny leftover already rewarded
    }
    if post_residual >= 10 && post_residual < 20 && next_item_size > post_residual && next_item_size > 0 {
        score += 15.0; // leftover can't hold the next item
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 80.0;
        } else if diff <= 5 {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fits poorly.
    if bin_residual == bin_capacity {
        // Baseline penalty: opening new bins is expensive.
        score += 35.0;
        // If many bins are open and mean residual is high, opening new bins is worse.
        score += (open_bins_count as f64).sqrt() * 3.0;
        score += mean_residual * 0.2;
        // Early in the stream, be more willing to open bins (exploration).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Prefer fuller bins slightly: reward closeness of fit relative to capacity.
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    // Mild penalty for spreading across many open bins when mean residual is large.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    let mut score = post;

    // Smooth polynomial waste penalty: dead space hurts more as it grows
    score += 6.0 * post_norm * post_norm * cap;

    // Tight fits rewarded, scaled by stream progress (early on, keep bins flexible)
    let tightness = 1.0 - post_norm;
    score -= 30.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Non-linear coupling: small post_residual relative to next item is valuable
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - gap / cap).powi(3);
        } else {
            score += 4.0 * (-gap / cap).powi(2) * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Prefer bins below mean residual early (balance load), above later (fill up)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += (1.0 - 2.0 * progress) * 8.0 * dev;

    // Many open bins: encourage consolidation
    score += 0.6 * open_bins_count as f64 * post_norm;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over capacity fractions.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let res_class = post_residual % 10; // fine-grained harmonic class
    let quarter = (post_residual * 4) / bin_capacity; // which quarter of capacity the leftover sits in

    // Dead-space penalty: leftover that no future item (min size 1..) can pair with is waste.
    // Penalize tiny leftovers strongly (unusable slivers) but reward perfect closures.
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 5 {
        score += 12.0; // sliver dead space
    }

    // Modulo-class bonus: leftover in "friendly" classes (multiples of 5/10) pairs better.
    if res_class == 0 {
        score -= 6.0;
    } else if res_class == 5 {
        score -= 3.0;
    } else {
        score += res_class as f64 * 0.4;
    }

    // Quarter coupling: mid-range leftovers (quarter 1-2) are the most reusable;
    // quarter 0 (nearly full bin) is fine; quarter 3 (large leftover) wastes a bin slot.
    match quarter {
        0 => score -= 4.0,
        1 => score -= 8.0,
        2 => score -= 6.0,
        _ => score += 2.0,
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // harmonic class match between next item and post residual
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 10.0;
            }
            score -= (next_item_size as f64) * 0.15;
        } else {
            // next item cannot use this bin anyway; slight penalty for stranding space
            score += (next_item_size as f64 - post) * 0.05;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced late in the stream or when bins are crowded
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap_f + open_bins_count as f64 * 5.0 - progress * 10.0;
        // if mean residual across open bins is small, open bins are nearly full anyway
        score -= mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Strict dead-space avoidance: small nonzero gaps are unusable by future items
    // (min item size 1, but realistically gaps < ~10 are dead weight). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item / cap;
    score -= 12.0 * fill * fill;

    // Last-chance bin pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += 0.4 * open_bins_count as f64;

    // New-bin candidate: empty bin should score worse than a decent existing fit,
    // but better than a terrible fit. Base it on mean residual of open bins.
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 0.3 * mean_residual;
        // If next item is large and current item is small, opening fresh may be wise.
        if next_item_size as f64 > item + 30.0 {
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && (next_item_size as f64 - post).abs() < 1.0 {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item cannot use the leftover gap -> dead space confirmed
        score += 6.0;
    }

    // Slight preference for filling bins earlier in the stream (keep flexibility later).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - progress) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), slightly super-linear penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item (chained packing), penalize near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0); // perfect chain gets full -40, looser chain less
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.5; // near-miss penalty: dead space blocks the lookahead item
        }
    }

    // Reward filling bins close to mean residual usage (keep residuals homogeneous
    // so future items have many fitting targets).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large relative to the residual and existing bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 2.0);
        let largeness = item_size as f64 / bin_capacity as f64;
        // Penalize new bin by default; discount the penalty when bins are crowded
        // and the item is big (poor fit likely elsewhere).
        score += 60.0 * (1.0 - 0.6 * crowding * largeness);
        // If the next item would chain perfectly into a fresh bin, soften slightly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early in the stream, be more willing to open bins (diversification);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) superlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, keep flexibility.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            // Waste that cannot fit the next item is dead space.
            score += 8.0 * (post_residual as f64 / (next_item_size as f64).max(1.0));
        }
        // Perfect pairing: item + next item exactly fill the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Near the end of the stream: fill bins aggressively.
        score -= 10.0;
    }

    // Time horizon: early on, prefer spreading into new bins (keep options);
    // later, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late unless item is large.
        let early_bias = 1.0 - progress;
        score += 12.0 * progress - 6.0 * early_bias;
        if item_size > bin_capacity / 2 {
            score -= 5.0; // big items start fresh bins happily
        }
    } else {
        // Prefer bins below mean residual (looser bins absorb odd sizes),
        // penalize dumping into already-tight bins unless it's a tight fit.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
        // Consolidation pressure grows over time.
        score -= 10.0 * progress;
    }

    // Penalize opening too many bins when many are already open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), non-linear polynomial coupling
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth progress coupling: late in stream, waste is costlier
    score += 8.0 * norm_pr * (0.5 + progress);

    // Reward good fit relative to item size (relative slack)
    score -= 6.0 * (1.0 - pr / (item_size as f64 + pr)).powi(2) * item_size as f64 * 0.1;

    // Last chance bin: strong bonus to use it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // If next item fits exactly in post_residual, reward leaving a perfect slot
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            // post_residual too small for next item: dead space penalty grows with progress
            score += 6.0 * (pr / cap) * (0.3 + 0.7 * progress);
        }
    }

    // Mean residual coupling: penalize bins far from mean residual (keeps flexibility)
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: neutral-ish baseline, slightly penalized so it's only chosen
    // when open bins fit poorly (large post_residual elsewhere dominates)
    if bin_residual == bin_capacity {
        score = 45.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality classes
    // class 0: perfect fit (0), class 1: tiny unusable (1..=5), class 2: small (6..=15), class 3: medium (16..=30), class 4: large reusable
    let class = if post_residual == 0 { 0u32 }
        else if post_residual <= 5 { 1 }
        else if post_residual <= 15 { 2 }
        else if post_residual <= 30 { 3 }
        else { 4 };

    score += match class {
        0 => -40.0,
        1 => 25.0,
        2 => 8.0,
        3 => -2.0,
        _ => -6.0,
    };

    // Harmonic residue: post_residual mod 10 — residues near multiples of 10 are reusable by common sizes
    let harm = (post_residual % 10) as f64;
    score += 1.5 * harm;

    // Lookahead coupling: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.05 * next_item_size as f64;
        } else if post_residual >= 10 {
            score += 6.0; // dead space likely for next item
        }
        // exact harmonic pairing: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins: closeness of fill fraction to harmonic fractions
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // New-bin candidate: neutral-ish, penalize when good fits exist
    if bin_residual == bin_capacity {
        let base = 55.0
            - 0.3 * open_bins_count as f64
            - 0.2 * mean_residual
            + 0.3 * item_size as f64;
        score += base;
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            score += 15.0; // don't open new bin if current bin serves lookahead too
        }
    }

    // Stream progression: be pickier early, greedier late
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }

    // Gaps that can still hold the smallest future item are less bad.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: reward residual that accommodates next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bins pressure: mild penalty per open bin to encourage consolidation.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when the item fits poorly
    // in this bin relative to capacity, or residual is already fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by consolidation pressure.
        score += 30.0 + 1.5 * open_bins_count as f64;
        if item_size >= 70 {
            score -= 20.0; // big items start fresh bins happily
        }
    } else {
        // Penalize placing into a bin whose residual is much larger than item
        // (wasteful fill) unless it's the last fitting bin.
        if item_size < bin_residual / 3 && fitting_bins_count > 1 {
            score += 10.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's an outlier; prefer to finish it off.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.5 * diff;
    }

    // Slight late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear penalty.
    let pr = post_residual as f64;
    score += 0.35 * (pr / 10.0).powi(2);

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact chain match is highly desirable.
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 12.0; // perfect 2-step match
            }
        } else {
            // Next item cannot follow here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    } else {
        // Last item: purely minimize waste.
        score += 0.5 * pr;
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when current fits are all poor.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.4 * item_size as f64;
        // Late in the stream, opening a new bin is cheaper than fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If next item is large and this item nearly empties the bin, new bin is fine.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 15 {
            score -= 15.0;
        }
    }

    // Penalize leaving dead space below the minimum item size (unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (wasted space is the core cost).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 60.0;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a moderately large gap
            // that will become dead space unless another item fills it.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits even more.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when no open bin is a good home (large post_residual everywhere) or the
    // stream is young and we want to build a diverse pool.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_waste = mean_residual / open_bins_count.max(1) as f64;
        // Penalize new bins when existing bins have decent usable residuals.
        score += 25.0 + avg_waste * 0.5;
        // Early in the stream, be slightly more willing to open bins.
        score -= 20.0 * (1.0 - progress);
        // If the item would leave a big gap in any open bin anyway, opening is ok.
        if post_residual > item_size {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (i.e., already fairly full) to keep many small gaps from accumulating.
    let gap_vs_mean = mean_residual - bin_residual as f64;
    score += gap_vs_mean * 0.15;

    // Late in the stream, be more conservative: avoid opening bins and
    // prioritize finishing existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, with a non-linear (quadratic) coupling to stream progress.
    // Early on, tight fills matter less; late in the stream, dead space is costly.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Smooth non-linear interaction: post_residual vs mean residual deviation.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // Reward tight fits (small post_residual) with a saturating non-linear bonus.
    score -= 20.0 * (-norm_pr * 4.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize leaving a residual that exactly fits the next item poorly
    // (reward if next item fits well into the post residual).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - ((pr - nx) / cap).abs();
            score -= 6.0 * fit_quality * fit_quality;
        } else {
            // Next item cannot fit here; slight penalty scaled by how much it overshoots.
            let over = (nx - pr) / cap;
            score += 4.0 * over * over;
        }
    }

    // Mild penalty for proliferation of open bins, smoothed non-linearly.
    score += (open_bins_count as f64).ln_1p() * 2.0 * (1.0 - progress);

    // New-bin candidate handling: make an empty bin unattractive unless residuals are all tight.
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap);
        score += 10.0 + 20.0 * (1.0 - avg_tightness).powi(2) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes
    let post = post_residual;
    let class = post % 10;
    // Residuals that are "dead space" (small, hard to fill) get penalized
    if post > 0 && post < 10 {
        score += 12.0 * (10 - post) as f64;
    }
    // Residuals that are multiples of 10 are harmonically reusable
    if class == 0 {
        score -= 6.0;
    } else if class <= 3 {
        score += 4.0; // awkward sliver
    }

    // Integer-division threshold: can post_residual hold a "half-class" (>=25)?
    if post >= 25 {
        score -= 5.0;
    }

    // Lookahead coupling: does the next item fit the post residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0; // perfect harmonic match
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            score -= 8.0 - (slack as f64).min(8.0) * 0.5;
            // harmonic class match between next item and post residual
            if post % 10 == next_item_size % 10 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; penalize if we waste a large residual
            score += 2.0;
        }
    }

    // Last-chance bonus: only this bin fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits (item much smaller than residuals).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins slightly, more early when packing density matters
        score += 18.0 + 10.0 * (1.0 - progress);
        // but if item is large relative to mean residual, existing bins are bad -> soften
        let mean_r = mean_residual;
        if mean_r > 0.0 && (item_size as f64) > mean_r * 0.9 {
            score -= 25.0;
        }
    } else {
        // Tight fit reward: item fills most of the bin
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fill;
        // Exact fill
        if post == 0 {
            score -= 15.0;
        }
        // Avoid fragmenting many open bins when one would do
        score += (open_bins_count as f64).sqrt() * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small gaps (< 10) are nearly unusable since items >= 1
    // but typical items are larger; penalize hard in the "unusable" band.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residual that can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual below mean (tighter bins) to preserve large gaps.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: make it unattractive unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fills (dead space penalized super-linearly).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        score += 0.35 * pr * pr / bin_capacity as f64;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            // Reward tight coupling: post_residual == next_item_size is ideal.
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            // Extra bonus if the next item fills the bin completely afterwards.
            if post_residual == next_item_size {
                score -= 80.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty proportional to leftover.
            score += 0.15 * (post_residual as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter (smaller residual) than average.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Allow new bin early in the stream or when lookahead suggests a large pairing.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 > bin_capacity as f64 {
            score -= 100.0;
        }
        if progress < 0.1 {
            score -= 40.0;
        }
    }

    // Slight preference for bins with less absolute residual among comparable fits.
    score += 0.05 * bin_residual as f64;

    // Late-stream consolidation: tighten packing as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_residual as f64 - post_residual as f64) / item_size.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 2.5 * fit_ratio * bin_residual as f64;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // When multiple bins fit, prefer fuller ones (smaller residual).
        score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 0.2 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > item_size as f64 * 1.5 {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // Early in stream: encourage compact packing (prefer existing bins).
    // Late in stream: allow opening new bins when fit is poor.
    if progress < 0.5 {
        score += 3.0 * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin should only win when the fit
    // into existing bins is bad (large post_residual or no real fit).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0 + 10.0 * (1.0 - progress);
        // If no existing bin fits tightly, new bin becomes attractive:
        // post_residual here is large (capacity - item), so reduce penalty
        // when item is large relative to capacity.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Opening new bin is fine when it would leave a useful residual
        // close to mean_residual of open bins (balanced state).
        if (post_residual as f64 - mean_residual).abs() < 10.0 {
            score -= 8.0;
        }
    }

    // Slight preference for bins whose residual is close to mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let base = pr_norm.powf(1.0 + 1.5 * progress);

    // Penalize dead space more as stream progresses (less chance to reuse it).
    let mut score = base * (1.0 + 2.0 * progress * pr_norm);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    score -= (1.0 - pr_norm).powi(2) * 2.5;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = (pr - nxt) / cap;
            score -= 1.5 * (1.0 - snug).powi(2);
        } else {
            score += 0.5 * (nxt - pr) / cap;
        }
    }

    // Slight preference for keeping bins balanced relative to mean residual.
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Mild bonus for new bin early in the stream, penalty later.
    if bin_residual == bin_capacity {
        score += 0.8 - 1.6 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into modulo-10 buckets
    let post_class = (post_residual % 10) as f64;
    let post_quotient = (post_residual / 10) as f64;

    // Penalize leftovers that fall in "dead" classes (1..9 mod 10 cannot hold
    // typical items unless large); reward exact zero leftover strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows with unusable remainder within the class
        let dead = if post_class >= 1.0 && post_class <= 9.0 {
            10.0 - post_class
        } else {
            0.0
        };
        score += dead * 2.5;

        // Reward leftovers that can still hold a mid-size item (>= 20)
        if post_residual >= 20 {
            score -= 8.0 + post_quotient;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            let next_class = (next_post % 10) as f64;
            if next_post == 0 {
                score -= 300.0;
            } else if next_class == 0.0 {
                score -= 25.0;
            } else if next_class >= 1.0 && next_class <= 9.0 {
                score += (10.0 - next_class) * 1.5;
            }
        } else {
            // Next item won't fit here: mild penalty for hoarding space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is bad.
    // Empty-bin call has bin_residual == bin_capacity => post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 60.0 + (post_residual as f64) * 0.5;
        // If this is the last item, opening a bin is fine
        if step_index + 1 >= total_items {
            score -= 200.0;
        }
    }

    // Late in stream: consolidate, prefer tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Slight preference for bins below mean residual (balance spreading)
    score += ((post_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is excellent
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += 2.0 * open_bins_count as f64;

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= post_residual + 5 {
        score += 15.0; // next item almost fits, dead space likely
    }

    // Mean residual coupling: avoid bins far from the mean when mean is small (waste elsewhere).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate: neutral-ish baseline, only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 55.0 + 1.5 * open_bins_count as f64;
        // But allow fresh bin late in stream if item is huge and fits would leave tiny gaps.
        if post_residual < 10 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Exact match for the next item is ideal.
            score -= 150.0 * (-slack / 20.0).exp();
            // Penalize large leftover that still "fits" everything (wasteful openness).
            score += 0.3 * slack;
        } else {
            // Post-residual too small for next item: dead space unless tiny.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead.min(60.0);
            if post_residual < 10 {
                score -= 50.0; // tiny dead space is fine, bin is effectively closed
            }
        }
    }

    // Compare against mean residual: prefer using bins with larger residuals first
    // (best-fit-ish), penalize dipping far below the mean residual.
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: prefer it only when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 60.0;
        // But if current fit is bad and next item is large, opening fresh is attractive.
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 10 {
            score -= 70.0;
        }
        // Early in stream, opening bins is cheap; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
    }

    // Mild preference to fill bins when many are open (reduce fragmentation).
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, weight residual more strongly
    let progress_weight = 1.0 + 1.5 * progress * progress;
    score *= progress_weight;

    // Interaction: post-residual vs mean residual deviation (smooth cubic coupling)
    let dev = (pr - mean_residual) / cap;
    score += 20.0 * dev * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: reward if next item fits into post-residual (smooth quadratic match)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap) * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // penalize leaving residual too small for next item, scaled by dead space
        let dead = pr / cap;
        score += 10.0 * dead * dead;
    }

    // Mild penalty for proliferating bins relative to stream length
    score += 0.5 * (open_bins_count as f64).sqrt();

    // New-bin candidate: make it attractive only when item is large or residual waste is high
    if bin_residual == bin_capacity {
        score -= 30.0 * item_size as f64 / cap + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead space" classes are penalized; large reusable leftovers rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit is golden
    } else {
        // integer-division thresholds on post_residual
        let class = pr / 10; // decade class 0..=9
        match class {
            0 => score += 25.0,        // 1..=9: nearly dead space
            1 => score += 12.0,        // 10..=19
            2 => score += 4.0,         // 20..=29
            3 => score -= 2.0,         // 30..=39: reusable
            4 => score -= 6.0,
            5 => score -= 8.0,
            _ => score -= 10.0,        // >=60: very flexible
        }
        // modulo arithmetic: residuals that are multiples of 5 pair well with
        // typical item sizes; odd tiny residuals are waste-prone
        if pr % 5 == 0 { score -= 3.0; }
        if pr % 2 == 1 && pr < 20 { score += 5.0; }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic-style decay of lookahead value
            score -= 25.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional
            // to how "wasted" the residual is for the lookahead
            score += ((next_item_size - pr) as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline, slightly penalized so we
    // prefer good existing fits, but preferred over creating tiny dead space.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64) * 2.0
              - (step_index as f64 / total_items.max(1) as f64) * 15.0;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 10.0; // big items coming: fresh bin useful
        }
    }

    // Mild pressure toward consolidating residual mass
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // A residual gap is "dead" if no plausible future item (min size 1..10)
        // could use it well; weight gaps below 10 extremely heavily.
        if post_residual < 10 {
            score += 50.0 * (10.0 - post_residual as f64);
        } else {
            // Smooth super-linear penalty on wasted space.
            let r = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * r * r * bin_capacity as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits relative to the item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if no existing bin fits well (post_residual tiny everywhere),
        // the base post_residual (= capacity) already makes it unattractive.
        // Slight relief late in the stream when consolidation matters less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    } else {
        score += 1.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item can't use the leftover: leftover is likely dead space.
        score += 6.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual bins are "more full", use them).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // --- 2-step lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            // perfect two-item packing: strongly reward
            score -= 60.0 + 0.5 * (1.0 - progress);
        } else if (post_residual as f64 - nxt).abs() <= 2.0 {
            // near-perfect pairing
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward proportional to closeness
            let slack = post_residual as f64 - nxt;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize proportionally to waste
            let waste = nxt - post_residual as f64;
            score += 0.6 * waste;
        }
    } else {
        // last item: just prefer tightest fit (post_residual already does this)
        score += 0.0;
    }

    // --- last-chance bonus: only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // --- mean residual anchoring: prefer bins whose residual deviates from mean ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // --- new-bin candidate handling ---
    if is_new_bin {
        // opening a new bin is attractive when few bins fit or item is large,
        // unattractive when good fits exist elsewhere
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 18.0 * fit_pressure - 10.0 * large_item + 5.0 * progress;
    }

    // --- mild preference for tighter residual fills across many open bins ---
    if open_bins_count > 4 {
        score -= 0.05 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more strongly as item grows.
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Penalize large dead space in bins that are already fairly empty.
    if post_residual < 10 {
        score -= 25.0; // near-perfect closure bonus
    } else if post_residual > 60 {
        score += 15.0; // wasteful placement
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward leaving usable space for the next item
            score -= (next_item_size as f64 / post_residual.max(1) as f64) * 8.0;
        } else {
            // penalize leaving space the next item cannot use
            score += ((next_item_size - post_residual) as f64 / bin_capacity as f64) * 10.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    let mean_resid_norm = mean_residual / bin_capacity as f64;
    if mean_resid_norm > 0.5 {
        score += (mean_resid_norm - 0.5) * 20.0;
    } else {
        score -= (0.5 - mean_resid_norm) * 10.0;
    }

    // Time horizon: early in stream, be conservative (favor new bins for
    // flexibility); late in stream, squeeze everything into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0;

    // New-bin candidate handling: empty bin gets a base cost that grows with
    // open_bins_count, so it is only chosen when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64) * 2.0;
    }

    // Mild penalty for bins that are nearly full already (avoid trivial moves
    // when better consolidation exists elsewhere).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += fill * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping over progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth coupling: penalize large post_residual more as stream progresses
    score += 30.0 * pr_norm * pr_norm * (0.5 + progress);

    // Dead-space penalty: post_residual too small for typical future items
    if pr > 0.0 {
        let dead = ((pr as i64 - next_item_size as i64).unsigned_abs()) as f64;
        score += 0.15 * (dead / cap) * (1.0 - progress);
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 12.0 * snug * snug;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr_norm);
    }

    // Mild pull toward mean residual state
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "dead zones"
    // (too small for typical small items) should be penalized.
    let dead_low = 1u32;
    let dead_high = 9u32;
    if post_residual >= dead_low && post_residual <= dead_high {
        score += 18.0 * (1.0 - (post_residual as f64) / (dead_high as f64 + 1.0));
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Integer-division thresholds: leftover that is a multiple of common small
    // item sizes is reusable; treat it as more valuable.
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0);
    if reusable && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves a further residual: mild reward scaled
            // by how tight the chain is.
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - chain_tight / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            // to how far off it is.
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (gap / 20.0).min(3.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: an empty bin should only win when the current fit is
    // bad or the stream is early with few bins open. Otherwise push it back.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += 14.0;                       // base inertia against new bins
        score -= 30.0 * (1.0 - fit_quality); // allow it for very poor fits
        score -= 10.0 * progress;            // more willing later? no: keep bins tight early
        if open_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
    }

    // Mean-residual context: when average leftover across open bins is large,
    // prefer consolidating into fuller bins (higher residual than mean).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Prefer bins with residuals in harmonic alignment with item size classes
    // (residual mod item_size small => future splits land cleanly).
    if item_size > 0 && post_residual > 0 {
        let m = post_residual % item_size;
        if m == 0 {
            score -= 5.0;
        } else if m <= 3 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically small gaps) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward using bins whose residual tightly matches the item.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless
    // the fit is genuinely good.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive when
    // the item leaves a large, reusable residual and no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin by default...
        score += 25.0 + 2.0 * open_bins_count as f64;
        // ...but reward it when the leftover space is large and likely usable.
        if post_residual >= 50 {
            score -= 45.0;
        }
        // If the next item can fit in the fresh bin's residual, opening is good.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Lookahead: if this placement leaves room for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Creating a gap that the next item cannot use is dead space.
        score += 6.0;
    }

    // Slight preference for filling fuller bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness.abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leave exactly 0 or exactly enough for the next item.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 30.0; // perfect two-item chain
        } else if post_residual > next_item_size {
            // post residual can host the next item: mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot follow here: penalize dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Reward tight fits relative to bin capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Compare against mean residual: placing in a bin with residual far above mean
    // wastes the large bins; prefer bins whose residual is close to the item.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let base_penalty = 40.0;
        let large_item_bonus = if item_size >= bin_capacity / 2 { 15.0 } else { 0.0 };
        let scarcity_bonus = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += base_penalty - large_item_bonus - scarcity_bonus;
    }

    // Slight early-stream preference to consolidate into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.02 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post-residual gets big discount.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 {
        let unusable = (post_residual as f64 / (bin_capacity as f64 - 9.0)).powi(3);
        score += 80.0 * unusable;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 45.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave bad residue.
    if bin_residual == bin_capacity {
        score += 70.0;
        // But if lookahead item is large and this bin would be left very small, opening new bin is fine.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score -= 30.0;
        }
        // Early in stream, allow exploration of new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: reward leaving post_residual that next item can exactly/nearly fill.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.25 * gap;
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score += 0.4 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty for bin proliferation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, keep residuals flexible (penalize small residuals less),
    // later, reward tight packing more aggressively.
    let norm_pr = pr / cap;
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;

    // Polynomial weight that grows with progress: tight fits (small norm_pr) get larger discounts late.
    let tightness = 1.0 - norm_pr; // 0..1, higher = tighter fit
    let coupling = tightness * (1.0 + 2.0 * progress + 3.0 * prog_sq + 2.0 * prog_cu);
    score -= 12.0 * coupling;

    // Dead-space penalty: residuals too small for typical items are worse later in stream.
    let dead = if pr > 0.0 { (cap / pr).ln() } else { 6.0 };
    score += 4.0 * dead * (0.3 + progress);

    // Lookahead: bonus if next item fits into post-residual (smoothly weighted).
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let size_ratio = next_item_size as f64 / cap;
        score -= 8.0 * fits_next * (1.0 - size_ratio) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight penalty for spreading across many open bins when mean residual is high.
    let mean_norm = mean_residual / cap;
    score += 0.05 * open_bins_count as f64 * mean_norm * (1.0 - progress);

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 3.0 * mean_norm * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Residuals that are "wasted" (below the
    // smallest item class) should be heavily penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: leftover smaller than the minimum item size is dead.
    if post_residual < 10 {
        score += 60.0 - post * 4.0; // steep penalty for unusable slivers
    }

    // Integer-division thresholds: reward residuals divisible into useful classes.
    // Class A: post_residual in [10, 30) — still fits small items well.
    // Class B: post_residual in [30, 60) — moderate utility.
    // Class C: post_residual >= 60 — high utility, keep it.
    if post_residual >= 60 {
        score -= 25.0;
    } else if post_residual >= 30 {
        score -= 10.0;
    } else if post_residual >= 10 {
        score -= 5.0;
    }

    // Modulo arithmetic on post_residual: exact "harmonic" leftovers
    // (multiples of 25, i.e. quarter-capacity harmonics) are versatile.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Residuals that are multiples of 10 align with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (perfect chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 18.0 + (slack as f64).min(30.0) * 0.2;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty proportional to overshoot.
        score += ((next_item_size - post_residual) as f64) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // rather than opening a new bin (unless it would create dead space).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when the item fits poorly in
    // existing bins; penalize new bins when mean residual across open bins
    // is still large.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual.max(0.0);
        score += 15.0 + mean_r * 0.3;
        // Late in the stream, discourage hoarding open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // If item nearly fills a fresh bin perfectly, allow it.
        if item_size as f64 >= cap * 0.9 {
            score -= 30.0;
        }
    }

    // Prefer tighter existing bins when several fit: subtract for small
    // relative waste (item fills a large fraction of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Last-chance bonus: only bin that fits avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open bins pressure: prefer reusing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if next item fits into post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: avoid making bin far below mean residual.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Prefer filling bins that are already partly used (residual below capacity).
    if bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            let diff = (pr - nxt).abs();
            // Perfect chain: next item exactly fills remaining space.
            if diff == 0.0 {
                score -= 40.0;
            } else if diff <= 3.0 {
                score -= 18.0;
            } else {
                // Mild reward proportional to closeness of chain fit.
                score -= 12.0 * (1.0 - diff / bin_capacity as f64);
            }
            // Penalize leaving residuals that no small item can use later (dead space).
            if post_residual < 10 {
                score += 15.0;
            }
        } else {
            // Next item cannot chain here: penalize relative to how much would be stranded.
            score += 8.0 + 0.3 * (nxt - pr);
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Prefer bins that end up tighter than average (consolidating space).
    if post_residual as f64 > mean_residual {
        score += 0.4 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Discourage opening new bins when plenty of open bins can fit the item.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Early in stream, be more willing to spread items (keep flexibility);
    // late in stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}
